static void test_fdb_scale_up(void)
{
    fdb_kv_set_default(&test_kvdb);

    static const struct test_kv old_kv_tbl[] = {
        {"kv0", "0", TEST_KV_VALUE_LEN, 0, 0, 1},
        {"kv1", "1", TEST_KV_VALUE_LEN, 0, 0, 1},
