    /* kv4: sector2, kv5: sector3, kv6: sector3, kv7: sector3 */
    test_save_fdb_by_kvs(new_kv_tbl, FDB_ARRAY_SIZE(new_kv_tbl));
    /* kv4: sector4, kv5: sector4, kv6: sector4, kv7: sector5 */
    test_save_fdb_by_kvs(new_kv_tbl, FDB_ARRAY_SIZE(new_kv_tbl));
    /* check new data */
    test_check_fdb_by_kvs(new_kv_tbl, FDB_ARRAY_SIZE(new_kv_tbl));
    /* check old data */
    test_check_fdb_by_kvs(old_kv_tbl, FDB_ARRAY_SIZE(old_kv_tbl));
}

static void test_fdb_kvdb_set_default(void)
{
    test_assert_true(fdb_kv_set_default(&test_kvdb) == FDB_NO_ERR);
}


static int utest_tc_init(void)
{
    dir_delete(TEST_TS_PART_NAME);
    return 0;
}

static int utest_tc_cleanup(void)
{
    if (test_kvdb.parent.init_ok)
    {
        fdb_kv_set_default(&test_kvdb);
        fdb_kvdb_deinit(&test_kvdb);
    }

    return 0;
}

static void testcase(void)
{
    TEST_RUN(test_fdb_kvdb_init);
    TEST_RUN(test_fdb_kvdb_init_check);
    TEST_RUN(test_fdb_create_kv_blob);
    TEST_RUN(test_fdb_change_kv_blob);
    TEST_RUN(test_fdb_del_kv_blob);
    TEST_RUN(test_fdb_create_kv);
    TEST_RUN(test_fdb_change_kv);
    TEST_RUN(test_fdb_del_kv);
    TEST_RUN(test_fdb_gc);
    TEST_RUN(test_fdb_gc2);
    TEST_RUN(test_fdb_scale_up);
    TEST_RUN(test_fdb_kvdb_set_default);
