/*
 * Copyright (c) 2020, Armink, <armink.ztl@gmail.com>
 *
 * SPDX-License-Identifier: Apache-2.0
 */

/**
 * @file
 * @brief TSDB testcases.
 */

#include "test_helpers.h"
#include <flashdb.h>
#include <fdb_low_lvl.h>
#include <stdio.h>
#include <stdlib.h>

#if defined(FDB_USING_TSDB)

#define TEST_TS_PART_NAME             "fdb_tsdb1"
#define TEST_TS_COUNT_BASE             256
#define TEST_TS_USER_STATUS1_COUNT    (TEST_TS_COUNT_BASE/2)
#define TEST_TS_DELETED_COUNT         (TEST_TS_COUNT_BASE - TEST_TS_USER_STATUS1_COUNT)
#define TEST_SECTOR_SIZE              4096
#define TEST_TIME_STEP                2

/* Dynamically compute how many variable-size TSLs (blob = int) fit in one sector.
 * This ensures test_fdb_tsl_iter_by_time_1 always spans exactly TEST_ITER1_SECTORS
 * (3 < N < sizeof(test_secs_info)) physical sectors for any FDB_WRITE_GRAN value,
 * avoiding both the "array overflow" (gran=64) and "rollover" (gran=128) failures. */
#define _TSIL_TSL_STATUS_SZ  FDB_STATUS_TABLE_SIZE(FDB_TSL_STATUS_NUM)
#define _TSIL_IDX_BASE_SZ    (_TSIL_TSL_STATUS_SZ + sizeof(fdb_time_t) + sizeof(uint32_t) * 2)
#define _TSIL_IDX_DATA_SZ    FDB_WG_ALIGN(_TSIL_IDX_BASE_SZ)
#define _TSIL_U32_ALIGN_SZ   FDB_WG_ALIGN(sizeof(uint32_t))
#define _TSIL_TIME_ALIGN_SZ  FDB_WG_ALIGN(sizeof(fdb_time_t))
#define _TSIL_SEC_HDR_RAW_SZ (FDB_STORE_STATUS_TABLE_SIZE + _TSIL_U32_ALIGN_SZ + _TSIL_TIME_ALIGN_SZ \
                              + 2 * (_TSIL_TIME_ALIGN_SZ + _TSIL_U32_ALIGN_SZ + _TSIL_TSL_STATUS_SZ) \
                              + sizeof(uint32_t))
#define _TSIL_SEC_HDR_SZ     FDB_WG_ALIGN(_TSIL_SEC_HDR_RAW_SZ)
#define _TSIL_PER_SECTOR     ((TEST_SECTOR_SIZE - _TSIL_SEC_HDR_SZ) \
                              / (_TSIL_IDX_DATA_SZ + FDB_WG_ALIGN(sizeof(int))))
/* Fill 5 sectors — always > 2 (required by assertions) and < 10 (test_secs_info size) */
#define TEST_ITER1_SECTORS   5
#define TEST_ITER1_COUNT     (TEST_ITER1_SECTORS * _TSIL_PER_SECTOR)

/* TSLs per sector when blob is logbuf-sized string */
#define _TSIL_LOGBUF_ALIGN_SZ  FDB_WG_ALIGN(sizeof(logbuf))
#define _TSIL_PER_SECTOR_STR   ((TEST_SECTOR_SIZE - _TSIL_SEC_HDR_SZ) \
                                / (_TSIL_IDX_DATA_SZ + _TSIL_LOGBUF_ALIGN_SZ))

/* Cap at 256 to avoid timeout on small write granularities (e.g. gran=1/8/32),
 * while still being dynamic enough to avoid ring-buffer wrap-around on large
 * granularities (e.g. gran=64/128/256). */
#define TEST_TS_COUNT          ((_TSIL_PER_SECTOR_STR * 14) < TEST_TS_COUNT_BASE \
                                ? (_TSIL_PER_SECTOR_STR * 14) : TEST_TS_COUNT_BASE)


struct test_tls_data {
    int data;
    fdb_time_t time;
    uint32_t addr;
    slist_t list;
};

struct test_tls_sector {
    uint32_t addr;                               /**< sector start address */
    fdb_time_t start_time;                       /**< the first start node's timestamp, 0x7FFFFFFF: unused */
    fdb_time_t end_time;
};

static char logbuf[10];
static struct fdb_tsdb test_tsdb;
static int cur_times = 0;
static struct test_tls_sector test_secs_info[10];
static fdb_time_t test_db_start_time = 0x7FFFFFFF, test_db_end_time = 0;

static fdb_time_t get_time(void)
{
    cur_times += TEST_TIME_STEP;
    return cur_times;
}

static void test_fdb_tsdb_init_ex(void)
{
    if (access(TEST_TS_PART_NAME, 0) < 0)
    {
        mkdir(TEST_TS_PART_NAME, 0777);
    }

    uint32_t sec_size = TEST_SECTOR_SIZE, db_size = sec_size * 16;
    bool file_mode = true;

    memset(&test_tsdb, 0, sizeof(struct fdb_tsdb));
    fdb_tsdb_control((fdb_tsdb_t)&(test_tsdb), FDB_TSDB_CTRL_SET_SEC_SIZE, &sec_size);
    fdb_tsdb_control((fdb_tsdb_t)&(test_tsdb), FDB_TSDB_CTRL_SET_FILE_MODE, &file_mode);
    fdb_tsdb_control((fdb_tsdb_t)&(test_tsdb), FDB_TSDB_CTRL_SET_MAX_SIZE, &db_size);

    test_assert_true(fdb_tsdb_init(&test_tsdb, "test_ts", TEST_TS_PART_NAME, get_time, 128, NULL) == FDB_NO_ERR);
}

static void test_fdb_tsdb_deinit(void)
{
    test_assert_true(fdb_tsdb_deinit(&test_tsdb) == FDB_NO_ERR);
}

/* check reboot status */
static void fdb_reboot(void)
{
    test_fdb_tsdb_deinit();
    test_fdb_tsdb_init_ex();
}

static void test_fdb_tsl_append(void)
{
    struct fdb_blob blob;
    int i;

    for (i = 0; i < TEST_TS_COUNT * TEST_TIME_STEP; ) {
        i += TEST_TIME_STEP;
        snprintf(logbuf, sizeof(logbuf), "%d", i);
        test_assert_true(fdb_tsl_append(&test_tsdb, fdb_blob_make(&blob, logbuf, strnlen(logbuf, sizeof(logbuf)))) == FDB_NO_ERR);
    }
}

static bool test_fdb_tsl_iter_cb(fdb_tsl_t tsl, void *arg)
{
    struct fdb_blob blob;
    char data[sizeof(logbuf)] = {0};
    size_t read_len;

    fdb_blob_make(&blob, data, tsl->log_len);
    read_len = fdb_blob_read((fdb_db_t) &test_tsdb, fdb_tsl_to_blob(tsl, &blob));

    data[read_len] = '\0';

    if (arg == NULL) {
        test_assert_true(tsl->time == atoi(data));
    } else {
        test_assert_true(tsl->time == *((fdb_time_t *)arg));
    }

    return false;
}

static void test_fdb_tsl_iter(void)
{
    fdb_reboot();
    fdb_tsl_iter(&test_tsdb, test_fdb_tsl_iter_cb, NULL);
}

static void test_fdb_tsl_iter_by_time(void)
{
    fdb_time_t from = 0, to = TEST_TS_COUNT * TEST_TIME_STEP - 1;

    fdb_reboot();
    for (fdb_time_t cur = from; cur <= to; cur += TEST_TIME_STEP) {
        fdb_tsl_iter_by_time(&test_tsdb, cur, cur, test_fdb_tsl_iter_cb, &cur);
    }
    fdb_tsl_iter_by_time(&test_tsdb, from, to, test_fdb_tsl_iter_cb, NULL);
}

static void test_fdb_tsl_query_count(void)
{
    fdb_time_t from = 0, to = TEST_TS_COUNT * TEST_TIME_STEP;
    uint32_t count;

    fdb_reboot();
    count = fdb_tsl_query_count(&test_tsdb, from, to, FDB_TSL_WRITE);
    printf("query_count from=%d to=%d => %u, expected=%u\n",
               (int)from, (int)to, (unsigned)count, TEST_TS_COUNT);

    test_assert_true(count == TEST_TS_COUNT);
}

static bool est_fdb_tsl_set_status_cb(fdb_tsl_t tsl, void *arg)
{
	fdb_tsdb_t db = arg;

    if (tsl->time >= 0 && tsl->time <= TEST_TS_USER_STATUS1_COUNT * TEST_TIME_STEP) {
        test_assert_true(fdb_tsl_set_status(db, tsl, FDB_TSL_USER_STATUS1) == FDB_NO_ERR);
    } else {
        test_assert_true(fdb_tsl_set_status(db, tsl, FDB_TSL_DELETED) == FDB_NO_ERR);
    }

    return false;
}

static void test_fdb_tsl_set_status(void)
{
    fdb_time_t from = 0, to = TEST_TS_COUNT * TEST_TIME_STEP;

    fdb_reboot();
    fdb_tsl_iter_by_time(&test_tsdb, from, to, est_fdb_tsl_set_status_cb, &test_tsdb);

    test_assert_true(fdb_tsl_query_count(&test_tsdb, from, to, FDB_TSL_USER_STATUS1) == TEST_TS_USER_STATUS1_COUNT);
    test_assert_true(fdb_tsl_query_count(&test_tsdb, from, to, FDB_TSL_DELETED) == TEST_TS_DELETED_COUNT);
}

static bool test_fdb_tsl_clean_cb(fdb_tsl_t tsl, void *arg)
{
    size_t *count = arg;

    (*count) ++;

    return false;
}

static void test_fdb_tsl_clean(void)
{
    size_t count = 0;

    cur_times = 0;

    fdb_reboot();
    fdb_tsl_clean(&test_tsdb);
    fdb_tsl_iter(&test_tsdb, test_fdb_tsl_clean_cb, &count);
    test_assert_true(count == 0);

    fdb_reboot();
    fdb_tsl_iter(&test_tsdb, test_fdb_tsl_clean_cb, &count);

    test_assert_true(count == 0);
}

static int utest_tc_init(void)
{
    cur_times = 0;
    memset(&test_tsdb, 0, sizeof(struct fdb_tsdb));

    return 0;
}

static int utest_tc_cleanup(void)
{
    return 0;
}

static bool query_cb(fdb_tsl_t tsl, void *arg)
{
    struct fdb_blob blob;
    int data = 0;
    struct test_tls_data *node;
    slist_t *tsl_list = (slist_t *)arg;
    fdb_blob_read((fdb_db_t) &test_tsdb, fdb_tsl_to_blob(tsl, fdb_blob_make(&blob, &data, sizeof(data))));
    node = malloc(sizeof(struct test_tls_data));
    assert(node != NULL);

    node->data = data;
    node->time = tsl->time;
    slist_append(tsl_list,&node->list);
    return false;
}

static bool get_sector_info_cb(fdb_tsl_t tsl, void *arg)
{
    int i = tsl->addr.log / TEST_SECTOR_SIZE;

    if (i < sizeof(test_secs_info) / sizeof(test_secs_info[0])) {
        test_secs_info[i].addr = FDB_ALIGN_DOWN(tsl->addr.log, TEST_SECTOR_SIZE);
        if (test_secs_info[i].start_time > tsl->time) {
            test_secs_info[i].start_time = tsl->time;
        }
        if (test_secs_info[i].end_time < tsl->time) {
            test_secs_info[i].end_time = tsl->time;
        }
        if (test_db_start_time > tsl->time) {
            test_db_start_time = tsl->time;
        }
        if (test_db_end_time < tsl->time) {
            test_db_end_time = tsl->time;
        }
        return false;
    } else {
        return true;
    }
}

static void test_tsdb_data_by_time(fdb_time_t from, fdb_time_t to)
{
    slist_t tsl_list;
    slist_init(&tsl_list);
    fdb_time_t i, cur_time = from, valid_to = to, last_tsl_time;
    uint32_t tsl_num, j;

    if (from <= to) {
        if (from < test_db_start_time) {
            cur_time = test_db_start_time;
        }
        if (to > test_db_end_time) {
            valid_to = test_db_end_time;
        }
    } else {
        if (from > test_db_end_time) {
            cur_time = test_db_end_time;
        }
        if (to < test_db_start_time) {
            valid_to = test_db_start_time;
        }
    }

    fdb_tsl_iter_by_time(&test_tsdb, from, to, query_cb, &tsl_list);

    struct test_tls_data *tls;
    slist_t* node = NULL;

    tsl_num = slist_len(&tsl_list);
    /* check the tsl number */
    if (from <= to) {
        for (i = cur_time, j = 0; i <= valid_to; i++) {
            if (i % TEST_TIME_STEP == 0) {
                j++;
            }
        }
    } else {
        for (i = cur_time, j = 0; i >= valid_to; i--) {
            if (i % TEST_TIME_STEP == 0) {
                j++;
            }
        }
    }
    test_assert_true(tsl_num == j);
    /* check the tsl time */
    for (node = (&tsl_list)->next; node != NULL; node = node->next, free(tls))
    {
        tls = slist_entry(node, struct test_tls_data, list);
        if (from <= to) {
            test_assert_true(tls->time == FDB_ALIGN(cur_time, TEST_TIME_STEP));
            cur_time += TEST_TIME_STEP;
        } else {
            test_assert_true(tls->time == FDB_ALIGN_DOWN(cur_time, TEST_TIME_STEP));
            cur_time -= TEST_TIME_STEP;
        }
        last_tsl_time = tls->time;
    }

    if (tsl_num > 0) {
        /* check the last tsl */
        if (from <= to) {
            test_assert_true(last_tsl_time == FDB_ALIGN_DOWN(valid_to, TEST_TIME_STEP));
        } else {
            test_assert_true(last_tsl_time == FDB_ALIGN(valid_to, TEST_TIME_STEP));
        }
    }
}

static void test_fdb_tsl_sector_bound_test(int start_sec_index, int end_sec_index)
{
    test_tsdb_data_by_time(test_secs_info[start_sec_index].start_time - 1, test_secs_info[end_sec_index].end_time + 1);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].start_time - 1, test_secs_info[end_sec_index].end_time + 0);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].start_time - 1, test_secs_info[end_sec_index].end_time - 1);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].start_time + 0, test_secs_info[end_sec_index].end_time + 1);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].start_time + 0, test_secs_info[end_sec_index].end_time + 0);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].start_time + 0, test_secs_info[end_sec_index].end_time - 1);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].start_time + 1, test_secs_info[end_sec_index].end_time + 1);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].start_time + 1, test_secs_info[end_sec_index].end_time + 0);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].start_time + 1, test_secs_info[end_sec_index].end_time - 1);

    test_tsdb_data_by_time(test_secs_info[start_sec_index].end_time - 1, test_secs_info[end_sec_index].start_time + 1);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].end_time - 1, test_secs_info[end_sec_index].start_time + 0);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].end_time - 1, test_secs_info[end_sec_index].start_time - 1);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].end_time + 0, test_secs_info[end_sec_index].start_time + 1);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].end_time + 0, test_secs_info[end_sec_index].start_time + 0);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].end_time + 0, test_secs_info[end_sec_index].start_time - 1);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].end_time + 1, test_secs_info[end_sec_index].start_time + 1);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].end_time + 1, test_secs_info[end_sec_index].start_time + 0);
    test_tsdb_data_by_time(test_secs_info[start_sec_index].end_time + 1, test_secs_info[end_sec_index].start_time - 1);
}

static void test_fdb_tsl_iter_by_time_1(void)
{
    struct fdb_blob blob;
    int data, i;

    fdb_tsl_clean(&test_tsdb);
    /* make test data for more than 2 sectors.
     * TEST_ITER1_COUNT is computed from FDB_WRITE_GRAN so that exactly
     * TEST_ITER1_SECTORS physical sectors are used, regardless of write granularity. */
    for (data = 0; data < TEST_ITER1_COUNT; data++) {
        fdb_tsl_append(&test_tsdb, fdb_blob_make(&blob, &data, sizeof(data)));
    }

    fdb_reboot();

    /* init all test sectors info */
    for (i = 0; i < sizeof(test_secs_info) / sizeof(test_secs_info[0]); i++) {
        test_secs_info[i].addr = TEST_SECTOR_SIZE * i;
        test_secs_info[i].start_time = 0x7FFFFFFF;
        test_secs_info[i].end_time = 0;
    }
    /* reset global DB time range before scanning */
    test_db_start_time = 0x7FFFFFFF;
    test_db_end_time = 0;
    /* get the the sectors info by iterator */
    fdb_tsl_iter_by_time(&test_tsdb, 0, 0x7FFFFFFF, get_sector_info_cb, NULL);
    /* must found more than 2 sectors */
    test_assert_true(test_secs_info[2].start_time != 0x7FFFFFFF);
    /* check the database bound */
    test_tsdb_data_by_time(test_db_start_time - 1, test_db_end_time + 1);
    test_tsdb_data_by_time(test_db_start_time - 2, test_db_start_time - 1);
    test_tsdb_data_by_time(test_db_start_time - 1, test_db_start_time - 2);
    test_tsdb_data_by_time(test_db_end_time + 1, test_db_end_time + 2);
    test_tsdb_data_by_time(test_db_end_time + 2, test_db_end_time + 1);

    /* check 1st sector */
    test_tsdb_data_by_time(test_secs_info[0].start_time - 1, test_secs_info[0].end_time);
    test_tsdb_data_by_time(test_secs_info[0].start_time, test_secs_info[0].end_time);
    test_tsdb_data_by_time(test_secs_info[0].start_time, test_secs_info[0].end_time + 1);
    test_tsdb_data_by_time(test_secs_info[0].end_time + 1, test_secs_info[0].start_time);
    test_tsdb_data_by_time(test_secs_info[0].end_time, test_secs_info[0].start_time);
    test_tsdb_data_by_time(test_secs_info[0].end_time, test_secs_info[0].start_time - 1);

    /* check last sector */
    struct test_tls_sector *last_secs = NULL;
    for (i = 0; i < sizeof(test_secs_info) / sizeof(test_secs_info[0]); i++) {
        if (test_secs_info[i].end_time == 0) {
            last_secs = &test_secs_info[i];
            break;
        }
    }
    test_assert_true(i >= 3);
    test_assert_true(last_secs != NULL);
    test_tsdb_data_by_time(last_secs->start_time - 1, last_secs->end_time);
    test_tsdb_data_by_time(last_secs->start_time, last_secs->end_time);
    test_tsdb_data_by_time(last_secs->start_time, last_secs->end_time + 1);
    test_tsdb_data_by_time(last_secs->end_time + 1, last_secs->start_time);
    test_tsdb_data_by_time(last_secs->end_time, last_secs->start_time);
    test_tsdb_data_by_time(last_secs->end_time, last_secs->start_time - 1);

    /* check less then 1 sector */
    test_tsdb_data_by_time(test_secs_info[0].start_time + 1, test_secs_info[0].end_time - 1);
    test_tsdb_data_by_time(test_secs_info[0].end_time - 1, test_secs_info[0].start_time + 1);

    /* check equal 1 sector */
    test_tsdb_data_by_time(test_secs_info[0].start_time, test_secs_info[0].end_time);
    test_tsdb_data_by_time(test_secs_info[0].end_time, test_secs_info[0].start_time);

    /* check 1~2 sector */
    test_fdb_tsl_sector_bound_test(0, 0);
    test_fdb_tsl_sector_bound_test(0, 1);
    test_fdb_tsl_sector_bound_test(1, 0);
    test_fdb_tsl_sector_bound_test(1, 1);

    /* check more than 2 sectors */
    test_fdb_tsl_sector_bound_test(0, 2);
    test_fdb_tsl_sector_bound_test(2, 0);
    test_fdb_tsl_sector_bound_test(2, 2);
}

static void test_fdb_github_issue_249(void)
{
    if (access("storage_tsdb", 0) < 0)
    {
        mkdir("storage_tsdb", 0777);
    }

    uint32_t sec_size = 16 * 1024, db_size = 512 * 1024, test_data_size = 0;
    bool file_mode = true, flag_not_format = false;
    struct fdb_blob blob;
    uint8_t *data = NULL;

    memset(&test_tsdb, 0, sizeof(struct fdb_tsdb));
    fdb_tsdb_control((fdb_tsdb_t) & (test_tsdb), FDB_TSDB_CTRL_SET_SEC_SIZE, &sec_size);
    fdb_tsdb_control((fdb_tsdb_t) & (test_tsdb), FDB_TSDB_CTRL_SET_FILE_MODE, &file_mode);
    fdb_tsdb_control((fdb_tsdb_t) & (test_tsdb), FDB_TSDB_CTRL_SET_NOT_FORMAT, &flag_not_format);
    fdb_tsdb_control((fdb_tsdb_t) & (test_tsdb), FDB_TSDB_CTRL_SET_MAX_SIZE, &db_size);

    test_assert_true(fdb_tsdb_init(&test_tsdb, "storage_tsdb", "storage_tsdb", get_time, 10*1024, NULL) == FDB_NO_ERR);
    /* clean status */
    fdb_tsl_clean(&test_tsdb);
    cur_times = 0;

    test_data_size = 7 * 1024;
    data = malloc(test_data_size);
    test_assert_true(data != NULL);
    test_assert_true(fdb_tsl_append(&test_tsdb, fdb_blob_make(&blob, data, test_data_size)) == FDB_NO_ERR);
    free(data);

    test_data_size = 8 * 1024;
    data = malloc(test_data_size);
    test_assert_true(data != NULL);
    test_assert_true(fdb_tsl_append(&test_tsdb, fdb_blob_make(&blob, data, test_data_size)) == FDB_NO_ERR);
    free(data);

    test_data_size = 9 * 1024;
    data = malloc(test_data_size);
    test_assert_true(data != NULL);
    test_assert_true(fdb_tsl_append(&test_tsdb, fdb_blob_make(&blob, data, test_data_size)) == FDB_NO_ERR);
    free(data);

    { /* reboot simulation */
        test_assert_true(fdb_tsdb_deinit(&test_tsdb) == FDB_NO_ERR);
        test_assert_true(fdb_tsdb_init(&test_tsdb, "storage_tsdb", "storage_tsdb", get_time, 10 * 1024, NULL) == FDB_NO_ERR);
    }
    test_assert_true(fdb_tsl_query_count(&test_tsdb, 2, 6, FDB_TSL_WRITE) == 3);
    test_assert_true(fdb_tsl_query_count(&test_tsdb, 0, INT32_MAX, FDB_TSL_WRITE) == 3);
}

static void testcase(void)
{
    TEST_RUN(test_fdb_tsdb_init_ex);
    TEST_RUN(test_fdb_tsl_clean);
    TEST_RUN(test_fdb_tsl_append);
    TEST_RUN(test_fdb_tsl_iter);
    TEST_RUN(test_fdb_tsl_iter_by_time);
    TEST_RUN(test_fdb_tsl_query_count);
    TEST_RUN(test_fdb_tsl_set_status);
    TEST_RUN(test_fdb_tsl_clean);
    TEST_RUN(test_fdb_tsl_iter_by_time_1);
    TEST_RUN(test_fdb_tsdb_deinit);

    TEST_RUN(test_fdb_github_issue_249);
}


#endif /* defined(FDB_USING_TSDB) */

