//! FlashDB Rust — a faithful C-to-Rust translation of the FlashDB embedded database.
//!
//! Supported profile: POSIX file mode, KVDB + TSDB, FDB_WRITE_GRAN=1, signed 32-bit timestamp.

mod crc;
mod status;
mod file_backend;
mod kvdb;
mod tsdb;
mod ffi;

// Re-export public types for tests
pub use crc::calc_crc32;
pub use kvdb::Kvdb;
pub use tsdb::Tsdb;
pub use file_backend::FileBackend;

/// Software version, must match C.
pub const FDB_SW_VERSION: &str = "2.2.99";
pub const FDB_SW_VERSION_NUM: u32 = 0x20299;

/// Write granularity in bits — fixed at 1 for this profile.
pub const FDB_WRITE_GRAN: usize = 1;

/// KV max name length.
pub const FDB_KV_NAME_MAX: usize = 64;

/// KV cache table size.
pub const FDB_KV_CACHE_TABLE_SIZE: usize = 64;

/// Sector cache table size.
pub const FDB_SECTOR_CACHE_TABLE_SIZE: usize = 8;

/// File cache table size.
pub const FDB_FILE_CACHE_TABLE_SIZE: usize = 2;

/// Erased byte value.
pub const FDB_BYTE_ERASED: u8 = 0xFF;

/// Written byte value.
pub const FDB_BYTE_WRITTEN: u8 = 0x00;

/// Data unused marker (when FDB_BYTE_ERASED == 0xFF).
pub const FDB_DATA_UNUSED: u32 = 0xFFFFFFFF;

/// Failed / invalid address.
pub const FDB_FAILED_ADDR: u32 = 0xFFFFFFFF;

/// String KV value max size for the legacy `fdb_kv_get` function.
pub const FDB_STR_KV_VALUE_MAX_SIZE: usize = 128;

/// GC minimum number of empty sectors.
pub const GC_MIN_EMPTY_SEC_NUM: usize = 1;

/// Sector remain threshold before full status.
pub const FDB_SEC_REMAIN_THRESHOLD_FACTOR: usize = 0; // computed at runtime

/// GC empty sector threshold.
pub const FDB_GC_EMPTY_SEC_THRESHOLD: usize = 1;

/// Sector magic word (`F`, `D`, `B`, `1`) = 0x30424446
pub const KVDB_SECTOR_MAGIC_WORD: u32 = 0x30424446;

/// KV magic word (`K`, `V`, `0`, `0`) = 0x3030564B
pub const KV_MAGIC_WORD: u32 = 0x3030564B;

/// TSDB sector magic word (`T`, `S`, `L`, `0`) = 0x304C5354
pub const TSDB_SECTOR_MAGIC_WORD: u32 = 0x304C5354;

/// Sector not combined value (when FDB_BYTE_ERASED == 0xFF).
pub const SECTOR_NOT_COMBINED: u32 = 0xFFFFFFFF;
pub const SECTOR_COMBINED: u32 = 0x00000000;

/// Align `size` up to `align` (align must be a power of 2).
#[inline]
pub const fn fdb_align(size: usize, align: usize) -> usize {
    ((size + align - 1) / align) * align
}

/// Align down.
#[inline]
pub const fn fdb_align_down(size: usize, align: usize) -> usize {
    (size / align) * align
}

/// Write-granularity alignment unit in bytes.
#[inline]
pub const fn wg_unit() -> usize {
    (FDB_WRITE_GRAN + 7) / 8
}

/// Align by write granularity.
#[inline]
pub const fn wg_align(size: usize) -> usize {
    fdb_align(size, wg_unit())
}

/// Align down by write granularity.
#[inline]
pub const fn wg_align_down(size: usize) -> usize {
    fdb_align_down(size, wg_unit())
}

/// Status table size in bytes.
/// For FDB_WRITE_GRAN == 1: (status_number * 1 + 7) / 8
/// For other: ((status_number - 1) * gran + 7) / 8
#[inline]
pub const fn status_table_size(status_number: usize) -> usize {
    if FDB_WRITE_GRAN == 1 {
        (status_number * FDB_WRITE_GRAN + 7) / 8
    } else {
        ((status_number - 1) * FDB_WRITE_GRAN + 7) / 8
    }
}

pub const FDB_STORE_STATUS_TABLE_SIZE: usize = status_table_size(FDB_SECTOR_STORE_STATUS_NUM);
pub const FDB_DIRTY_STATUS_TABLE_SIZE: usize = status_table_size(FDB_SECTOR_DIRTY_STATUS_NUM);
pub const KV_STATUS_TABLE_SIZE: usize = status_table_size(FDB_KV_STATUS_NUM);
pub const TSL_STATUS_TABLE_SIZE: usize = status_table_size(FDB_TSL_STATUS_NUM);

/// Number of sector store statuses.
pub const FDB_SECTOR_STORE_STATUS_NUM: usize = 4;
/// Number of sector dirty statuses.
pub const FDB_SECTOR_DIRTY_STATUS_NUM: usize = 4;
/// Number of KV statuses.
pub const FDB_KV_STATUS_NUM: usize = 6;
/// Number of TSL statuses.
pub const FDB_TSL_STATUS_NUM: usize = 6;

// ---- Error codes ----

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum FdbErr {
    NoErr = 0,
    EraseErr = 1,
    ReadErr = 2,
    WriteErr = 3,
    KvNameErr = 4,
    KvNameExist = 5,
    SavedFull = 6,
    InitFailed = 7,
}

impl FdbErr {
    pub fn from_c(val: u32) -> Option<Self> {
        match val {
            0 => Some(FdbErr::NoErr),
            1 => Some(FdbErr::EraseErr),
            2 => Some(FdbErr::ReadErr),
            3 => Some(FdbErr::WriteErr),
            4 => Some(FdbErr::KvNameErr),
            5 => Some(FdbErr::KvNameExist),
            6 => Some(FdbErr::SavedFull),
            7 => Some(FdbErr::InitFailed),
            _ => None,
        }
    }
}

// ---- Status enums ----

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum KvStatus {
    Unused = 0,
    PreWrite = 1,
    Write = 2,
    PreDelete = 3,
    Deleted = 4,
    ErrHdr = 5,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum TslStatus {
    Unused = 0,
    PreWrite = 1,
    Write = 2,
    UserStatus1 = 3,
    Deleted = 4,
    UserStatus2 = 5,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum SectorStoreStatus {
    Unused = 0,
    Empty = 1,
    Using = 2,
    Full = 3,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum SectorDirtyStatus {
    Unused = 0,
    False = 1,
    True = 2,
    Gc = 3,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum DbType {
    Kv = 0,
    Ts = 1,
}

/// Timestamp type — 32-bit signed for this profile.
pub type FdbTime = i32;

/// Callback type for getting current time.
pub type GetTimeFn = fn() -> FdbTime;

/// Lock callback.
pub type LockFn = fn(*mut core::ffi::c_void);

/// Unlock callback.
pub type UnlockFn = fn(*mut core::ffi::c_void);

/// TSL iteration callback. Returns `true` to stop iteration.
pub type TslCb = fn(&TslInfo, *mut core::ffi::c_void) -> bool;

// ---- Blob ----

#[derive(Debug, Clone)]
pub struct Blob {
    pub buf: Vec<u8>,
    pub size: usize,
    pub saved_meta_addr: u32,
    pub saved_addr: u32,
    pub saved_len: usize,
}

impl Blob {
    pub fn new(value_buf: &[u8]) -> Self {
        Blob {
            buf: value_buf.to_vec(),
            size: value_buf.len(),
            saved_meta_addr: 0,
            saved_addr: 0,
            saved_len: 0,
        }
    }

    pub fn make(&mut self, value_buf: &[u8], buf_len: usize) -> &mut Self {
        self.buf = value_buf.to_vec();
        self.size = buf_len;
        self
    }

    pub fn read_from_storage(&mut self, backend: &mut dyn StorageBackend, addr: u32, len: usize) -> usize {
        let read_len = self.size.min(len);
        if read_len == 0 {
            return 0;
        }
        let mut tmp = vec![0u8; read_len];
        match backend.read(addr, &mut tmp) {
            Ok(()) => {
                let copy_len = read_len.min(self.buf.len());
                self.buf[..copy_len].copy_from_slice(&tmp[..copy_len]);
                read_len
            }
            Err(_) => 0,
        }
    }
}

// ---- KV Info (in-memory) ----

#[derive(Debug, Clone)]
pub struct KvInfo {
    pub status: KvStatus,
    pub crc_is_ok: bool,
    pub name_len: u8,
    pub magic: u32,
    pub len: u32,
    pub value_len: u32,
    pub name: [u8; FDB_KV_NAME_MAX],
    pub addr_start: u32,
    pub addr_value: u32,
}

impl Default for KvInfo {
    fn default() -> Self {
        KvInfo {
            status: KvStatus::Unused,
            crc_is_ok: false,
            name_len: 0,
            magic: 0,
            len: 0,
            value_len: 0,
            name: [0u8; FDB_KV_NAME_MAX],
            addr_start: FDB_FAILED_ADDR,
            addr_value: 0,
        }
    }
}

// ---- TSL Info (in-memory) ----

#[derive(Debug, Clone)]
pub struct TslInfo {
    pub status: TslStatus,
    pub time: FdbTime,
    pub log_len: u32,
    pub addr_index: u32,
    pub addr_log: u32,
}

impl Default for TslInfo {
    fn default() -> Self {
        TslInfo {
            status: TslStatus::Unused,
            time: 0,
            log_len: 0,
            addr_index: FDB_FAILED_ADDR,
            addr_log: FDB_DATA_UNUSED,
        }
    }
}

// ---- KVDB Sector Info (in-memory) ----

#[derive(Debug, Clone)]
pub struct KvdbSecInfo {
    pub check_ok: bool,
    pub store_status: SectorStoreStatus,
    pub dirty_status: SectorDirtyStatus,
    pub addr: u32,
    pub magic: u32,
    pub combined: u32,
    pub remain: usize,
    pub empty_kv: u32,
}

impl Default for KvdbSecInfo {
    fn default() -> Self {
        KvdbSecInfo {
            check_ok: false,
            store_status: SectorStoreStatus::Unused,
            dirty_status: SectorDirtyStatus::Unused,
            addr: 0,
            magic: 0,
            combined: SECTOR_NOT_COMBINED,
            remain: 0,
            empty_kv: FDB_FAILED_ADDR,
        }
    }
}

// ---- TSDB Sector Info (in-memory) ----

#[derive(Debug, Clone)]
pub struct TsdbSecInfo {
    pub check_ok: bool,
    pub status: SectorStoreStatus,
    pub addr: u32,
    pub magic: u32,
    pub start_time: FdbTime,
    pub end_time: FdbTime,
    pub end_idx: u32,
    pub end_info_stat: [TslStatus; 2],
    pub remain: usize,
    pub empty_idx: u32,
    pub empty_data: u32,
}

impl Default for TsdbSecInfo {
    fn default() -> Self {
        TsdbSecInfo {
            check_ok: false,
            status: SectorStoreStatus::Unused,
            addr: 0,
            magic: 0,
            start_time: 0x7FFFFFFF,
            end_time: 0,
            end_idx: 0,
            end_info_stat: [TslStatus::Unused, TslStatus::Unused],
            remain: 0,
            empty_idx: 0,
            empty_data: 0,
        }
    }
}

// ---- Default KV ----

#[derive(Debug, Clone)]
pub struct DefaultKvNode {
    pub key: String,
    pub value: Vec<u8>,
    pub value_len: usize,
}

#[derive(Debug, Clone, Default)]
pub struct DefaultKv {
    pub kvs: Vec<DefaultKvNode>,
}

// ---- Storage Backend Trait ----

pub trait StorageBackend {
    fn read(&mut self, addr: u32, buf: &mut [u8]) -> Result<(), FdbErr>;
    fn write(&mut self, addr: u32, data: &[u8], sync: bool) -> Result<(), FdbErr>;
    fn erase(&mut self, addr: u32, size: usize) -> Result<(), FdbErr>;
}

// ---- KVDB Control Commands ----

pub const FDB_KVDB_CTRL_SET_SEC_SIZE: i32 = 0x00;
pub const FDB_KVDB_CTRL_GET_SEC_SIZE: i32 = 0x01;
pub const FDB_KVDB_CTRL_SET_LOCK: i32 = 0x02;
pub const FDB_KVDB_CTRL_SET_UNLOCK: i32 = 0x03;
pub const FDB_KVDB_CTRL_SET_FILE_MODE: i32 = 0x09;
pub const FDB_KVDB_CTRL_SET_MAX_SIZE: i32 = 0x0A;
pub const FDB_KVDB_CTRL_SET_NOT_FORMAT: i32 = 0x0B;

// ---- TSDB Control Commands ----

pub const FDB_TSDB_CTRL_SET_SEC_SIZE: i32 = 0x00;
pub const FDB_TSDB_CTRL_GET_SEC_SIZE: i32 = 0x01;
pub const FDB_TSDB_CTRL_SET_LOCK: i32 = 0x02;
pub const FDB_TSDB_CTRL_SET_UNLOCK: i32 = 0x03;
pub const FDB_TSDB_CTRL_SET_ROLLOVER: i32 = 0x04;
pub const FDB_TSDB_CTRL_GET_ROLLOVER: i32 = 0x05;
pub const FDB_TSDB_CTRL_GET_LAST_TIME: i32 = 0x06;
pub const FDB_TSDB_CTRL_SET_FILE_MODE: i32 = 0x09;
pub const FDB_TSDB_CTRL_SET_MAX_SIZE: i32 = 0x0A;
pub const FDB_TSDB_CTRL_SET_NOT_FORMAT: i32 = 0x0B;

//! Status table read/write utilities.
//! Faithful translation of _fdb_set_status, _fdb_get_status, etc.

use crate::{
    FDB_WRITE_GRAN, FDB_BYTE_ERASED, FDB_BYTE_WRITTEN, status_table_size,
    StorageBackend, FdbErr, FDB_FAILED_ADDR, wg_align,
};

/// Set the status in a status table buffer.
/// Returns the byte index that was modified (or usize::MAX if no write needed).
/// Identical semantics to C `_fdb_set_status`.
pub fn set_status(status_table: &mut [u8], status_num: usize, status_index: usize) -> usize {
    // Fill the table with erased value
    let table_size = status_table_size(status_num);
    for b in status_table.iter_mut().take(table_size) {
        *b = FDB_BYTE_ERASED;
    }

    if status_index == 0 {
        return usize::MAX;
    }

    if FDB_WRITE_GRAN == 1 {
        let byte_index = (status_index - 1) / 8;
        if FDB_BYTE_ERASED == 0xFF {
            status_table[byte_index] &= (0x00ff_u32 >> (status_index % 8)) as u8;
        } else {
            status_table[byte_index] |= (0x00ff_u32 >> (status_index % 8)) as u8;
        }
        byte_index
    } else {
        let byte_index = (status_index - 1) * (FDB_WRITE_GRAN / 8);
        status_table[byte_index] = FDB_BYTE_WRITTEN;
        byte_index
    }
}

/// Get the current status index from a status table buffer.
/// Identical semantics to C `_fdb_get_status`.
pub fn get_status(status_table: &[u8], status_num: usize) -> usize {
    let mut i = 0usize;
    let mut status_num_bak = status_num;
    let sn = status_num - 1;
    status_num_bak = sn + 1;

    let mut count = sn;
    loop {
        if count == 0 {
            break;
        }
        if FDB_WRITE_GRAN == 1 {
            if (status_table[count / 8] & (0x80 >> (count % 8)) as u8) == 0x00 {
                break;
            }
        } else {
            if status_table[count * FDB_WRITE_GRAN / 8] == FDB_BYTE_WRITTEN {
                break;
            }
        }
        i += 1;
        if count == 0 { break; }
        count -= 1;
    }

    status_num_bak - i
}

/// Write a status to flash via the backend.
/// Identical semantics to C `_fdb_write_status`.
pub fn write_status(
    backend: &mut dyn StorageBackend,
    addr: u32,
    status_table: &mut [u8],
    status_num: usize,
    status_index: usize,
    sync: bool,
) -> Result<(), FdbErr> {
    assert!(status_index < status_num);

    let byte_index = set_status(status_table, status_num, status_index);

    if byte_index == usize::MAX {
        return Ok(());
    }

    if FDB_WRITE_GRAN == 1 {
        backend.write(addr + byte_index as u32, &status_table[byte_index..byte_index + 1], sync)
    } else {
        let gran_bytes = FDB_WRITE_GRAN / 8;
        backend.write(addr + byte_index as u32, &status_table[byte_index..byte_index + gran_bytes], sync)
    }
}

/// Read a status from flash via the backend.
/// Returns the status index.
/// Identical semantics to C `_fdb_read_status`.
pub fn read_status(
    backend: &mut dyn StorageBackend,
    addr: u32,
    status_table: &mut [u8],
    total_num: usize,
) -> usize {
    let table_size = status_table_size(total_num);
    if backend.read(addr, &mut status_table[..table_size]).is_err() {
        // If read fails, treat as all-erased
        for b in status_table.iter_mut().take(table_size) {
            *b = FDB_BYTE_ERASED;
        }
    }
    get_status(status_table, total_num)
}

/// Find the continue 0xFF flash address.
/// Identical semantics to C `_fdb_continue_ff_addr`.
pub fn continue_ff_addr(
    backend: &mut dyn StorageBackend,
    start: u32,
    end: u32,
    sec_size: u32,
) -> u32 {
    let mut buf = [0u8; 32];
    let mut last_data = FDB_BYTE_WRITTEN;
    let mut addr = start;
    let mut cur = start;

    while cur < end {
        let read_size = if cur + 32 < end { 32 } else { (end - cur) as usize };
        if backend.read(cur, &mut buf[..read_size]).is_err() {
            break;
        }
        for i in 0..read_size {
            if last_data != FDB_BYTE_ERASED && buf[i] == FDB_BYTE_ERASED {
                addr = cur + i as u32;
            }
            last_data = buf[i];
        }
        cur += 32;
    }

    if last_data == FDB_BYTE_ERASED {
        wg_align(addr as usize) as u32
    } else {
        end
    }
}

/// Write data aligned to write granularity.
/// Identical semantics to C `_fdb_flash_write_align`.
pub fn write_align(
    backend: &mut dyn StorageBackend,
    addr: u32,
    data: &[u8],
) -> Result<(), FdbErr> {
    let aligned_down = crate::wg_align_down(data.len());
    if aligned_down > 0 {
        backend.write(addr, &data[..aligned_down], false)?;
    }

    let remain = data.len() - aligned_down;
    if remain > 0 {
        let unit = crate::wg_unit();
        let mut align_data = vec![FDB_BYTE_ERASED; unit];
        align_data[..remain].copy_from_slice(&data[aligned_down..aligned_down + remain]);
        backend.write(addr + aligned_down as u32, &align_data, false)?;
    }

    Ok(())
}

//! POSIX file mode storage backend for FlashDB.
//! Faithful translation of fdb_file.c (POSIX mode).

use std::fs;
use std::io::{Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};

use crate::{StorageBackend, FdbErr, FDB_BYTE_ERASED, fdb_align_down};

const DB_PATH_MAX: usize = 256;
const DB_NAME_MAX: usize = 8;
const BUF_SIZE: usize = 32;
const FILE_CACHE_TABLE_SIZE: usize = crate::FDB_FILE_CACHE_TABLE_SIZE;

struct FileCacheEntry {
    sec_addr: u32,
    fd: Option<fs::File>,
}

impl Default for FileCacheEntry {
    fn default() -> Self {
        FileCacheEntry {
            sec_addr: crate::FDB_FAILED_ADDR,
            fd: None,
        }
    }
}

pub struct FileBackend {
    db_name: String,
    dir: PathBuf,
    sec_size: u32,
    max_size: u32,
    cache: Vec<FileCacheEntry>,
}

impl FileBackend {
    pub fn new(db_name: &str, dir: &str, sec_size: u32, max_size: u32) -> Self {
        let mut cache = Vec::with_capacity(FILE_CACHE_TABLE_SIZE);
        for _ in 0..FILE_CACHE_TABLE_SIZE {
            cache.push(FileCacheEntry::default());
        }
        FileBackend {
            db_name: db_name.to_string(),
            dir: PathBuf::from(dir),
            sec_size,
            max_size,
            cache,
        }
    }

    fn get_db_file_path(&self, addr: u32) -> PathBuf {
        let sec_addr = fdb_align_down(addr as usize, self.sec_size as usize) as u32;
        let index = sec_addr / self.sec_size;
        let file_name = format!("{:.*}.fdb.{}", DB_NAME_MAX, self.db_name, index);
        self.dir.join(&file_name)
    }

    fn get_file_from_cache(&self, sec_addr: u32) -> Option<&fs::File> {
        for entry in &self.cache {
            if entry.sec_addr == sec_addr {
                return entry.fd.as_ref();
            }
        }
        None
    }

    fn update_file_cache(&mut self, sec_addr: u32, fd: Option<fs::File>) {
        // Check if already in cache
        for entry in &mut self.cache {
            if entry.sec_addr == sec_addr {
                entry.fd = fd;
                return;
            }
        }

        // Find free slot
        if fd.is_some() {
            for i in 0..self.cache.len() {
                if self.cache[i].fd.is_none() && self.cache[i].sec_addr == crate::FDB_FAILED_ADDR {
                    self.cache[i].sec_addr = sec_addr;
                    self.cache[i].fd = fd;
                    return;
                }
            }
            // Cache full — close the last entry and shift
            if let Some(ref mut f) = self.cache.last_mut().unwrap().fd {
                let _ = f.sync_all();
            }
            for i in (1..self.cache.len()).rev() {
                self.cache[i] = std::mem::take(&mut self.cache[i - 1]);
            }
            self.cache[0].sec_addr = sec_addr;
            self.cache[0].fd = fd;
        }
    }

    fn open_db_file(&mut self, addr: u32, clean: bool) -> Option<fs::File> {
        let sec_addr = fdb_align_down(addr as usize, self.sec_size as usize) as u32;

        // Try cache first
        let cached_fd = self.get_file_from_cache(sec_addr).and_then(|f| f.try_clone().ok());

        if cached_fd.is_some() && !clean {
            return cached_fd;
        }

        let path = self.get_db_file_path(addr);

        // Close cached fd if we're cleaning
        if clean {
            self.update_file_cache(sec_addr, None);
        }

        if clean {
            // Clean the old file
            if let Ok(mut f) = fs::OpenOptions::new()
                .read(true)
                .write(true)
                .create(true)
                .truncate(true)
                .open(&path)
            {
                let _ = f.sync_all();
            }
        }

        // Open the file
        if self.get_file_from_cache(sec_addr).is_none() {
            if let Ok(f) = fs::OpenOptions::new()
                .read(true)
                .write(true)
                .open(&path)
            {
                self.update_file_cache(sec_addr, Some(f));
            } else {
                // File doesn't exist yet; create it
                // Ensure directory exists
                if let Some(parent) = path.parent() {
                    let _ = fs::create_dir_all(parent);
                }
                if let Ok(f) = fs::OpenOptions::new()
                    .read(true)
                    .write(true)
                    .create(true)
                    .open(&path)
                {
                    self.update_file_cache(sec_addr, Some(f));
                }
            }
        }

        self.get_file_from_cache(sec_addr).and_then(|f| f.try_clone().ok())
    }
}

impl StorageBackend for FileBackend {
    fn read(&mut self, addr: u32, buf: &mut [u8]) -> Result<(), FdbErr> {
        let fd = self.open_db_file(addr, false);
        match fd {
            Some(mut f) => {
                let offset = addr % self.sec_size;
                if f.seek(SeekFrom::Start(offset as u64)).is_err() {
                    return Err(FdbErr::ReadErr);
                }
                match f.read_exact(buf) {
                    Ok(()) => Ok(()),
                    Err(_) => Err(FdbErr::ReadErr),
                }
            }
            None => Err(FdbErr::ReadErr),
        }
    }

    fn write(&mut self, addr: u32, data: &[u8], sync: bool) -> Result<(), FdbErr> {
        let fd = self.open_db_file(addr, false);
        match fd {
            Some(mut f) => {
                let offset = addr % self.sec_size;
                if f.seek(SeekFrom::Start(offset as u64)).is_err() {
                    return Err(FdbErr::WriteErr);
                }
                match f.write_all(data) {
                    Ok(()) => {
                        if sync {
                            let _ = f.sync_all();
                        }
                        Ok(())
                    }
                    Err(_) => Err(FdbErr::WriteErr),
                }
            }
            None => Err(FdbErr::WriteErr),
        }
    }

    fn erase(&mut self, addr: u32, size: usize) -> Result<(), FdbErr> {
        let fd = self.open_db_file(addr, true);
        match fd {
            Some(mut f) => {
                let erase_buf = [FDB_BYTE_ERASED; BUF_SIZE];
                f.seek(SeekFrom::Start(0)).map_err(|_| FdbErr::EraseErr)?;
                let full_chunks = size / BUF_SIZE;
                for _ in 0..full_chunks {
                    f.write_all(&erase_buf).map_err(|_| FdbErr::EraseErr)?;
                }
                let remainder = size - full_chunks * BUF_SIZE;
                if remainder > 0 {
                    f.write_all(&erase_buf[..remainder]).map_err(|_| FdbErr::EraseErr)?;
                }
                let _ = f.sync_all();
                Ok(())
            }
            None => Err(FdbErr::EraseErr),
        }
    }
}

//! KVDB — Key-Value Database implementation.
//! Faithful translation of fdb_kvdb.c.

use std::cell::RefCell;

use crate::{
    StorageBackend, FdbErr, FdbTime, FDB_BYTE_ERASED, FDB_DATA_UNUSED, FDB_FAILED_ADDR,
    FDB_KV_NAME_MAX, FDB_GC_EMPTY_SEC_THRESHOLD, FDB_STR_KV_VALUE_MAX_SIZE,
    KVDB_SECTOR_MAGIC_WORD, KV_MAGIC_WORD, SECTOR_NOT_COMBINED, SECTOR_COMBINED,
    KvStatus, SectorStoreStatus, SectorDirtyStatus, DefaultKv, DefaultKvNode,
    Blob, KvInfo, KvdbSecInfo,
    calc_crc32, status, wg_align, wg_align_down, fdb_align_down, status_table_size,
    FDB_STORE_STATUS_TABLE_SIZE, FDB_DIRTY_STATUS_TABLE_SIZE, FDB_KV_STATUS_NUM,
    KV_STATUS_TABLE_SIZE, FDB_SECTOR_STORE_STATUS_NUM, FDB_SECTOR_DIRTY_STATUS_NUM,
    DbType, FDB_SEC_REMAIN_THRESHOLD,
};

/// Compute sector header data size at runtime.
fn sector_hdr_data_size(sec_size: u32) -> usize {
    // sector_hdr_data: store_status + dirty_status + magic + combined + reserved
    // For FDB_WRITE_GRAN=1:
    //   store: FDB_STORE_STATUS_TABLE_SIZE bytes
    //   dirty: FDB_DIRTY_STATUS_TABLE_SIZE bytes
    //   magic: 4 bytes
    //   combined: 4 bytes
    //   reserved: 4 bytes
    let raw = FDB_STORE_STATUS_TABLE_SIZE + FDB_DIRTY_STATUS_TABLE_SIZE + 4 + 4 + 4;
    wg_align(raw)
}

/// Compute KV header data size at runtime.
fn kv_hdr_data_size() -> usize {
    // kv_hdr_data: status_table + magic + len + crc32 + name_len + value_len
    let raw = KV_STATUS_TABLE_SIZE + 4 + 4 + 4 + 1 + 4;
    wg_align(raw)
}

/// Compute FDB_SEC_REMAIN_THRESHOLD = KV_HDR_DATA_SIZE + FDB_KV_NAME_MAX
fn sec_remain_threshold() -> usize {
    kv_hdr_data_size() + FDB_KV_NAME_MAX
}

// Offsets into sector header
fn sector_store_offset() -> usize { 0 }
fn sector_dirty_offset() -> usize { FDB_STORE_STATUS_TABLE_SIZE }
fn sector_magic_offset() -> usize { FDB_STORE_STATUS_TABLE_SIZE + FDB_DIRTY_STATUS_TABLE_SIZE }
fn kv_magic_offset() -> usize { KV_STATUS_TABLE_SIZE }
fn kv_len_offset() -> usize { KV_STATUS_TABLE_SIZE + 4 }
fn kv_name_len_offset() -> usize { KV_STATUS_TABLE_SIZE + 4 + 4 + 4 }

fn sector_num(max_size: u32, sec_size: u32) -> u32 {
    max_size / sec_size
}

pub struct Kvdb {
    pub name: String,
    pub sec_size: u32,
    pub max_size: u32,
    pub oldest_addr: u32,
    pub init_ok: bool,
    pub file_mode: bool,
    pub not_formatable: bool,
    pub dir: String,
    pub gc_request: bool,
    pub in_recovery_check: bool,
    pub cur_kv: KvInfo,
    pub cur_sector: KvdbSecInfo,
    pub last_is_complete_del: bool,
    pub default_kvs: DefaultKv,
    pub lock_fn: Option<fn(*mut core::ffi::c_void)>,
    pub unlock_fn: Option<fn(*mut core::ffi::c_void)>,
    pub user_data: *mut core::ffi::c_void,
    pub backend: Option<Box<dyn StorageBackend>>,
    // Cache tables
    kv_cache: Vec<KvCacheNode>,
    sector_cache: Vec<KvdbSecInfo>,
}

#[derive(Clone)]
struct KvCacheNode {
    name_crc: u16,
    active: u16,
    addr: u32,
}

impl Default for KvCacheNode {
    fn default() -> Self {
        KvCacheNode {
            name_crc: 0,
            active: 0,
            addr: FDB_DATA_UNUSED,
        }
    }
}

impl Kvdb {
    pub fn new() -> Self {
        let kv_cache = vec![KvCacheNode::default(); crate::FDB_KV_CACHE_TABLE_SIZE];
        let mut sector_cache = Vec::with_capacity(crate::FDB_SECTOR_CACHE_TABLE_SIZE);
        for _ in 0..crate::FDB_SECTOR_CACHE_TABLE_SIZE {
            sector_cache.push(KvdbSecInfo::default());
        }
        Kvdb {
            name: String::new(),
            sec_size: 0,
            max_size: 0,
            oldest_addr: 0,
            init_ok: false,
            file_mode: true,
            not_formatable: false,
            dir: String::new(),
            gc_request: false,
            in_recovery_check: false,
            cur_kv: KvInfo::default(),
            cur_sector: KvdbSecInfo::default(),
            last_is_complete_del: false,
            default_kvs: DefaultKv::default(),
            lock_fn: None,
            unlock_fn: None,
            user_data: std::ptr::null_mut(),
            backend: None,
            kv_cache,
            sector_cache,
        }
    }

    fn be(&mut self) -> &mut dyn StorageBackend {
        self.backend.as_deref_mut().unwrap()
    }

    fn db_lock(&self) {
        if let Some(lock) = self.lock_fn {
            lock(self.user_data);
        }
    }

    fn db_unlock(&self) {
        if let Some(unlock) = self.unlock_fn {
            unlock(self.user_data);
        }
    }

    fn update_sector_cache(&mut self, sector: &KvdbSecInfo) {
        for i in 0..self.sector_cache.len() {
            if self.sector_cache[i].addr == sector.addr {
                if sector.check_ok {
                    self.sector_cache[i] = sector.clone();
                } else {
                    self.sector_cache[i].addr = FDB_DATA_UNUSED;
                }
                return;
            } else if self.sector_cache[i].addr == FDB_DATA_UNUSED {
                // empty slot found
            }
        }
        if sector.check_ok {
            for i in 0..self.sector_cache.len() {
                if self.sector_cache[i].addr == FDB_DATA_UNUSED {
                    self.sector_cache[i] = sector.clone();
                    return;
                }
            }
        }
    }

    fn get_sector_from_cache(&self, sec_addr: u32) -> Option<usize> {
        for i in 0..self.sector_cache.len() {
            if self.sector_cache[i].addr == sec_addr {
                return Some(i);
            }
        }
        None
    }

    fn update_sector_empty_addr_cache(&mut self, sec_addr: u32, empty_addr: u32) {
        if let Some(idx) = self.get_sector_from_cache(sec_addr) {
            self.sector_cache[idx].empty_kv = empty_addr;
            self.sector_cache[idx].remain = self.sec_size as usize - (empty_addr - sec_addr) as usize;
        }
    }

    fn update_sector_status_store_cache(&mut self, sec_addr: u32, st: SectorStoreStatus) {
        if let Some(idx) = self.get_sector_from_cache(sec_addr) {
            self.sector_cache[idx].store_status = st;
        }
    }

    fn update_kv_cache(&mut self, name: &str, addr: u32) {
        let name_crc = (calc_crc32(0, name.as_bytes()) >> 16) as u16;
        let name_len = name.len();

        if addr != FDB_DATA_UNUSED {
            // Update existing
            for i in 0..self.kv_cache.len() {
                if self.kv_cache[i].name_crc == name_crc {
                    self.kv_cache[i].addr = addr;
                    return;
                }
            }
            // Find empty slot
            let mut empty_index = self.kv_cache.len();
            let mut min_activity_index = self.kv_cache.len();
            let mut min_activity: u16 = 0xFFFF;

            for i in 0..self.kv_cache.len() {
                if self.kv_cache[i].addr == FDB_DATA_UNUSED && empty_index == self.kv_cache.len() {
                    empty_index = i;
                } else if self.kv_cache[i].addr != FDB_DATA_UNUSED {
                    if self.kv_cache[i].active > 0 {
                        self.kv_cache[i].active -= 1;
                    }
                    if self.kv_cache[i].active < min_activity {
                        min_activity_index = i;
                        min_activity = self.kv_cache[i].active;
                    }
                }
            }

            if empty_index < self.kv_cache.len() {
                self.kv_cache[empty_index].addr = addr;
                self.kv_cache[empty_index].name_crc = name_crc;
                self.kv_cache[empty_index].active = self.kv_cache.len() as u16;
            } else if min_activity_index < self.kv_cache.len() {
                self.kv_cache[min_activity_index].addr = addr;
                self.kv_cache[min_activity_index].name_crc = name_crc;
                self.kv_cache[min_activity_index].active = self.kv_cache.len() as u16;
            }
        } else {
            // Delete
            for i in 0..self.kv_cache.len() {
                if self.kv_cache[i].name_crc == name_crc {
                    self.kv_cache[i].addr = FDB_DATA_UNUSED;
                    self.kv_cache[i].active = 0;
                    return;
                }
            }
        }
    }

    fn get_kv_from_cache(&mut self, name: &str) -> Option<u32> {
        let name_crc = (calc_crc32(0, name.as_bytes()) >> 16) as u16;
        let name_len = name.len();

        for i in 0..self.kv_cache.len() {
            if self.kv_cache[i].addr != FDB_DATA_UNUSED && self.kv_cache[i].name_crc == name_crc {
                // Read the KV name from flash to verify
                let mut saved_name = vec![0u8; FDB_KV_NAME_MAX];
                let kv_hdr_sz = kv_hdr_data_size();
                if self.be().read(self.kv_cache[i].addr + kv_hdr_sz as u32, &mut saved_name).is_ok() {
                    if name.as_bytes() == &saved_name[..name_len] {
                        let addr = self.kv_cache[i].addr;
                        let active = self.kv_cache[i].active;
                        self.kv_cache[i].active = if active >= 0xFFFF - self.kv_cache.len() as u16 {
                            0xFFFF
                        } else {
                            active + self.kv_cache.len() as u16
                        };
                        return Some(addr);
                    }
                }
            }
        }
        None
    }

    /// Find the next KV address by magic word.
    fn find_next_kv_addr(&self, start: u32, end: u32) -> u32 {
        // Check cache first
        let sec_addr = fdb_align_down(start as usize, self.sec_size as usize) as u32;
        if let Some(idx) = self.get_sector_from_cache(sec_addr) {
            if start == self.sector_cache[idx].empty_kv {
                return FDB_FAILED_ADDR;
            }
        }

        let mut buf = [0u8; 32];
        let start_bak = start;
        let mut cur = start;

        while cur < end && cur + 32 < end {
            if self.be().read(cur, &mut buf).is_err() {
                return FDB_FAILED_ADDR;
            }
            for i in 0..(32 - 4) {
                if cur + i as u32 >= end {
                    break;
                }
                // Little endian
                let magic = buf[i] as u32
                    | ((buf[i + 1] as u32) << 8)
                    | ((buf[i + 2] as u32) << 16)
                    | ((buf[i + 3] as u32) << 24);
                if magic == KV_MAGIC_WORD {
                    let addr = cur + i as u32;
                    let kv_addr = if kv_magic_offset() <= addr as usize {
                        addr - kv_magic_offset() as u32
                    } else {
                        continue;
                    };
                    if kv_addr >= start_bak {
                        return kv_addr;
                    }
                }
            }
            cur += (32 - 4) as u32;
        }

        FDB_FAILED_ADDR
    }

    /// Get next KV address in a sector.
    fn get_next_kv_addr(&self, sector: &KvdbSecInfo, pre_kv: &KvInfo) -> u32 {
        if sector.store_status == SectorStoreStatus::Empty {
            return FDB_FAILED_ADDR;
        }

        let sec_hdr_sz = sector_hdr_data_size(self.sec_size) as u32;

        let addr = if pre_kv.addr_start == FDB_FAILED_ADDR {
            sector.addr + sec_hdr_sz
        } else if pre_kv.addr_start <= sector.addr + self.sec_size {
            if pre_kv.crc_is_ok {
                pre_kv.addr_start + pre_kv.len
            } else {
                pre_kv.addr_start + wg_align(1) as u32
            }
        } else {
            return FDB_FAILED_ADDR;
        };

        if addr == FDB_FAILED_ADDR || addr > sector.addr + self.sec_size || pre_kv.len == 0 {
            return FDB_FAILED_ADDR;
        }

        self.find_next_kv_addr(addr, sector.addr + self.sec_size - sec_hdr_sz)
    }

    /// Read a KV from flash.
    fn read_kv(&mut self, kv: &mut KvInfo) -> Result<(), FdbErr> {
        let kv_hdr_sz = kv_hdr_data_size();
        let mut kv_hdr_buf = vec![0u8; kv_hdr_sz];
        self.be().read(kv.addr_start, &mut kv_hdr_buf)?;

        // Parse KV header from raw bytes
        let kv_status = status::get_status(&kv_hdr_buf[..KV_STATUS_TABLE_SIZE], FDB_KV_STATUS_NUM);
        kv.status = match kv_status {
            0 => KvStatus::Unused,
            1 => KvStatus::PreWrite,
            2 => KvStatus::Write,
            3 => KvStatus::PreDelete,
            4 => KvStatus::Deleted,
            5 => KvStatus::ErrHdr,
            _ => KvStatus::ErrHdr,
        };

        kv.len = u32::from_le_bytes(kv_hdr_buf[kv_len_offset()..kv_len_offset() + 4].try_into().unwrap());

        if kv.len == u32::MAX || kv.len > self.max_size || kv.len < kv_hdr_sz as u32 {
            kv.len = kv_hdr_sz as u32;
            if kv.status != KvStatus::ErrHdr {
                kv.status = KvStatus::ErrHdr;
                let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
                let _ = status::write_status(self.be(), kv.addr_start, &mut st, FDB_KV_STATUS_NUM, KvStatus::ErrHdr as usize, true);
            }
            kv.crc_is_ok = false;
            return Err(FdbErr::ReadErr);
        }

        let name_len = kv_hdr_buf[kv_name_len_offset()] as usize;
        let value_len = u32::from_le_bytes(
            kv_hdr_buf[kv_name_len_offset() + 1..kv_name_len_offset() + 5].try_into().unwrap()
        ) as usize;

        // Calculate CRC32
        let crc32_stored = u32::from_le_bytes(
            kv_hdr_buf[kv_name_len_offset() - 4..kv_name_len_offset()].try_into().unwrap()
        );

        let mut calc_crc: u32 = 0;
        // CRC32(name_len as uint32 + value_len as uint32 + name + value)
        let name_len_bytes = (name_len as u32).to_le_bytes();
        calc_crc = calc_crc32(calc_crc, &name_len_bytes);
        let value_len_bytes = (value_len as u32).to_le_bytes();
        calc_crc = calc_crc32(calc_crc, &value_len_bytes);

        let crc_data_len = kv.len as usize - kv_hdr_sz;
        let mut buf = [0u8; 32];
        let mut len = 0usize;
        while len < crc_data_len {
            let size = if len + 32 < crc_data_len { 32 } else { crc_data_len - len };
            let read_size = wg_align(size);
            let mut read_buf = vec![0u8; read_size];
            if self.be().read(kv.addr_start + kv_hdr_sz as u32 + len as u32, &mut read_buf).is_err() {
                kv.crc_is_ok = false;
                return Err(FdbErr::ReadErr);
            }
            calc_crc = calc_crc32(calc_crc, &read_buf[..size]);
            len += size;
        }

        if calc_crc != crc32_stored {
            kv.crc_is_ok = false;
            // Try to read name anyway
            let actual_name_len = name_len.min(FDB_KV_NAME_MAX);
            let aligned_name_len = wg_align(actual_name_len);
            let mut name_buf = vec![0u8; aligned_name_len];
            let _ = self.be().read(kv.addr_start + kv_hdr_sz as u32, &mut name_buf);
            kv.name[..actual_name_len].copy_from_slice(&name_buf[..actual_name_len]);
            kv.name_len = actual_name_len as u8;
            return Err(FdbErr::ReadErr);
        }

        kv.crc_is_ok = true;
        kv.name_len = name_len as u8;
        kv.value_len = value_len as u32;

        let actual_name_len = name_len.min(FDB_KV_NAME_MAX);
        let aligned_name_len = wg_align(actual_name_len);
        let mut name_buf = vec![0u8; aligned_name_len];
        self.be().read(kv.addr_start + kv_hdr_sz as u32, &mut name_buf)?;
        kv.name[..actual_name_len].copy_from_slice(&name_buf[..actual_name_len]);
        if actual_name_len < kv.name.len() {
            kv.name[actual_name_len] = 0;
        }

        kv.addr_value = kv.addr_start + kv_hdr_sz as u32 + wg_align(actual_name_len) as u32;

        Ok(())
    }

    /// Read sector info from flash.
    fn read_sector_info(&mut self, addr: u32, traversal: bool) -> Result<KvdbSecInfo, FdbErr> {
        assert_eq!(addr % self.sec_size, 0);

        let sec_hdr_sz = sector_hdr_data_size(self.sec_size);

        // Check cache
        if let Some(idx) = self.get_sector_from_cache(addr) {
            if !traversal || (traversal && self.sector_cache[idx].empty_kv != FDB_FAILED_ADDR) {
                return Ok(self.sector_cache[idx].clone());
            }
        }

        let mut sec_hdr_buf = vec![0u8; sec_hdr_sz];
        self.be().read(addr, &mut sec_hdr_buf)?;

        let mut sector = KvdbSecInfo::default();
        sector.addr = addr;

        // Parse sector header
        let store_status = status::get_status(
            &sec_hdr_buf[sector_store_offset()..sector_store_offset() + FDB_STORE_STATUS_TABLE_SIZE],
            FDB_SECTOR_STORE_STATUS_NUM,
        );
        sector.store_status = match store_status {
            0 => SectorStoreStatus::Unused,
            1 => SectorStoreStatus::Empty,
            2 => SectorStoreStatus::Using,
            3 => SectorStoreStatus::Full,
            _ => SectorStoreStatus::Unused,
        };

        let dirty_status = status::get_status(
            &sec_hdr_buf[sector_dirty_offset()..sector_dirty_offset() + FDB_DIRTY_STATUS_TABLE_SIZE],
            FDB_SECTOR_DIRTY_STATUS_NUM,
        );
        sector.dirty_status = match dirty_status {
            0 => SectorDirtyStatus::Unused,
            1 => SectorDirtyStatus::False,
            2 => SectorDirtyStatus::True,
            3 => SectorDirtyStatus::Gc,
            _ => SectorDirtyStatus::Unused,
        };

        let magic_off = sector_magic_offset();
        sector.magic = u32::from_le_bytes(sec_hdr_buf[magic_off..magic_off + 4].try_into().unwrap());

        if sector.magic != KVDB_SECTOR_MAGIC_WORD {
            sector.check_ok = false;
            sector.combined = SECTOR_NOT_COMBINED;
            return Err(FdbErr::InitFailed);
        }

        sector.check_ok = true;
        let combined_off = magic_off + 4;
        sector.combined = u32::from_le_bytes(sec_hdr_buf[combined_off..combined_off + 4].try_into().unwrap());

        if sector.combined != SECTOR_NOT_COMBINED && sector.combined != SECTOR_COMBINED {
            sector.check_ok = false;
            return Err(FdbErr::InitFailed);
        }

        if traversal {
            sector.remain = 0;
            sector.empty_kv = sector.addr + sec_hdr_sz as u32;

            if sector.store_status == SectorStoreStatus::Empty {
                sector.remain = self.sec_size as usize - sec_hdr_sz;
            } else if sector.store_status == SectorStoreStatus::Using {
                sector.remain = self.sec_size as usize - sec_hdr_sz;
                let mut kv_obj = KvInfo::default();
                kv_obj.addr_start = sector.addr + sec_hdr_sz as u32;
                loop {
                    let _ = self.read_kv(&mut kv_obj);
                    if !kv_obj.crc_is_ok {
                        if kv_obj.status != KvStatus::PreWrite && kv_obj.status != KvStatus::ErrHdr {
                            sector.remain = 0;
                            break;
                        }
                    }
                    sector.empty_kv += kv_obj.len;
                    if sector.remain >= kv_obj.len as usize {
                        sector.remain -= kv_obj.len as usize;
                    } else {
                        sector.remain = 0;
                    }

                    let next_addr = self.get_next_kv_addr(&sector, &kv_obj);
                    if next_addr == FDB_FAILED_ADDR {
                        break;
                    }
                    kv_obj.addr_start = next_addr;
                }

                // Check continue FF
                let ff_addr = status::continue_ff_addr(
                    self.be(),
                    sector.empty_kv,
                    sector.addr + self.sec_size,
                    self.sec_size,
                );
                if sector.empty_kv != ff_addr {
                    sector.empty_kv = ff_addr;
                    sector.remain = self.sec_size as usize - (ff_addr - sector.addr) as usize;
                }
            }

            self.update_sector_cache(&sector);
        } else {
            if self.get_sector_from_cache(sector.addr).is_none() {
                sector.empty_kv = FDB_FAILED_ADDR;
                sector.remain = 0;
                self.update_sector_cache(&sector);
            }
        }

        Ok(sector)
    }

    /// Get next sector address.
    fn get_next_sector_addr(&self, pre_sec: &KvdbSecInfo, traversed_len: u32) -> u32 {
        let cur_block_size = if pre_sec.combined == SECTOR_NOT_COMBINED {
            self.sec_size
        } else {
            pre_sec.combined * self.sec_size
        };

        if traversed_len + cur_block_size <= self.max_size {
            if pre_sec.addr + cur_block_size < self.max_size {
                pre_sec.addr + cur_block_size
            } else {
                0
            }
        } else {
            FDB_FAILED_ADDR
        }
    }

    /// Format a sector.
    fn format_sector(&mut self, addr: u32, combined_value: u32) -> Result<(), FdbErr> {
        assert_eq!(addr % self.sec_size, 0);

        self.be().erase(addr, self.sec_size as usize)?;

        let sec_hdr_sz = sector_hdr_data_size(self.sec_size);
        let mut sec_hdr_buf = vec![FDB_BYTE_ERASED; sec_hdr_sz];

        // For FDB_WRITE_GRAN=1, build the header in memory then write it all at once
        status::set_status(
            &mut sec_hdr_buf[sector_store_offset()..sector_store_offset() + FDB_STORE_STATUS_TABLE_SIZE],
            FDB_SECTOR_STORE_STATUS_NUM,
            SectorStoreStatus::Empty as usize,
        );
        status::set_status(
            &mut sec_hdr_buf[sector_dirty_offset()..sector_dirty_offset() + FDB_DIRTY_STATUS_TABLE_SIZE],
            FDB_SECTOR_DIRTY_STATUS_NUM,
            SectorDirtyStatus::False as usize,
        );

        let magic_off = sector_magic_offset();
        sec_hdr_buf[magic_off..magic_off + 4].copy_from_slice(&KVDB_SECTOR_MAGIC_WORD.to_le_bytes());
        sec_hdr_buf[magic_off + 4..magic_off + 8].copy_from_slice(&combined_value.to_le_bytes());
        sec_hdr_buf[magic_off + 8..magic_off + 12].copy_from_slice(&FDB_DATA_UNUSED.to_le_bytes());

        self.be().write(addr, &sec_hdr_buf, true)?;

        // Invalidate cache
        let mut sector = KvdbSecInfo::default();
        sector.addr = addr;
        sector.check_ok = false;
        sector.empty_kv = FDB_FAILED_ADDR;
        self.update_sector_cache(&sector);

        Ok(())
    }

    /// Update sector status.
    fn update_sec_status(&mut self, sector: &mut KvdbSecInfo, new_kv_len: usize) -> Result<bool, FdbErr> {
        let mut is_full = false;
        let threshold = sec_remain_threshold();

        if sector.store_status == SectorStoreStatus::Empty {
            let mut st = vec![0u8; FDB_STORE_STATUS_TABLE_SIZE];
            status::write_status(self.be(), sector.addr, &mut st, FDB_SECTOR_STORE_STATUS_NUM, SectorStoreStatus::Using as usize, true)?;
            self.update_sector_status_store_cache(sector.addr, SectorStoreStatus::Using);
            sector.store_status = SectorStoreStatus::Using;
        } else if sector.store_status == SectorStoreStatus::Using {
            if sector.remain < threshold || sector.remain - new_kv_len < threshold {
                let mut st = vec![0u8; FDB_STORE_STATUS_TABLE_SIZE];
                status::write_status(self.be(), sector.addr, &mut st, FDB_SECTOR_STORE_STATUS_NUM, SectorStoreStatus::Full as usize, true)?;
                self.update_sector_status_store_cache(sector.addr, SectorStoreStatus::Full);
                sector.store_status = SectorStoreStatus::Full;
                is_full = true;
            }
        }

        Ok(is_full)
    }

    /// Find a KV by key.
    fn find_kv(&mut self, key: &str) -> Option<KvInfo> {
        // Try cache first
        if let Some(addr) = self.get_kv_from_cache(key) {
            let mut kv = KvInfo::default();
            kv.addr_start = addr;
            if self.read_kv(&mut kv).is_ok() && kv.crc_is_ok {
                return Some(kv);
            }
        }

        // Linear scan
        let result = self.find_kv_no_cache(key);
        if let Some(ref kv) = result {
            self.update_kv_cache(key, kv.addr_start);
        }
        result
    }

    fn find_kv_no_cache(&mut self, key: &str) -> Option<KvInfo> {
        let mut kv = KvInfo::default();
        let mut found = false;
        self.kv_iterator(&mut kv, key, &mut found, Self::find_kv_cb);
        if found { Some(kv) } else { None }
    }

    fn find_kv_cb(kv: &KvInfo, key: &str, found: &mut bool) -> bool {
        let key_len = key.len();
        if kv.name_len as usize != key_len {
            return false;
        }
        if kv.crc_is_ok && kv.status == KvStatus::Write && &kv.name[..key_len] == key.as_bytes() {
            *found = true;
            return true;
        }
        false
    }

    /// Iterate over all KVs.
    fn kv_iterator<F>(&mut self, kv: &mut KvInfo, arg1: &str, arg2: &mut bool, callback: F)
    where
        F: Fn(&KvInfo, &str, &mut bool) -> bool,
    {
        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;
        let sec_hdr_sz = sector_hdr_data_size(self.sec_size) as u32;

        loop {
            traversed_len += self.sec_size;
            let sector = match self.read_sector_info(sec_addr, false) {
                Ok(s) => s,
                Err(_) => {
                    let next = self.get_next_sector_addr(&{
                        let mut s = KvdbSecInfo::default();
                        s.addr = sec_addr;
                        s.combined = SECTOR_NOT_COMBINED;
                        s
                    }, traversed_len);
                    if next == FDB_FAILED_ADDR { break; }
                    sec_addr = next;
                    continue;
                }
            };

            if sector.store_status == SectorStoreStatus::Using || sector.store_status == SectorStoreStatus::Full {
                kv.addr_start = sector.addr + sec_hdr_sz;
                loop {
                    if self.read_kv(kv).is_err() && !kv.crc_is_ok {
                        // Continue scanning
                    }
                    if callback(kv, arg1, arg2) {
                        return;
                    }
                    let next = self.get_next_kv_addr(&sector, kv);
                    if next == FDB_FAILED_ADDR { break; }
                    kv.addr_start = next;
                }
            }

            let next = self.get_next_sector_addr(&sector, traversed_len);
            if next == FDB_FAILED_ADDR { break; }
            sec_addr = next;
        }
    }

    /// Sector iterator.
    fn sector_iterator<F>(&mut self, status_filter: SectorStoreStatus, traversal: bool, mut callback: F)
    where
        F: FnMut(&mut Kvdb, &KvdbSecInfo) -> bool,
    {
        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;

        loop {
            traversed_len += self.sec_size;
            let sector = match self.read_sector_info(sec_addr, false) {
                Ok(s) => s,
                Err(_) => {
                    let next = self.get_next_sector_addr(&{
                        let mut s = KvdbSecInfo::default();
                        s.addr = sec_addr;
                        s.combined = SECTOR_NOT_COMBINED;
                        s
                    }, traversed_len);
                    if next == FDB_FAILED_ADDR { break; }
                    sec_addr = next;
                    continue;
                }
            };

            if status_filter == SectorStoreStatus::Unused || sector.store_status == status_filter {
                let sector = if traversal {
                    match self.read_sector_info(sec_addr, true) {
                        Ok(s) => s,
                        Err(_) => sector,
                    }
                } else {
                    sector
                };

                if callback(self, &sector) {
                    return;
                }
            }

            let next = self.get_next_sector_addr(&sector, traversed_len);
            if next == FDB_FAILED_ADDR { break; }
            sec_addr = next;
        }
    }

    /// Allocate a KV in a sector.
    fn alloc_kv(&mut self, kv_size: usize) -> (u32, KvdbSecInfo) {
        let mut empty_kv = FDB_FAILED_ADDR;
        let mut empty_sector = 0usize;
        let mut using_sector = 0usize;
        let threshold = sec_remain_threshold();

        // Statistics
        let mut temp_sector = KvdbSecInfo::default();
        let sec_addr_bak = self.oldest_addr;
        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;

        loop {
            traversed_len += self.sec_size;
            match self.read_sector_info(sec_addr, false) {
                Ok(sector) => {
                    if sector.check_ok && sector.store_status == SectorStoreStatus::Empty {
                        empty_sector += 1;
                    } else if sector.check_ok && sector.store_status == SectorStoreStatus::Using {
                        using_sector += 1;
                    }
                }
                Err(_) => {}
            }

            let next = self.get_next_sector_addr(&{
                let mut s = KvdbSecInfo::default();
                s.addr = sec_addr;
                s.combined = SECTOR_NOT_COMBINED;
                s
            }, traversed_len);
            if next == FDB_FAILED_ADDR { break; }
            sec_addr = next;
        }

        // Try using sectors first
        if using_sector > 0 {
            sec_addr = self.oldest_addr;
            traversed_len = 0;
            loop {
                traversed_len += self.sec_size;
                let sector = match self.read_sector_info(sec_addr, true) {
                    Ok(s) => s,
                    Err(_) => {
                        let next = self.get_next_sector_addr(&{
                            let mut s = KvdbSecInfo::default();
                            s.addr = sec_addr;
                            s.combined = SECTOR_NOT_COMBINED;
                            s
                        }, traversed_len);
                        if next == FDB_FAILED_ADDR { break; }
                        sec_addr = next;
                        continue;
                    }
                };

                if sector.check_ok && sector.remain > kv_size + threshold
                    && (sector.dirty_status == SectorDirtyStatus::False
                        || (sector.dirty_status == SectorDirtyStatus::True && !self.gc_request))
                    && sector.store_status == SectorStoreStatus::Using
                {
                    empty_kv = sector.empty_kv;
                    return (empty_kv, sector);
                }

                let next = self.get_next_sector_addr(&sector, traversed_len);
                if next == FDB_FAILED_ADDR { break; }
                sec_addr = next;
            }
        }

        // Try empty sectors
        if empty_sector > 0 && empty_kv == FDB_FAILED_ADDR {
            if empty_sector > FDB_GC_EMPTY_SEC_THRESHOLD || self.gc_request {
                sec_addr = self.oldest_addr;
                traversed_len = 0;
                loop {
                    traversed_len += self.sec_size;
                    let sector = match self.read_sector_info(sec_addr, true) {
                        Ok(s) => s,
                        Err(_) => {
                            let next = self.get_next_sector_addr(&{
                                let mut s = KvdbSecInfo::default();
                                s.addr = sec_addr;
                                s.combined = SECTOR_NOT_COMBINED;
                                s
                            }, traversed_len);
                            if next == FDB_FAILED_ADDR { break; }
                            sec_addr = next;
                            continue;
                        }
                    };

                    if sector.check_ok && sector.remain > kv_size + threshold
                        && (sector.dirty_status == SectorDirtyStatus::False
                            || (sector.dirty_status == SectorDirtyStatus::True && !self.gc_request))
                        && sector.store_status == SectorStoreStatus::Empty
                    {
                        empty_kv = sector.empty_kv;
                        return (empty_kv, sector);
                    }

                    let next = self.get_next_sector_addr(&sector, traversed_len);
                    if next == FDB_FAILED_ADDR { break; }
                    sec_addr = next;
                }
            } else {
                self.gc_request = true;
            }
        }

        (empty_kv, KvdbSecInfo::default())
    }

    /// Delete a KV.
    fn del_kv(&mut self, key: Option<&str>, old_kv: &KvInfo, complete_del: bool) -> Result<(), FdbErr> {
        let mut result = FdbErr::NoErr;

        if !complete_del {
            let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
            result = status::write_status(self.be(), old_kv.addr_start, &mut st, FDB_KV_STATUS_NUM, KvStatus::PreDelete as usize, false);
            self.last_is_complete_del = true;
        } else {
            let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
            result = status::write_status(self.be(), old_kv.addr_start, &mut st, FDB_KV_STATUS_NUM, KvStatus::Deleted as usize, true);

            if !self.last_is_complete_del && result == FdbErr::NoErr {
                if let Some(k) = key {
                    self.update_kv_cache(k, FDB_DATA_UNUSED);
                } else {
                    let name = std::str::from_utf8(&old_kv.name[..old_kv.name_len as usize]).unwrap_or("");
                    self.update_kv_cache(name, FDB_DATA_UNUSED);
                }
            }
            self.last_is_complete_del = false;
        }

        // Update dirty status
        if result == FdbErr::NoErr {
            let dirty_status_addr = fdb_align_down(old_kv.addr_start as usize, self.sec_size as usize) as u32
                + sector_dirty_offset() as u32;
            let mut dirty_st = vec![0u8; FDB_DIRTY_STATUS_TABLE_SIZE];
            let current_dirty = status::read_status(self.be(), dirty_status_addr, &mut dirty_st, FDB_SECTOR_DIRTY_STATUS_NUM);
            if current_dirty == SectorDirtyStatus::False as usize {
                let mut st = vec![0u8; FDB_DIRTY_STATUS_TABLE_SIZE];
                result = status::write_status(self.be(), dirty_status_addr, &mut st, FDB_SECTOR_DIRTY_STATUS_NUM, SectorDirtyStatus::True as usize, true);

                let sec_addr = fdb_align_down(old_kv.addr_start as usize, self.sec_size as usize) as u32;
                if let Some(idx) = self.get_sector_from_cache(sec_addr) {
                    self.sector_cache[idx].dirty_status = SectorDirtyStatus::True;
                }
            }
        }

        Ok(result)
    }

    /// Move a KV to new space.
    fn move_kv(&mut self, kv: &KvInfo) -> Result<(), FdbErr> {
        if kv.status == KvStatus::Write {
            self.del_kv(None, kv, false)?;
        }

        let (kv_addr, mut sector) = self.alloc_kv(kv.len as usize);
        if kv_addr == FDB_FAILED_ADDR {
            return Err(FdbErr::SavedFull);
        }

        // Update sector status
        self.update_sec_status(&mut sector, kv.len as usize)?;

        // Write KV header (pre-write status)
        let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
        status::write_status(self.be(), kv_addr, &mut st, FDB_KV_STATUS_NUM, KvStatus::PreWrite as usize, false)?;

        // Copy data
        let kv_hdr_sz = kv_hdr_data_size() as u32;
        let magic_off = kv_magic_offset() as u32;
        let kv_len = kv.len - magic_off;
        let mut buf = [0u8; 32];
        let mut len = 0u32;
        while len < kv_len {
            let size = if len + 32 < kv_len { 32 } else { kv_len - len };
            let read_size = wg_align(size as usize);
            let mut read_buf = vec![0u8; read_size];
            self.be().read(kv.addr_start + magic_off + len, &mut read_buf)?;
            self.be().write(kv_addr + magic_off + len, &read_buf[..size as usize], true)?;
            len += size as u32;
        }

        // Write status to WRITE
        let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
        status::write_status(self.be(), kv_addr, &mut st, FDB_KV_STATUS_NUM, KvStatus::Write as usize, true)?;

        // Update caches
        self.update_sector_empty_addr_cache(
            fdb_align_down(kv_addr as usize, self.sec_size as usize) as u32,
            kv_addr + kv_hdr_sz + wg_align(kv.name_len as usize) as u32 + wg_align(kv.value_len as usize) as u32,
        );
        let name = std::str::from_utf8(&kv.name[..kv.name_len as usize]).unwrap_or("");
        self.update_kv_cache(name, kv_addr);

        // Delete old KV
        self.del_kv(None, kv, true)?;

        Ok(())
    }

    /// GC collect by free size.
    fn gc_collect_by_free_size(&mut self, free_size: usize) {
        let mut empty_sec_num = 0usize;
        let mut empty_sec_addr = 0u32;

        // Check empty sector count
        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;
        loop {
            traversed_len += self.sec_size;
            match self.read_sector_info(sec_addr, false) {
                Ok(sector) => {
                    if sector.check_ok && sector.store_status == SectorStoreStatus::Empty {
                        empty_sec_num += 1;
                        empty_sec_addr = sector.addr;
                    }
                }
                Err(_) => {}
            }
            let next = self.get_next_sector_addr(&{
                let mut s = KvdbSecInfo::default();
                s.addr = sec_addr;
                s.combined = SECTOR_NOT_COMBINED;
                s
            }, traversed_len);
            if next == FDB_FAILED_ADDR { break; }
            sec_addr = next;
        }

        if empty_sec_num <= FDB_GC_EMPTY_SEC_THRESHOLD {
            // Do GC
            sec_addr = self.oldest_addr;
            traversed_len = 0;
            let mut last_gc_sec_addr = empty_sec_addr;
            loop {
                traversed_len += self.sec_size;
                let sector = match self.read_sector_info(sec_addr, false) {
                    Ok(s) => s,
                    Err(_) => {
                        let next = self.get_next_sector_addr(&{
                            let mut s = KvdbSecInfo::default();
                            s.addr = sec_addr;
                            s.combined = SECTOR_NOT_COMBINED;
                            s
                        }, traversed_len);
                        if next == FDB_FAILED_ADDR { break; }
                        sec_addr = next;
                        continue;
                    }
                };

                if sector.check_ok && (sector.dirty_status == SectorDirtyStatus::True || sector.dirty_status == SectorDirtyStatus::Gc) {
                    // Mark as GC
                    let dirty_addr = sector.addr + sector_dirty_offset() as u32;
                    let mut dirty_st = vec![0u8; FDB_DIRTY_STATUS_TABLE_SIZE];
                    let _ = status::write_status(self.be(), dirty_addr, &mut dirty_st, FDB_SECTOR_DIRTY_STATUS_NUM, SectorDirtyStatus::Gc as usize, true);

                    // Move all valid KVs
                    let sec_hdr_sz = sector_hdr_data_size(self.sec_size) as u32;
                    let mut kv_obj = KvInfo::default();
                    kv_obj.addr_start = sector.addr + sec_hdr_sz;
                    loop {
                        let _ = self.read_kv(&mut kv_obj);
                        if kv_obj.crc_is_ok && (kv_obj.status == KvStatus::Write || kv_obj.status == KvStatus::PreDelete) {
                            if self.move_kv(&kv_obj).is_err() {
                                break;
                            }
                        }
                        let next = self.get_next_kv_addr(&sector, &kv_obj);
                        if next == FDB_FAILED_ADDR { break; }
                        kv_obj.addr_start = next;
                    }

                    self.format_sector(sector.addr, SECTOR_NOT_COMBINED)?;
                    let old_last = last_gc_sec_addr;
                    last_gc_sec_addr = sector.addr;

                    // Update oldest_addr
                    let next_sec = self.get_next_sector_addr(&sector, 0);
                    self.oldest_addr = next_sec;

                    // Check if we have enough space
                    if let Ok(last_gc_sector) = self.read_sector_info(old_last, true) {
                        if last_gc_sector.remain > free_size {
                            break;
                        }
                    }
                }

                let next = self.get_next_sector_addr(&sector, traversed_len);
                if next == FDB_FAILED_ADDR { break; }
                sec_addr = next;
            }
        }

        self.gc_request = false;
    }

    /// Create a KV blob.
    fn create_kv_blob(&mut self, sector: &mut KvdbSecInfo, key: &str, value: &[u8]) -> Result<(), FdbErr> {
        let kv_hdr_sz = kv_hdr_data_size();
        let key_len = key.len();
        let value_len = value.len();

        if key_len > FDB_KV_NAME_MAX {
            return Err(FdbErr::KvNameErr);
        }

        let total_len = kv_hdr_sz + wg_align(key_len) + wg_align(value_len);
        if total_len > self.sec_size as usize - sector_hdr_data_size(self.sec_size) {
            return Err(FdbErr::SavedFull);
        }

        let kv_addr = if sector.empty_kv != FDB_FAILED_ADDR {
            sector.empty_kv
        } else {
            let (addr, _) = self.alloc_kv(total_len);
            if addr == FDB_FAILED_ADDR {
                // Try GC
                if self.gc_request {
                    self.gc_collect_by_free_size(total_len);
                    let (addr2, _) = self.alloc_kv(total_len);
                    if addr2 == FDB_FAILED_ADDR {
                        return Err(FdbErr::SavedFull);
                    }
                    addr2
                } else {
                    return Err(FdbErr::SavedFull);
                }
            } else {
                addr
            }
        };

        let is_full = self.update_sec_status(sector, total_len)?;

        // Build KV header
        let mut kv_hdr_buf = vec![FDB_BYTE_ERASED; kv_hdr_sz];
        // Status table: pre-write
        status::set_status(
            &mut kv_hdr_buf[..KV_STATUS_TABLE_SIZE],
            FDB_KV_STATUS_NUM,
            KvStatus::PreWrite as usize,
        );
        // Magic
        kv_hdr_buf[kv_magic_offset()..kv_magic_offset() + 4].copy_from_slice(&KV_MAGIC_WORD.to_le_bytes());
        // Len
        kv_hdr_buf[kv_len_offset()..kv_len_offset() + 4].copy_from_slice(&(total_len as u32).to_le_bytes());
        // Name_len
        kv_hdr_buf[kv_name_len_offset()] = key_len as u8;
        // Value_len
        kv_hdr_buf[kv_name_len_offset() + 1..kv_name_len_offset() + 5].copy_from_slice(&(value_len as u32).to_le_bytes());

        // Calculate CRC32
        let mut crc: u32 = 0;
        let name_len_bytes = (key_len as u32).to_le_bytes();
        crc = calc_crc32(crc, &name_len_bytes);
        let value_len_bytes = (value_len as u32).to_le_bytes();
        crc = calc_crc32(crc, &value_len_bytes);
        crc = calc_crc32(crc, key.as_bytes());
        // Pad name alignment
        let name_pad = wg_align(key_len) - key_len;
        for _ in 0..name_pad {
            crc = calc_crc32(crc, &[FDB_BYTE_ERASED]);
        }
        crc = calc_crc32(crc, value);
        let value_pad = wg_align(value_len) - value_len;
        for _ in 0..value_pad {
            crc = calc_crc32(crc, &[FDB_BYTE_ERASED]);
        }

        // CRC32 stored at offset kv_name_len_offset - 4
        let crc_off = kv_name_len_offset() - 4;
        kv_hdr_buf[crc_off..crc_off + 4].copy_from_slice(&crc.to_le_bytes());

        // Write header (first status, then rest)
        status::write_status(self.be(), kv_addr, &mut kv_hdr_buf[..KV_STATUS_TABLE_SIZE].to_vec(), FDB_KV_STATUS_NUM, KvStatus::PreWrite as usize, false)?;
        self.be().write(kv_addr + kv_magic_offset() as u32, &kv_hdr_buf[kv_magic_offset()..], false)?;

        // Write key name
        status::write_align(self.be(), kv_addr + kv_hdr_sz as u32, key.as_bytes())?;

        // Update cache
        if !is_full {
            self.update_sector_empty_addr_cache(
                sector.addr,
                kv_addr + kv_hdr_sz as u32 + wg_align(key_len) as u32 + wg_align(value_len) as u32,
            );
        }
        self.update_kv_cache(key, kv_addr);

        // Write value
        status::write_align(self.be(), kv_addr + kv_hdr_sz as u32 + wg_align(key_len) as u32, value)?;

        // Set status to WRITE
        let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
        status::write_status(self.be(), kv_addr, &mut st, FDB_KV_STATUS_NUM, KvStatus::Write as usize, true)?;

        if is_full {
            self.gc_request = true;
        }

        Ok(())
    }

    /// Set a KV value.
    fn set_kv(&mut self, key: &str, value: &[u8]) -> Result<(), FdbErr> {
        if value.is_empty() {
            // Delete
            return self.del_kv(Some(key), &KvInfo::default(), true);
        }

        let kv_len = kv_hdr_data_size() + wg_align(key.len()) + wg_align(value.len());
        let (empty_addr, _) = self.alloc_kv(kv_len);
        if empty_addr == FDB_FAILED_ADDR {
            if self.gc_request {
                self.gc_collect_by_free_size(kv_len);
                let (empty_addr2, _) = self.alloc_kv(kv_len);
                if empty_addr2 == FDB_FAILED_ADDR {
                    return Err(FdbErr::SavedFull);
                }
            } else {
                return Err(FdbErr::SavedFull);
            }
        }

        let kv_is_found = self.find_kv(key);
        if let Some(ref old_kv) = kv_is_found {
            self.del_kv(Some(key), old_kv, false)?;
        }

        let mut sector = KvdbSecInfo::default();
        sector.empty_kv = FDB_FAILED_ADDR;
        let result = self.create_kv_blob(&mut sector, key, value);

        if let Some(ref old_kv) = kv_is_found {
            if result.is_ok() {
                let _ = self.del_kv(Some(key), old_kv, true);
            }
        }

        if self.gc_request {
            self.gc_collect_by_free_size(kv_hdr_data_size() + wg_align(key.len()) + wg_align(value.len()));
        }

        result
    }

    /// Get a KV value.
    fn get_kv(&mut self, key: &str, value_buf: &mut [u8]) -> (usize, usize) {
        if let Some(kv) = self.find_kv(key) {
            let value_len = kv.value_len as usize;
            let read_len = value_buf.len().min(value_len);
            if self.be().read(kv.addr_value, &mut value_buf[..read_len]).is_err() {
                return (0, value_len);
            }
            (read_len, value_len)
        } else {
            (0, 0)
        }
    }

    // ---- Public API ----

    pub fn init(&mut self, name: &str, path: &str, default_kv: Option<&DefaultKv>, user_data: *mut core::ffi::c_void) -> Result<(), FdbErr> {
        if self.init_ok {
            return Ok(());
        }

        self.name = name.to_string();
        self.dir = path.to_string();
        self.user_data = user_data;

        if self.file_mode {
            // Create directory if needed
            let _ = std::fs::create_dir_all(path);

            assert!(self.sec_size != 0);
            assert!(self.max_size != 0);
        }

        // Validate
        if self.sec_size & (self.sec_size - 1) != 0 {
            return Err(FdbErr::InitFailed);
        }
        if self.max_size % self.sec_size != 0 {
            return Err(FdbErr::InitFailed);
        }
        if self.max_size / self.sec_size < 2 {
            return Err(FdbErr::InitFailed);
        }

        // Setup backend
        self.backend = Some(Box::new(crate::FileBackend::new(name, path, self.sec_size, self.max_size)));

        self.db_lock();

        self.gc_request = false;
        self.in_recovery_check = false;
        if let Some(dkv) = default_kv {
            self.default_kvs = dkv.clone();
        } else {
            self.default_kvs = DefaultKv::default();
        }

        // Find oldest sector
        {
            self.oldest_addr = 0;
            let mut sector_oldest_addr = 0u32;
            let mut last_sector_status = SectorStoreStatus::Unused;

            let mut sec_addr = 0u32;
            let mut traversed_len = 0u32;
            loop {
                traversed_len += self.sec_size;
                match self.read_sector_info(sec_addr, false) {
                    Ok(sector) => {
                        if last_sector_status == SectorStoreStatus::Empty
                            && (sector.store_status == SectorStoreStatus::Full || sector.store_status == SectorStoreStatus::Using)
                        {
                            sector_oldest_addr = sector.addr;
                        }
                        last_sector_status = sector.store_status;
                    }
                    Err(_) => {}
                }
                let next = {
                    let mut s = KvdbSecInfo::default();
                    s.addr = sec_addr;
                    s.combined = SECTOR_NOT_COMBINED;
                    s
                };
                let n = self.get_next_sector_addr(&next, traversed_len);
                if n == FDB_FAILED_ADDR { break; }
                sec_addr = n;
            }
            self.oldest_addr = sector_oldest_addr;
        }

        // Initialize cache
        for i in 0..self.sector_cache.len() {
            self.sector_cache[i].check_ok = false;
            self.sector_cache[i].empty_kv = FDB_FAILED_ADDR;
            self.sector_cache[i].addr = FDB_DATA_UNUSED;
        }
        for i in 0..self.kv_cache.len() {
            self.kv_cache[i].addr = FDB_DATA_UNUSED;
        }

        self.db_unlock();

        // Load and recovery
        let result = self.kv_load();

        self.db_lock();
        self.db_unlock();

        if result.is_ok() {
            self.init_ok = true;
        }

        result
    }

    fn kv_load(&mut self) -> Result<(), FdbErr> {
        self.in_recovery_check = true;

        // Check all sector headers
        let mut check_failed_count = 0usize;
        let sec_num = self.max_size / self.sec_size;

        let mut sec_addr = 0u32;
        let mut traversed_len = 0u32;
        loop {
            traversed_len += self.sec_size;
            match self.read_sector_info(sec_addr, false) {
                Ok(sector) => {
                    if !sector.check_ok {
                        check_failed_count += 1;
                        if !self.not_formatable {
                            self.format_sector(sector.addr, SECTOR_NOT_COMBINED)?;
                        }
                    }
                }
                Err(_) => {
                    check_failed_count += 1;
                    if !self.not_formatable {
                        self.format_sector(sec_addr, SECTOR_NOT_COMBINED)?;
                    }
                }
            }
            let next = {
                let mut s = KvdbSecInfo::default();
                s.addr = sec_addr;
                s.combined = SECTOR_NOT_COMBINED;
                s
            };
            let n = self.get_next_sector_addr(&next, traversed_len);
            if n == FDB_FAILED_ADDR { break; }
            sec_addr = n;
        }

        if self.not_formatable && check_failed_count > 0 {
            return Err(FdbErr::ReadErr);
        }

        if check_failed_count == sec_num as usize {
            self.set_default()?;
        }

        // Recovery GC
        sec_addr = 0;
        traversed_len = 0;
        loop {
            traversed_len += self.sec_size;
            if let Ok(sector) = self.read_sector_info(sec_addr, false) {
                if sector.check_ok && sector.dirty_status == SectorDirtyStatus::Gc {
                    self.gc_request = true;
                    self.gc_collect();
                }
            }
            let next = {
                let mut s = KvdbSecInfo::default();
                s.addr = sec_addr;
                s.combined = SECTOR_NOT_COMBINED;
                s
            };
            let n = self.get_next_sector_addr(&next, traversed_len);
            if n == FDB_FAILED_ADDR { break; }
            sec_addr = n;
        }

        // Recovery KVs
        loop {
            let mut kv = KvInfo::default();
            let mut need_gc = false;
            let mut sec_addr = self.oldest_addr;
            let mut traversed_len = 0u32;
            let sec_hdr_sz = sector_hdr_data_size(self.sec_size) as u32;

            loop {
                traversed_len += self.sec_size;
                let sector = match self.read_sector_info(sec_addr, false) {
                    Ok(s) => s,
                    Err(_) => {
                        let next = {
                            let mut s = KvdbSecInfo::default();
                            s.addr = sec_addr;
                            s.combined = SECTOR_NOT_COMBINED;
                            s
                        };
                        let n = self.get_next_sector_addr(&next, traversed_len);
                        if n == FDB_FAILED_ADDR { break; }
                        sec_addr = n;
                        continue;
                    }
                };

                if sector.store_status == SectorStoreStatus::Using || sector.store_status == SectorStoreStatus::Full {
                    kv.addr_start = sector.addr + sec_hdr_sz;
                    loop {
                        let _ = self.read_kv(&mut kv);
                        if kv.crc_is_ok && kv.status == KvStatus::PreDelete {
                            if self.move_kv(&kv).is_err() {
                                need_gc = true;
                                break;
                            }
                        } else if kv.status == KvStatus::PreWrite {
                            let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
                            let _ = status::write_status(self.be(), kv.addr_start, &mut st, FDB_KV_STATUS_NUM, KvStatus::ErrHdr as usize, true);
                            break;
                        } else if kv.crc_is_ok && kv.status == KvStatus::Write {
                            let name = std::str::from_utf8(&kv.name[..kv.name_len as usize]).unwrap_or("");
                            self.update_kv_cache(name, kv.addr_start);
                        }
                        let next = self.get_next_kv_addr(&sector, &kv);
                        if next == FDB_FAILED_ADDR { break; }
                        kv.addr_start = next;
                    }
                }

                let next = {
                    let mut s = KvdbSecInfo::default();
                    s.addr = sec_addr;
                    s.combined = sector.combined;
                    s
                };
                let n = self.get_next_sector_addr(&next, traversed_len);
                if n == FDB_FAILED_ADDR { break; }
                sec_addr = n;
            }

            if self.gc_request {
                self.gc_collect();
            } else {
                break;
            }
        }

        self.in_recovery_check = false;
        Ok(())
    }

    fn gc_collect(&mut self) {
        self.gc_collect_by_free_size(self.max_size as usize);
    }

    /// Set a string KV.
    pub fn kv_set(&mut self, key: &str, value: &str) -> Result<(), FdbErr> {
        if !self.init_ok {
            return Err(FdbErr::InitFailed);
        }
        self.db_lock();
        let result = self.set_kv(key, value.as_bytes());
        self.db_unlock();
        result
    }

    /// Get a string KV.
    pub fn kv_get(&mut self, key: &str) -> Option<String> {
        if !self.init_ok {
            return None;
        }
        self.db_lock();
        let mut value_buf = vec![0u8; FDB_STR_KV_VALUE_MAX_SIZE];
        let (read_len, value_len) = self.get_kv(key, &mut value_buf);
        self.db_unlock();

        if read_len > 0 {
            // Check if string
            let is_str = value_buf[..read_len].iter().all(|&b| b >= 0x20 && b < 0x7F);
            if is_str {
                value_buf[read_len] = 0;
                Some(String::from_utf8_lossy(&value_buf[..read_len]).to_string())
            } else {
                None
            }
        } else {
            None
        }
    }

    /// Set a blob KV.
    pub fn kv_set_blob(&mut self, key: &str, value: &[u8]) -> Result<(), FdbErr> {
        if !self.init_ok {
            return Err(FdbErr::InitFailed);
        }
        self.db_lock();
        let result = self.set_kv(key, value);
        self.db_unlock();
        result
    }

    /// Get a blob KV.
    pub fn kv_get_blob(&mut self, key: &str, buf: &mut [u8]) -> usize {
        if !self.init_ok {
            return 0;
        }
        self.db_lock();
        let (read_len, _) = self.get_kv(key, buf);
        self.db_unlock();
        read_len
    }

    /// Delete a KV.
    pub fn kv_del(&mut self, key: &str) -> Result<(), FdbErr> {
        if !self.init_ok {
            return Err(FdbErr::InitFailed);
        }
        self.db_lock();
        let kv = self.find_kv(key);
        match kv {
            Some(old_kv) => {
                let result = self.del_kv(Some(key), &old_kv, true);
                self.db_unlock();
                result
            }
            None => {
                self.db_unlock();
                Err(FdbErr::KvNameErr)
            }
        }
    }

    /// Set default KVs.
    pub fn set_default(&mut self) -> Result<(), FdbErr> {
        self.db_lock();

        // Clear cache
        for i in 0..self.kv_cache.len() {
            self.kv_cache[i].addr = FDB_DATA_UNUSED;
        }

        // Format all sectors
        let mut addr = 0u32;
        while addr < self.max_size {
            self.format_sector(addr, SECTOR_NOT_COMBINED)?;
            addr += self.sec_size;
        }

        // Create default KVs
        for node in &self.default_kvs.kvs {
            let mut sector = KvdbSecInfo::default();
            sector.empty_kv = FDB_FAILED_ADDR;
            self.create_kv_blob(&mut sector, &node.key, &node.value)?;
        }

        self.oldest_addr = 0;
        self.db_unlock();
        Ok(())
    }

    /// Deinitialize.
    pub fn deinit(&mut self) -> Result<(), FdbErr> {
        self.init_ok = false;
        self.backend = None;
        Ok(())
    }

    /// Check database integrity.
    pub fn check(&mut self) -> Result<(), FdbErr> {
        if !self.init_ok {
            return Err(FdbErr::InitFailed);
        }
        self.db_lock();

        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;
        let sec_hdr_sz = sector_hdr_data_size(self.sec_size) as u32;
        let mut result = FdbErr::NoErr;

        loop {
            traversed_len += self.sec_size;
            match self.read_sector_info(sec_addr, false) {
                Ok(sector) => {
                    if sector.store_status == SectorStoreStatus::Using || sector.store_status == SectorStoreStatus::Full {
                        let mut kv = KvInfo::default();
                        kv.addr_start = sector.addr + sec_hdr_sz;
                        loop {
                            result = self.read_kv(&mut kv).err().unwrap_or(FdbErr::NoErr);
                            let next = self.get_next_kv_addr(&sector, &kv);
                            if next == FDB_FAILED_ADDR || result != FdbErr::NoErr { break; }
                            kv.addr_start = next;
                        }
                    }
                }
                Err(e) => { result = e; }
            }

            let next = {
                let mut s = KvdbSecInfo::default();
                s.addr = sec_addr;
                s.combined = SECTOR_NOT_COMBINED;
                s
            };
            let n = self.get_next_sector_addr(&next, traversed_len);
            if n == FDB_FAILED_ADDR || result != FdbErr::NoErr { break; }
            sec_addr = n;
        }

        self.db_unlock();
        if result == FdbErr::NoErr { Ok(()) } else { Err(result) }
    }

    /// Control interface.
    pub fn control(&mut self, cmd: i32, arg: *mut core::ffi::c_void) {
        match cmd {
            crate::FDB_KVDB_CTRL_SET_SEC_SIZE => {
                assert!(!self.init_ok);
                unsafe { self.sec_size = *(arg as *const u32); }
            }
            crate::FDB_KVDB_CTRL_GET_SEC_SIZE => {
                unsafe { *(arg as *mut u32) = self.sec_size; }
            }
            crate::FDB_KVDB_CTRL_SET_LOCK => {
                unsafe { self.lock_fn = Some(std::mem::transmute(arg)); }
            }
            crate::FDB_KVDB_CTRL_SET_UNLOCK => {
                unsafe { self.unlock_fn = Some(std::mem::transmute(arg)); }
            }
            crate::FDB_KVDB_CTRL_SET_FILE_MODE => {
                assert!(!self.init_ok);
                unsafe { self.file_mode = *(arg as *const bool); }
            }
            crate::FDB_KVDB_CTRL_SET_MAX_SIZE => {
                assert!(!self.init_ok);
                unsafe { self.max_size = *(arg as *const u32); }
            }
            crate::FDB_KVDB_CTRL_SET_NOT_FORMAT => {
                assert!(!self.init_ok);
                unsafe { self.not_formatable = *(arg as *const bool); }
            }
            _ => {}
        }
    }
}

// FFI-compat constant
const FDB_SEC_REMAIN_THRESHOLD: usize = 0; // computed dynamically

//! TSDB — Time Series Database implementation.
//! Faithful translation of fdb_tsdb.c.

use crate::{
    StorageBackend, FdbErr, FdbTime, FDB_BYTE_ERASED, FDB_DATA_UNUSED, FDB_FAILED_ADDR,
    TSDB_SECTOR_MAGIC_WORD, SECTOR_NOT_COMBINED,
    TslStatus, SectorStoreStatus, Blob, TslInfo, TsdbSecInfo,
    calc_crc32, status, wg_align, fdb_align_down, status_table_size,
    FDB_STORE_STATUS_TABLE_SIZE, FDB_TSL_STATUS_NUM, TSL_STATUS_TABLE_SIZE,
    FDB_SECTOR_STORE_STATUS_NUM, DbType,
    FDB_TSDB_CTRL_SET_SEC_SIZE, FDB_TSDB_CTRL_GET_SEC_SIZE,
    FDB_TSDB_CTRL_SET_LOCK, FDB_TSDB_CTRL_SET_UNLOCK,
    FDB_TSDB_CTRL_SET_ROLLOVER, FDB_TSDB_CTRL_GET_ROLLOVER,
    FDB_TSDB_CTRL_GET_LAST_TIME, FDB_TSDB_CTRL_SET_FILE_MODE,
    FDB_TSDB_CTRL_SET_MAX_SIZE, FDB_TSDB_CTRL_SET_NOT_FORMAT,
};

/// Sector header data size (computed).
fn sector_hdr_data_size() -> usize {
    // For FDB_WRITE_GRAN=1, fdb_time_t=i32:
    // status + magic(aligned_u32) + start_time(aligned_i32) + end_info[2](time+index+status) + reserved
    let tsl_uint32_align = wg_align(4);
    let tsl_time_align = wg_align(4); // sizeof(i32) = 4
    let raw = FDB_STORE_STATUS_TABLE_SIZE
        + tsl_uint32_align // magic
        + tsl_time_align  // start_time
        + 2 * (tsl_time_align + tsl_uint32_align + TSL_STATUS_TABLE_SIZE) // end_info
        + 4; // reserved
    wg_align(raw)
}

/// Log index data size.
fn log_idx_data_size() -> usize {
    // For FDB_WRITE_GRAN=1, fdb_time_t=i32, variable blob size:
    // status_table + time + log_len + log_addr
    let raw = TSL_STATUS_TABLE_SIZE + 4 + 4 + 4;
    wg_align(raw)
}

fn log_idx_ts_offset() -> usize { TSL_STATUS_TABLE_SIZE }

fn sector_magic_offset() -> usize { FDB_STORE_STATUS_TABLE_SIZE }

fn sector_start_time_offset() -> usize {
    FDB_STORE_STATUS_TABLE_SIZE + wg_align(4) // magic
}

fn sector_end0_time_offset() -> usize {
    sector_start_time_offset() + wg_align(4) // start_time
}

fn sector_end0_idx_offset() -> usize {
    sector_end0_time_offset() + wg_align(4) // time
}

fn sector_end0_status_offset() -> usize {
    sector_end0_idx_offset() + wg_align(4) // index
}

fn sector_end1_time_offset() -> usize {
    sector_end0_status_offset() + TSL_STATUS_TABLE_SIZE
}

fn sector_end1_idx_offset() -> usize {
    sector_end1_time_offset() + wg_align(4)
}

fn sector_end1_status_offset() -> usize {
    sector_end1_idx_offset() + wg_align(4)
}

pub struct Tsdb {
    pub name: String,
    pub sec_size: u32,
    pub max_size: u32,
    pub oldest_addr: u32,
    pub init_ok: bool,
    pub file_mode: bool,
    pub not_formatable: bool,
    pub dir: String,
    pub cur_sec: TsdbSecInfo,
    pub last_time: FdbTime,
    pub get_time_fn: Option<fn() -> FdbTime>,
    pub max_len: usize,
    pub rollover: bool,
    pub lock_fn: Option<fn(*mut core::ffi::c_void)>,
    pub unlock_fn: Option<fn(*mut core::ffi::c_void)>,
    pub user_data: *mut core::ffi::c_void,
    pub backend: Option<Box<dyn StorageBackend>>,
}

impl Tsdb {
    pub fn new() -> Self {
        Tsdb {
            name: String::new(),
            sec_size: 0,
            max_size: 0,
            oldest_addr: 0,
            init_ok: false,
            file_mode: true,
            not_formatable: false,
            dir: String::new(),
            cur_sec: TsdbSecInfo::default(),
            last_time: 0,
            get_time_fn: None,
            max_len: 0,
            rollover: true,
            lock_fn: None,
            unlock_fn: None,
            user_data: std::ptr::null_mut(),
            backend: None,
        }
    }

    fn be(&mut self) -> &mut dyn StorageBackend {
        self.backend.as_deref_mut().unwrap()
    }

    fn db_lock(&self) {
        if let Some(lock) = self.lock_fn {
            lock(self.user_data);
        }
    }

    fn db_unlock(&self) {
        if let Some(unlock) = self.unlock_fn {
            unlock(self.user_data);
        }
    }

    /// Read TSL from flash.
    fn read_tsl(&mut self, tsl: &mut TslInfo) -> Result<(), FdbErr> {
        let idx_size = log_idx_data_size();
        let mut idx_buf = vec![0u8; idx_size];
        self.be().read(tsl.addr_index, &mut idx_buf)?;

        let st = status::get_status(&idx_buf[..TSL_STATUS_TABLE_SIZE], FDB_TSL_STATUS_NUM);
        tsl.status = match st {
            0 => TslStatus::Unused,
            1 => TslStatus::PreWrite,
            2 => TslStatus::Write,
            3 => TslStatus::UserStatus1,
            4 => TslStatus::Deleted,
            5 => TslStatus::UserStatus2,
            _ => TslStatus::Unused,
        };

        if tsl.status == TslStatus::PreWrite || tsl.status == TslStatus::Unused {
            tsl.log_len = self.max_len as u32;
            tsl.addr_log = FDB_DATA_UNUSED;
            tsl.time = 0;
        } else {
            let ts_off = log_idx_ts_offset();
            tsl.time = i32::from_le_bytes(idx_buf[ts_off..ts_off + 4].try_into().unwrap());
            tsl.log_len = u32::from_le_bytes(idx_buf[ts_off + 4..ts_off + 8].try_into().unwrap());
            tsl.addr_log = u32::from_le_bytes(idx_buf[ts_off + 8..ts_off + 12].try_into().unwrap());
        }

        Ok(())
    }

    /// Get next sector address.
    fn get_next_sector_addr(&self, pre_sec: &TsdbSecInfo, traversed_len: u32) -> u32 {
        if traversed_len + self.sec_size <= self.max_size {
            if pre_sec.addr + self.sec_size < self.max_size {
                pre_sec.addr + self.sec_size
            } else {
                0
            }
        } else {
            FDB_FAILED_ADDR
        }
    }

    /// Get last sector address.
    fn get_last_sector_addr(&self, pre_sec: &TsdbSecInfo, traversed_len: u32) -> u32 {
        if traversed_len + self.sec_size <= self.max_size {
            if pre_sec.addr >= self.sec_size {
                pre_sec.addr - self.sec_size
            } else {
                self.max_size - self.sec_size
            }
        } else {
            FDB_FAILED_ADDR
        }
    }

    /// Get next TSL address.
    fn get_next_tsl_addr(&self, sector: &TsdbSecInfo, pre_tsl: &TslInfo) -> u32 {
        if sector.status == SectorStoreStatus::Empty {
            return FDB_FAILED_ADDR;
        }
        if pre_tsl.addr_index + log_idx_data_size() as u32 <= sector.end_idx {
            pre_tsl.addr_index + log_idx_data_size() as u32
        } else {
            FDB_FAILED_ADDR
        }
    }

    /// Get last TSL address.
    fn get_last_tsl_addr(&self, sector: &TsdbSecInfo, pre_tsl: &TslInfo) -> u32 {
        if sector.status == SectorStoreStatus::Empty {
            return FDB_FAILED_ADDR;
        }
        if pre_tsl.addr_index >= sector.addr + sector_hdr_data_size() as u32 + log_idx_data_size() as u32 {
            pre_tsl.addr_index - log_idx_data_size() as u32
        } else {
            FDB_FAILED_ADDR
        }
    }

    /// Read sector info.
    fn read_sector_info(&mut self, addr: u32, traversal: bool) -> Result<TsdbSecInfo, FdbErr> {
        let sec_hdr_sz = sector_hdr_data_size();
        let mut sec_hdr_buf = vec![0u8; sec_hdr_sz];
        self.be().read(addr, &mut sec_hdr_buf)?;

        let mut sector = TsdbSecInfo::default();
        sector.addr = addr;

        // Parse magic
        let magic_off = sector_magic_offset();
        sector.magic = u32::from_le_bytes(sec_hdr_buf[magic_off..magic_off + 4].try_into().unwrap());

        if sector.magic != TSDB_SECTOR_MAGIC_WORD {
            sector.check_ok = false;
            return Err(FdbErr::InitFailed);
        }

        sector.check_ok = true;
        let st = status::get_status(&sec_hdr_buf[..FDB_STORE_STATUS_TABLE_SIZE], FDB_SECTOR_STORE_STATUS_NUM);
        sector.status = match st {
            0 => SectorStoreStatus::Unused,
            1 => SectorStoreStatus::Empty,
            2 => SectorStoreStatus::Using,
            3 => SectorStoreStatus::Full,
            _ => SectorStoreStatus::Unused,
        };

        // Parse start_time
        let st_off = sector_start_time_offset();
        sector.start_time = i32::from_le_bytes(sec_hdr_buf[st_off..st_off + 4].try_into().unwrap());

        // Parse end_info
        for i in 0..2 {
            let (time_off, idx_off, status_off) = if i == 0 {
                (sector_end0_time_offset(), sector_end0_idx_offset(), sector_end0_status_offset())
            } else {
                (sector_end1_time_offset(), sector_end1_idx_offset(), sector_end1_status_offset())
            };
            sector.end_info_stat[i] = match status::get_status(
                &sec_hdr_buf[status_off..status_off + TSL_STATUS_TABLE_SIZE],
                FDB_TSL_STATUS_NUM,
            ) {
                0 => TslStatus::Unused,
                1 => TslStatus::PreWrite,
                2 => TslStatus::Write,
                3 => TslStatus::UserStatus1,
                4 => TslStatus::Deleted,
                5 => TslStatus::UserStatus2,
                _ => TslStatus::Unused,
            };
        }

        if sector.end_info_stat[0] == TslStatus::Write {
            let time_off = sector_end0_time_offset();
            sector.end_time = i32::from_le_bytes(sec_hdr_buf[time_off..time_off + 4].try_into().unwrap());
            let idx_off = sector_end0_idx_offset();
            sector.end_idx = u32::from_le_bytes(sec_hdr_buf[idx_off..idx_off + 4].try_into().unwrap());
        } else if sector.end_info_stat[1] == TslStatus::Write {
            let time_off = sector_end1_time_offset();
            sector.end_time = i32::from_le_bytes(sec_hdr_buf[time_off..time_off + 4].try_into().unwrap());
            let idx_off = sector_end1_idx_offset();
            sector.end_idx = u32::from_le_bytes(sec_hdr_buf[idx_off..idx_off + 4].try_into().unwrap());
        }

        sector.empty_idx = sector.addr + sec_hdr_sz as u32;
        sector.empty_data = sector.addr + self.sec_size;
        sector.remain = (sector.empty_data - sector.empty_idx) as usize;

        if sector.status == SectorStoreStatus::Using && traversal {
            let mut tsl = TslInfo::default();
            tsl.addr.index = sector.empty_idx;

            while self.read_tsl(&mut tsl).is_ok() {
                if tsl.status == TslStatus::Unused {
                    break;
                }
                if tsl.status != TslStatus::PreWrite {
                    sector.end_time = tsl.time;
                }
                sector.end_idx = tsl.addr.index;
                sector.empty_idx += log_idx_data_size() as u32;
                sector.empty_data -= wg_align(tsl.log_len as usize) as u32;
                let consumed = log_idx_data_size() + wg_align(tsl.log_len as usize);
                if sector.remain > consumed {
                    sector.remain -= consumed;
                } else {
                    sector.remain = 0;
                    break;
                }
                tsl.addr.index += log_idx_data_size() as u32;
            }
        }

        Ok(sector)
    }

    /// Format a sector.
    fn format_sector(&mut self, addr: u32) -> Result<(), FdbErr> {
        assert_eq!(addr % self.sec_size, 0);

        self.be().erase(addr, self.sec_size as usize)?;

        let mut st = vec![0u8; FDB_STORE_STATUS_TABLE_SIZE];
        status::write_status(self.be(), addr, &mut st, FDB_SECTOR_STORE_STATUS_NUM, SectorStoreStatus::Empty as usize, true)?;

        // Write magic
        let mut magic_buf = vec![FDB_BYTE_ERASED; wg_align(4)];
        magic_buf[..4].copy_from_slice(&TSDB_SECTOR_MAGIC_WORD.to_le_bytes());
        self.be().write(addr + sector_magic_offset() as u32, &magic_buf, true)?;

        Ok(())
    }

    /// Sector iterator.
    fn sector_iterator<F>(&mut self, start_addr: u32, status_filter: SectorStoreStatus, traversal: bool, get_next: fn(&Tsdb, &TsdbSecInfo, u32) -> u32, mut callback: F)
    where
        F: FnMut(&TsdbSecInfo) -> bool,
    {
        let mut sec_addr = start_addr;
        let mut traversed_len = 0u32;

        loop {
            traversed_len += self.sec_size;
            match self.read_sector_info(sec_addr, false) {
                Ok(sector) => {
                    if status_filter == SectorStoreStatus::Unused || sector.status == status_filter {
                        let sector = if traversal {
                            self.read_sector_info(sec_addr, true).unwrap_or(sector)
                        } else {
                            sector
                        };
                        if callback(&sector) {
                            return;
                        }
                    }
                }
                Err(_) => {}
            }

            let next = {
                let mut s = TsdbSecInfo::default();
                s.addr = sec_addr;
                s
            };
            let n = get_next(self, &next, traversed_len);
            if n == FDB_FAILED_ADDR { break; }
            sec_addr = n;
        }
    }

    /// Write a TSL.
    fn write_tsl(&mut self, blob: &[u8], time: FdbTime) -> Result<(), FdbErr> {
        let idx_data_sz = log_idx_data_size();
        let idx_addr = self.cur_sec.empty_idx;
        let log_addr = self.cur_sec.empty_data - wg_align(blob.len()) as u32;

        // Build index data
        let ts_off = log_idx_ts_offset();
        let mut idx_buf = vec![FDB_BYTE_ERASED; idx_data_sz];
        // Status will be written separately
        // Write time
        idx_buf[ts_off..ts_off + 4].copy_from_slice(&time.to_le_bytes());
        // Write log_len
        idx_buf[ts_off + 4..ts_off + 8].copy_from_slice(&(blob.len() as u32).to_le_bytes());
        // Write log_addr
        idx_buf[ts_off + 8..ts_off + 12].copy_from_slice(&log_addr.to_le_bytes());

        // Write pre-write status
        let mut st = vec![0u8; TSL_STATUS_TABLE_SIZE];
        status::write_status(self.be(), idx_addr, &mut st, FDB_TSL_STATUS_NUM, TslStatus::PreWrite as usize, false)?;

        // Write rest of index
        self.be().write(idx_addr + ts_off as u32, &idx_buf[ts_off..], false)?;

        // Write blob data
        status::write_align(self.be(), log_addr, blob)?;

        // Write WRITE status
        let mut st = vec![0u8; TSL_STATUS_TABLE_SIZE];
        status::write_status(self.be(), idx_addr, &mut st, FDB_TSL_STATUS_NUM, TslStatus::Write as usize, true)?;

        Ok(())
    }

    /// Update sector status for TSL append.
    fn update_sec_status(&mut self, blob_len: usize, cur_time: FdbTime) -> Result<(), FdbErr> {
        let idx_data_sz = log_idx_data_size();
        let aligned_blob = wg_align(blob_len);
        let needed = idx_data_sz + aligned_blob;

        if self.cur_sec.status == SectorStoreStatus::Using && self.cur_sec.remain < needed {
            // Sector is full, save end info
            let end_index_temp = self.cur_sec.empty_idx - idx_data_sz as u32;
            let cur_sec_addr = self.cur_sec.addr;

            // Save end info
            for slot in 0..2 {
                let (time_off, idx_off, status_off) = if slot == 0 {
                    (sector_end0_time_offset(), sector_end0_idx_offset(), sector_end0_status_offset())
                } else {
                    (sector_end1_time_offset(), sector_end1_idx_offset(), sector_end1_status_offset())
                };

                if self.cur_sec.end_info_stat[slot] == TslStatus::Unused {
                    let mut st = vec![0u8; TSL_STATUS_TABLE_SIZE];
                    status::write_status(self.be(), cur_sec_addr + status_off as u32, &mut st, FDB_TSL_STATUS_NUM, TslStatus::PreWrite as usize, false)?;
                    let mut time_buf = vec![FDB_BYTE_ERASED; wg_align(4)];
                    time_buf[..4].copy_from_slice(&self.last_time.to_le_bytes());
                    self.be().write(cur_sec_addr + time_off as u32, &time_buf, false)?;
                    let mut idx_buf = vec![FDB_BYTE_ERASED; wg_align(4)];
                    idx_buf[..4].copy_from_slice(&end_index_temp.to_le_bytes());
                    self.be().write(cur_sec_addr + idx_off as u32, &idx_buf, false)?;
                    let mut st = vec![0u8; TSL_STATUS_TABLE_SIZE];
                    status::write_status(self.be(), cur_sec_addr + status_off as u32, &mut st, FDB_TSL_STATUS_NUM, TslStatus::Write as usize, true)?;
                    break;
                }
            }

            // Change sector to FULL
            let mut st = vec![0u8; FDB_STORE_STATUS_TABLE_SIZE];
            status::write_status(self.be(), cur_sec_addr, &mut st, FDB_SECTOR_STORE_STATUS_NUM, SectorStoreStatus::Full as usize, true)?;
            self.cur_sec.status = SectorStoreStatus::Full;

            // Find next sector
            let new_sec_addr = if cur_sec_addr + self.sec_size < self.max_size {
                cur_sec_addr + self.sec_size
            } else if self.rollover {
                0
            } else {
                return Err(FdbErr::SavedFull);
            };

            self.read_sector_info_inner(new_sec_addr, false)?;
            if self.cur_sec.status != SectorStoreStatus::Empty {
                self.oldest_addr = if new_sec_addr + self.sec_size < self.max_size {
                    new_sec_addr + self.sec_size
                } else {
                    0
                };
                self.format_sector(new_sec_addr)?;
                self.read_sector_info_inner(new_sec_addr, false)?;
            }
        } else if self.cur_sec.status == SectorStoreStatus::Full {
            return Err(FdbErr::SavedFull);
        }

        if self.cur_sec.status == SectorStoreStatus::Empty {
            self.cur_sec.status = SectorStoreStatus::Using;
            self.cur_sec.start_time = cur_time;
            let mut st = vec![0u8; FDB_STORE_STATUS_TABLE_SIZE];
            status::write_status(self.be(), self.cur_sec.addr, &mut st, FDB_SECTOR_STORE_STATUS_NUM, SectorStoreStatus::Using as usize, true)?;

            let mut time_buf = vec![FDB_BYTE_ERASED; wg_align(4)];
            time_buf[..4].copy_from_slice(&cur_time.to_le_bytes());
            self.be().write(self.cur_sec.addr + sector_start_time_offset() as u32, &time_buf, true)?;
        }

        Ok(())
    }

    fn read_sector_info_inner(&mut self, addr: u32, traversal: bool) -> Result<(), FdbErr> {
        let sector = self.read_sector_info(addr, traversal)?;
        self.cur_sec = sector;
        Ok(())
    }

    /// Append a TSL.
    fn tsl_append(&mut self, blob: &[u8], timestamp: Option<FdbTime>) -> Result<(), FdbErr> {
        let cur_time = match timestamp {
            Some(t) => t,
            None => (self.get_time_fn.unwrap())(),
        };

        if blob.len() > self.max_len {
            return Err(FdbErr::WriteErr);
        }

        if cur_time <= self.last_time {
            return Err(FdbErr::WriteErr);
        }

        self.update_sec_status(blob.len(), cur_time)?;
        self.write_tsl(blob, cur_time)?;

        // Update current sector info
        self.cur_sec.end_idx = self.cur_sec.empty_idx;
        self.cur_sec.end_time = cur_time;
        self.cur_sec.empty_idx += log_idx_data_size() as u32;
        self.cur_sec.empty_data -= wg_align(blob.len()) as u32;
        self.cur_sec.remain -= log_idx_data_size() + wg_align(blob.len());
        self.last_time = cur_time;

        Ok(())
    }

    /// Format all sectors.
    fn tsl_format_all(&mut self) {
        let mut sector = TsdbSecInfo::default();
        sector.addr = 0;

        let mut sec_addr = 0u32;
        let mut traversed_len = 0u32;
        loop {
            traversed_len += self.sec_size;
            let _ = self.format_sector(sec_addr);
            let next = self.get_next_sector_addr(&{
                let mut s = TsdbSecInfo::default();
                s.addr = sec_addr;
                s
            }, traversed_len);
            if next == FDB_FAILED_ADDR { break; }
            sec_addr = next;
        }

        self.oldest_addr = 0;
        self.cur_sec = TsdbSecInfo::default();
        self.cur_sec.addr = 0;
        self.last_time = 0;

        let _ = self.read_sector_info_inner(0, false);
    }

    // ---- Public API ----

    pub fn init(&mut self, name: &str, path: &str, get_time: fn() -> FdbTime, max_len: usize, user_data: *mut core::ffi::c_void) -> Result<(), FdbErr> {
        self.name = name.to_string();
        self.dir = path.to_string();
        self.user_data = user_data;

        if self.init_ok {
            return Ok(());
        }

        if self.file_mode {
            let _ = std::fs::create_dir_all(path);
        }

        if self.sec_size == 0 || self.max_size == 0 {
            return Err(FdbErr::InitFailed);
        }

        if self.max_size % self.sec_size != 0 {
            return Err(FdbErr::InitFailed);
        }
        if self.max_size / self.sec_size < 2 {
            return Err(FdbErr::InitFailed);
        }

        self.backend = Some(Box::new(crate::FileBackend::new(name, path, self.sec_size, self.max_size)));

        self.db_lock();

        self.get_time_fn = Some(get_time);
        self.max_len = max_len;
        self.rollover = true;
        self.oldest_addr = FDB_DATA_UNUSED;
        self.cur_sec = TsdbSecInfo::default();
        self.cur_sec.addr = FDB_DATA_UNUSED;

        // Check all sector headers
        let mut check_failed = false;
        let mut empty_num = 0usize;
        let mut empty_addr = 0u32;
        let mut cur_sec_found = false;

        let mut sec_addr = 0u32;
        let mut traversed_len = 0u32;
        loop {
            traversed_len += self.sec_size;
            match self.read_sector_info(sec_addr, true) {
                Ok(sector) => {
                    if !sector.check_ok {
                        check_failed = true;
                    } else if sector.status == SectorStoreStatus::Using {
                        if self.cur_sec.addr == FDB_DATA_UNUSED {
                            self.cur_sec = sector;
                            cur_sec_found = true;
                        } else {
                            check_failed = true;
                        }
                    } else if sector.status == SectorStoreStatus::Empty {
                        empty_num += 1;
                        empty_addr = sector.addr;
                        if empty_num == 1 && self.cur_sec.addr == FDB_DATA_UNUSED {
                            self.cur_sec = sector;
                        }
                    }
                }
                Err(_) => {
                    check_failed = true;
                }
            }
            let next = {
                let mut s = TsdbSecInfo::default();
                s.addr = sec_addr;
                s
            };
            let n = self.get_next_sector_addr(&next, traversed_len);
            if n == FDB_FAILED_ADDR { break; }
            sec_addr = n;
        }

        if check_failed {
            if self.not_formatable {
                self.db_unlock();
                return Err(FdbErr::ReadErr);
            }
            self.tsl_format_all();
        } else {
            let latest_addr = if empty_num > 0 {
                empty_addr
            } else if self.rollover {
                self.cur_sec.addr
            } else {
                self.cur_sec.addr = self.max_size - self.sec_size;
                self.cur_sec.addr
            };

            if latest_addr + self.sec_size >= self.max_size {
                self.oldest_addr = 0;
            } else {
                self.oldest_addr = latest_addr + self.sec_size;
            }
        }

        // Read current using sector info
        let _ = self.read_sector_info_inner(self.cur_sec.addr, true);

        // Get last save time
        if self.cur_sec.status == SectorStoreStatus::Using {
            self.last_time = self.cur_sec.end_time;
        } else if self.cur_sec.status == SectorStoreStatus::Empty && self.oldest_addr != self.cur_sec.addr {
            let addr = if self.cur_sec.addr == 0 {
                self.max_size - self.sec_size
            } else {
                self.cur_sec.addr - self.sec_size
            };
            if let Ok(sec) = self.read_sector_info(addr, false) {
                self.last_time = sec.end_time;
            }
        }

        self.db_unlock();
        self.init_ok = true;

        Ok(())
    }

    pub fn deinit(&mut self) -> Result<(), FdbErr> {
        self.init_ok = false;
        self.backend = None;
        Ok(())
    }

    /// Append a new TSL.
    pub fn tsl_append(&mut self, blob: &[u8]) -> Result<(), FdbErr> {
        if !self.init_ok {
            return Err(FdbErr::InitFailed);
        }
        self.db_lock();
        let result = self.tsl_append_inner(blob, None);
        self.db_unlock();
        result
    }

    /// Append with specific timestamp.
    pub fn tsl_append_with_ts(&mut self, blob: &[u8], timestamp: FdbTime) -> Result<(), FdbErr> {
        if !self.init_ok {
            return Err(FdbErr::InitFailed);
        }
        self.db_lock();
        let result = self.tsl_append_inner(blob, Some(timestamp));
        self.db_unlock();
        result
    }

    fn tsl_append_inner(&mut self, blob: &[u8], timestamp: Option<FdbTime>) -> Result<(), FdbErr> {
        self.tsl_append(blob, timestamp)
    }

    /// Iterate over all TSLs.
    pub fn tsl_iter<F>(&mut self, mut cb: F)
    where
        F: FnMut(&TslInfo) -> bool,
    {
        if !self.init_ok {
            return;
        }

        self.db_lock();
        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;

        loop {
            traversed_len += self.sec_size;
            let sector = match self.read_sector_info(sec_addr, false) {
                Ok(s) => s,
                Err(_) => {
                    let next = {
                        let mut s = TsdbSecInfo::default();
                        s.addr = sec_addr;
                        s
                    };
                    let n = self.get_next_sector_addr(&next, traversed_len);
                    if n == FDB_FAILED_ADDR { break; }
                    sec_addr = n;
                    continue;
                }
            };

            if sector.status == SectorStoreStatus::Using || sector.status == SectorStoreStatus::Full {
                let sector = if sector.status == SectorStoreStatus::Using {
                    self.cur_sec.clone()
                } else {
                    sector
                };

                let mut tsl = TslInfo::default();
                tsl.addr.index = sector.addr + sector_hdr_data_size() as u32;
                loop {
                    if self.read_tsl(&mut tsl).is_err() { break; }
                    if cb(&tsl) {
                        self.db_unlock();
                        return;
                    }
                    let next = self.get_next_tsl_addr(&sector, &tsl);
                    if next == FDB_FAILED_ADDR { break; }
                    tsl.addr.index = next;
                }
            }

            let next = {
                let mut s = TsdbSecInfo::default();
                s.addr = sec_addr;
                s
            };
            let n = self.get_next_sector_addr(&next, traversed_len);
            if n == FDB_FAILED_ADDR { break; }
            sec_addr = n;
        }

        self.db_unlock();
    }

    /// Iterate over TSLs in reverse.
    pub fn tsl_iter_reverse<F>(&mut self, mut cb: F)
    where
        F: FnMut(&TslInfo) -> bool,
    {
        if !self.init_ok {
            return;
        }

        self.db_lock();
        let mut sec_addr = self.cur_sec.addr;
        let mut traversed_len = 0u32;

        loop {
            traversed_len += self.sec_size;
            let sector = match self.read_sector_info(sec_addr, false) {
                Ok(s) => s,
                Err(_) => {
                    let next = {
                        let mut s = TsdbSecInfo::default();
                        s.addr = sec_addr;
                        s
                    };
                    let n = self.get_last_sector_addr(&next, traversed_len);
                    if n == FDB_FAILED_ADDR { break; }
                    sec_addr = n;
                    continue;
                }
            };

            if sector.status == SectorStoreStatus::Using || sector.status == SectorStoreStatus::Full {
                let sector = if sector.status == SectorStoreStatus::Using {
                    self.cur_sec.clone()
                } else {
                    sector
                };

                let mut tsl = TslInfo::default();
                tsl.addr.index = sector.end_idx;
                loop {
                    if self.read_tsl(&mut tsl).is_err() { break; }
                    if cb(&tsl) {
                        self.db_unlock();
                        return;
                    }
                    let prev = self.get_last_tsl_addr(&sector, &tsl);
                    if prev == FDB_FAILED_ADDR { break; }
                    tsl.addr.index = prev;
                }
            } else if sector.status == SectorStoreStatus::Empty || sector.status == SectorStoreStatus::Unused {
                break;
            }

            let next = {
                let mut s = TsdbSecInfo::default();
                s.addr = sec_addr;
                s
            };
            let n = self.get_last_sector_addr(&next, traversed_len);
            if n == FDB_FAILED_ADDR { break; }
            sec_addr = n;
        }

        self.db_unlock();
    }

    /// Binary search for start TSL address.
    fn search_start_tsl_addr(&mut self, start: u32, end: u32, from: FdbTime, to: FdbTime) -> u32 {
        let mut start = start;
        let mut end = end;
        let idx_data_sz = log_idx_data_size() as u32;

        loop {
            let mid = start + fdb_align_down(((end - start) / 2) as usize, log_idx_data_size()) as u32;
            let mut tsl = TslInfo::default();
            tsl.addr.index = mid;
            let _ = self.read_tsl(&mut tsl);

            if tsl.time < from {
                start = tsl.addr.index + idx_data_sz;
            } else if tsl.time > from {
                end = tsl.addr.index - idx_data_sz;
            } else {
                return tsl.addr.index;
            }

            if start > end {
                if from > to {
                    let mut tsl = TslInfo::default();
                    tsl.addr.index = start;
                    let _ = self.read_tsl(&mut tsl);
                    if tsl.time > from {
                        start -= idx_data_sz;
                    }
                }
                break;
            }
        }

        start
    }

    /// Iterate TSLs by time range.
    pub fn tsl_iter_by_time<F>(&mut self, from: FdbTime, to: FdbTime, mut cb: F)
    where
        F: FnMut(&TslInfo) -> bool,
    {
        if !self.init_ok {
            return;
        }

        self.db_lock();

        let forward = from <= to;
        let start_addr = if forward { self.oldest_addr } else { self.cur_sec.addr };

        let mut sec_addr = start_addr;
        let mut traversed_len = 0u32;
        let mut found_start_tsl = false;

        loop {
            traversed_len += self.sec_size;
            let sector = match self.read_sector_info(sec_addr, false) {
                Ok(s) => s,
                Err(_) => {
                    let next = if forward {
                        let s = TsdbSecInfo { addr: sec_addr, ..TsdbSecInfo::default() };
                        self.get_next_sector_addr(&s, traversed_len)
                    } else {
                        let s = TsdbSecInfo { addr: sec_addr, ..TsdbSecInfo::default() };
                        self.get_last_sector_addr(&s, traversed_len)
                    };
                    if next == FDB_FAILED_ADDR { break; }
                    sec_addr = next;
                    continue;
                }
            };

            if sector.status == SectorStoreStatus::Using || sector.status == SectorStoreStatus::Full {
                let sector = if sector.status == SectorStoreStatus::Using {
                    self.cur_sec.clone()
                } else {
                    sector
                };

                let time_match = if !found_start_tsl {
                    if forward {
                        (sec_addr == start_addr && from <= sector.start_time) || from <= sector.end_time
                    } else {
                        (sec_addr == start_addr && from >= sector.end_time) || from >= sector.start_time
                    }
                } else {
                    true
                };

                if found_start_tsl || time_match {
                    found_start_tsl = true;

                    let start_idx = sector.addr + sector_hdr_data_size() as u32;
                    let end_idx = sector.end_idx;

                    let tsl_start = self.search_start_tsl_addr(start_idx, end_idx, from, to);
                    let mut tsl = TslInfo::default();
                    tsl.addr.index = tsl_start;

                    loop {
                        if self.read_tsl(&mut tsl).is_err() { break; }
                        if tsl.status != TslStatus::Unused {
                            if (forward && tsl.time >= from && tsl.time <= to)
                                || (!forward && tsl.time <= from && tsl.time >= to)
                            {
                                if cb(&tsl) {
                                    self.db_unlock();
                                    return;
                                }
                            } else {
                                break;
                            }
                        }
                        let next = if forward {
                            self.get_next_tsl_addr(&sector, &tsl)
                        } else {
                            self.get_last_tsl_addr(&sector, &tsl)
                        };
                        if next == FDB_FAILED_ADDR { break; }
                        tsl.addr.index = next;
                    }
                }
            } else if sector.status == SectorStoreStatus::Empty {
                break;
            }

            let next = if forward {
                let s = TsdbSecInfo { addr: sec_addr, ..TsdbSecInfo::default() };
                self.get_next_sector_addr(&s, traversed_len)
            } else {
                let s = TsdbSecInfo { addr: sec_addr, ..TsdbSecInfo::default() };
                self.get_last_sector_addr(&s, traversed_len)
            };
            if next == FDB_FAILED_ADDR { break; }
            sec_addr = next;
        }

        self.db_unlock();
    }

    /// Query count of TSLs by time range and status.
    pub fn tsl_query_count(&mut self, from: FdbTime, to: FdbTime, status: TslStatus) -> usize {
        if !self.init_ok {
            return 0;
        }
        let mut count = 0usize;
        let status_clone = status;
        self.tsl_iter_by_time(from, to, |tsl| {
            if tsl.status == status_clone {
                count += 1;
            }
            false
        });
        count
    }

    /// Set TSL status.
    pub fn tsl_set_status(&mut self, tsl: &TslInfo, status: TslStatus) -> Result<(), FdbErr> {
        let mut st = vec![0u8; TSL_STATUS_TABLE_SIZE];
        status::write_status(self.be(), tsl.addr.index, &mut st, FDB_TSL_STATUS_NUM, status as usize, true)
    }

    /// Clean all TSLs.
    pub fn tsl_clean(&mut self) {
        self.db_lock();
        self.tsl_format_all();
        self.db_unlock();
    }

    /// Get max blob count.
    pub fn tsl_max_blob_count(&self) -> usize {
        let max_blob_len = self.max_len;
        let sec_size = self.sec_size as usize - sector_hdr_data_size();
        let blob_size = log_idx_data_size() + wg_align(max_blob_len);
        let n_sec = self.max_size as usize / self.sec_size as usize;
        n_sec * (sec_size / blob_size)
    }

    /// Convert TSL to blob for reading.
    pub fn tsl_to_blob(&self, tsl: &TslInfo) -> (u32, u32, usize) {
        (tsl.addr.log, tsl.addr.index, tsl.log_len as usize)
    }

    /// Control interface.
    pub fn control(&mut self, cmd: i32, arg: *mut core::ffi::c_void) {
        match cmd {
            FDB_TSDB_CTRL_SET_SEC_SIZE => {
                assert!(!self.init_ok);
                unsafe { self.sec_size = *(arg as *const u32); }
            }
            FDB_TSDB_CTRL_GET_SEC_SIZE => {
                unsafe { *(arg as *mut u32) = self.sec_size; }
            }
            FDB_TSDB_CTRL_SET_LOCK => {
                unsafe { self.lock_fn = Some(std::mem::transmute(arg)); }
            }
            FDB_TSDB_CTRL_SET_UNLOCK => {
                unsafe { self.unlock_fn = Some(std::mem::transmute(arg)); }
            }
            FDB_TSDB_CTRL_SET_ROLLOVER => {
                assert!(self.init_ok);
                unsafe { self.rollover = *(arg as *const bool); }
            }
            FDB_TSDB_CTRL_GET_ROLLOVER => {
                unsafe { *(arg as *mut bool) = self.rollover; }
            }
            FDB_TSDB_CTRL_GET_LAST_TIME => {
                unsafe { *(arg as *mut FdbTime) = self.last_time; }
            }
            FDB_TSDB_CTRL_SET_FILE_MODE => {
                assert!(!self.init_ok);
                unsafe { self.file_mode = *(arg as *const bool); }
            }
            FDB_TSDB_CTRL_SET_MAX_SIZE => {
                assert!(!self.init_ok);
                unsafe { self.max_size = *(arg as *const u32); }
            }
            FDB_TSDB_CTRL_SET_NOT_FORMAT => {
                assert!(!self.init_ok);
                unsafe { self.not_formatable = *(arg as *const bool); }
            }
            _ => {}
        }
    }
}

//! FFI — C-compatible exports for the flashdb_rust static library.
//! All public symbols from inc/flashdb.h are exported here.

use std::ffi::{CStr, CString};
use std::os::raw::c_char;
use std::ptr;

use crate::{
    Kvdb, Tsdb, FdbErr, FdbTime, Blob, KvInfo, TslInfo, KvdbSecInfo,
    FDB_KV_NAME_MAX, FDB_STR_KV_VALUE_MAX_SIZE, FDB_DATA_UNUSED,
    FDB_KVDB_CTRL_SET_SEC_SIZE, FDB_KVDB_CTRL_GET_SEC_SIZE,
    FDB_KVDB_CTRL_SET_LOCK, FDB_KVDB_CTRL_SET_UNLOCK,
    FDB_KVDB_CTRL_SET_FILE_MODE, FDB_KVDB_CTRL_SET_MAX_SIZE,
    FDB_KVDB_CTRL_SET_NOT_FORMAT,
    FDB_TSDB_CTRL_SET_SEC_SIZE, FDB_TSDB_CTRL_GET_SEC_SIZE,
    FDB_TSDB_CTRL_SET_LOCK, FDB_TSDB_CTRL_SET_UNLOCK,
    FDB_TSDB_CTRL_SET_ROLLOVER, FDB_TSDB_CTRL_GET_ROLLOVER,
    FDB_TSDB_CTRL_GET_LAST_TIME, FDB_TSDB_CTRL_SET_FILE_MODE,
    FDB_TSDB_CTRL_SET_MAX_SIZE, FDB_TSDB_CTRL_SET_NOT_FORMAT,
};

// ---- Opaque handles ----

pub type FdbKvdbT = *mut Kvdb;
pub type FdbTsdbT = *mut Tsdb;
pub type FdbDbT = *mut u8; // generic, not directly used
pub type FdbKvT = *mut KvInfo;
pub type FdbTslT = *mut TslInfo;
pub type FdbBlobT = *mut Blob;

// ---- Helper: C error code ----

fn err_to_c(e: FdbErr) -> i32 {
    e as i32
}

// ---- FDB struct wrappers for C compatibility ----

/// C-compatible blob structure
#[repr(C)]
pub struct CfdbBlob {
    pub buf: *mut u8,
    pub size: usize,
    pub saved_meta_addr: u32,
    pub saved_addr: u32,
    pub saved_len: usize,
}

/// C-compatible default KV node
#[repr(C)]
pub struct CfdbDefaultKvNode {
    pub key: *const c_char,
    pub value: *mut u8,
    pub value_len: usize,
}

/// C-compatible default KV
#[repr(C)]
pub struct CfdbDefaultKv {
    pub kvs: *mut CfdbDefaultKvNode,
    pub num: usize,
}

/// C-compatible KV iterator
#[repr(C)]
pub struct CfdbKvIterator {
    pub db: FdbKvdbT,
    // Internal state
    internal: crate::kvdb::KvIterState,
}

/// C-compatible TSL callback
pub type FdbTslCb = extern "C" fn(tsl: FdbTslT, arg: *mut core::ffi::c_void) -> bool;

/// C-compatible get_time callback
pub type FdbGetTime = extern "C" fn() -> FdbTime;

/// Global KVDB and TSDB storage (simple approach for FFI)
use std::sync::Mutex;
use std::collections::HashMap;

lazy_static::lazy_static! {
    static ref KVDB_INSTANCES: Mutex<HashMap<usize, Kvdb>> = Mutex::new(HashMap::new());
    static ref TSDB_INSTANCES: Mutex<HashMap<usize, Tsdb>> = Mutex::new(HashMap::new());
    static ref NEXT_HANDLE: Mutex<usize> = Mutex::new(1);
    static ref BLOB_INSTANCES: Mutex<HashMap<usize, Blob>> = Mutex::new(HashMap::new());
    static ref KV_INSTANCES: Mutex<HashMap<usize, KvInfo>> = Mutex::new(HashMap::new());
    static ref TSL_INSTANCES: Mutex<HashMap<usize, TslInfo>> = Mutex::new(HashMap::new());
}

fn alloc_handle() -> usize {
    let mut next = NEXT_HANDLE.lock().unwrap();
    let h = *next;
    *next += 1;
    h
}

// ---- KVDB API ----

#[no_mangle]
pub extern "C" fn fdb_kvdb_init(
    db: FdbKvdbT,
    name: *const c_char,
    path: *const c_char,
    default_kv: *const CfdbDefaultKv,
    user_data: *mut core::ffi::c_void,
) -> i32 {
    if db.is_null() || name.is_null() || path.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }

    let name_str = unsafe { CStr::from_ptr(name) }.to_str().unwrap_or("");
    let path_str = unsafe { CStr::from_ptr(path) }.to_str().unwrap_or("");

    let dkv = if default_kv.is_null() {
        None
    } else {
        let cd = unsafe { &*default_kv };
        let mut kvs = Vec::new();
        for i in 0..cd.num {
            let node = unsafe { &*cd.kvs.add(i) };
            let key = unsafe { CStr::from_ptr(node.key) }.to_str().unwrap_or("").to_string();
            let mut value = Vec::new();
            if !node.value.is_null() && node.value_len > 0 {
                unsafe {
                    let slice = std::slice::from_raw_parts(node.value, node.value_len);
                    value.extend_from_slice(slice);
                }
            }
            kvs.push(crate::DefaultKvNode { key, value, value_len: node.value_len });
        }
        Some(crate::DefaultKv { kvs })
    };

    let db_ref = unsafe { &mut *db };
    let result = db_ref.init(name_str, path_str, dkv.as_ref(), user_data);
    match result {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kvdb_deinit(db: FdbKvdbT) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let db_ref = unsafe { &mut *db };
    match db_ref.deinit() {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kvdb_control(db: FdbKvdbT, cmd: i32, arg: *mut core::ffi::c_void) {
    if db.is_null() {
        return;
    }
    let db_ref = unsafe { &mut *db };
    db_ref.control(cmd, arg);
}

#[no_mangle]
pub extern "C" fn fdb_kvdb_check(db: FdbKvdbT) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let db_ref = unsafe { &mut *db };
    match db_ref.check() {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_set(db: FdbKvdbT, key: *const c_char, value: *const c_char) -> i32 {
    if db.is_null() || key.is_null() {
        return err_to_c(FdbErr::KvNameErr);
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let db_ref = unsafe { &mut *db };

    if value.is_null() {
        match db_ref.kv_del(key_str) {
            Ok(()) => err_to_c(FdbErr::NoErr),
            Err(e) => err_to_c(e),
        }
    } else {
        let val_str = unsafe { CStr::from_ptr(value) }.to_str().unwrap_or("");
        match db_ref.kv_set(key_str, val_str) {
            Ok(()) => err_to_c(FdbErr::NoErr),
            Err(e) => err_to_c(e),
        }
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_get(db: FdbKvdbT, key: *const c_char) -> *mut c_char {
    if db.is_null() || key.is_null() {
        return ptr::null_mut();
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let db_ref = unsafe { &mut *db };

    match db_ref.kv_get(key_str) {
        Some(val) => {
            let c_str = CString::new(val).unwrap_or_default();
            c_str.into_raw()
        }
        None => ptr::null_mut(),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_set_blob(db: FdbKvdbT, key: *const c_char, blob: FdbBlobT) -> i32 {
    if db.is_null() || key.is_null() || blob.is_null() {
        return err_to_c(FdbErr::KvNameErr);
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let blob_ref = unsafe { &*blob };
    let db_ref = unsafe { &mut *db };

    match db_ref.kv_set_blob(key_str, &blob_ref.buf) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_get_blob(db: FdbKvdbT, key: *const c_char, blob: FdbBlobT) -> usize {
    if db.is_null() || key.is_null() || blob.is_null() {
        return 0;
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let blob_ref = unsafe { &mut *blob };
    let db_ref = unsafe { &mut *db };

    let mut buf = vec![0u8; blob_ref.size];
    let read_len = db_ref.kv_get_blob(key_str, &mut buf);
    if read_len > 0 && !blob_ref.buf.is_null() {
        unsafe {
            std::ptr::copy_nonoverlapping(buf.as_ptr(), blob_ref.buf, read_len);
        }
    }
    read_len
}

#[no_mangle]
pub extern "C" fn fdb_kv_del(db: FdbKvdbT, key: *const c_char) -> i32 {
    if db.is_null() || key.is_null() {
        return err_to_c(FdbErr::KvNameErr);
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let db_ref = unsafe { &mut *db };

    match db_ref.kv_del(key_str) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_set_default(db: FdbKvdbT) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let db_ref = unsafe { &mut *db };
    match db_ref.set_default() {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_print(_db: FdbKvdbT) {
    // Stub — printing is for debug only
}

#[no_mangle]
pub extern "C" fn fdb_blob_make(blob: FdbBlobT, value_buf: *const core::ffi::c_void, buf_len: usize) -> FdbBlobT {
    if blob.is_null() {
        return ptr::null_mut();
    }
    let blob_ref = unsafe { &mut *blob };
    if !value_buf.is_null() && buf_len > 0 {
        blob_ref.buf = unsafe { std::slice::from_raw_parts(value_buf as *const u8, buf_len) }.to_vec();
    }
    blob_ref.size = buf_len;
    blob
}

#[no_mangle]
pub extern "C" fn fdb_blob_read(db: FdbDbT, blob: FdbBlobT) -> usize {
    if blob.is_null() {
        return 0;
    }
    let blob_ref = unsafe { &mut *blob };
    let read_len = blob_ref.size.min(blob_ref.saved_len);
    if read_len > 0 && !blob_ref.buf.is_empty() {
        read_len
    } else {
        0
    }
}

#[no_mangle]
pub extern "C" fn fdb_calc_crc32(crc: u32, buf: *const core::ffi::c_void, size: usize) -> u32 {
    if buf.is_null() || size == 0 {
        return crc;
    }
    let data = unsafe { std::slice::from_raw_parts(buf as *const u8, size) };
    crate::calc_crc32(crc, data)
}

// ---- TSDB API ----

#[no_mangle]
pub extern "C" fn fdb_tsdb_init(
    db: FdbTsdbT,
    name: *const c_char,
    path: *const c_char,
    get_time: Option<extern "C" fn() -> FdbTime>,
    max_len: usize,
    user_data: *mut core::ffi::c_void,
) -> i32 {
    if db.is_null() || name.is_null() || path.is_null() || get_time.is_none() {
        return err_to_c(FdbErr::InitFailed);
    }

    let name_str = unsafe { CStr::from_ptr(name) }.to_str().unwrap_or("");
    let path_str = unsafe { CStr::from_ptr(path) }.to_str().unwrap_or("");
    let get_time_fn = get_time.unwrap();

    let db_ref = unsafe { &mut *db };
    let result = db_ref.init(name_str, path_str, get_time_fn, max_len, user_data);
    match result {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_tsdb_deinit(db: FdbTsdbT) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let db_ref = unsafe { &mut *db };
    match db_ref.deinit() {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_tsdb_control(db: FdbTsdbT, cmd: i32, arg: *mut core::ffi::c_void) {
    if db.is_null() {
        return;
    }
    let db_ref = unsafe { &mut *db };
    db_ref.control(cmd, arg);
}

#[no_mangle]
pub extern "C" fn fdb_tsl_append(db: FdbTsdbT, blob: FdbBlobT) -> i32 {
    if db.is_null() || blob.is_null() {
        return err_to_c(FdbErr::WriteErr);
    }
    let blob_ref = unsafe { &*blob };
    let db_ref = unsafe { &mut *db };
    match db_ref.tsl_append(&blob_ref.buf) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_tsl_append_with_ts(db: FdbTsdbT, blob: FdbBlobT, timestamp: FdbTime) -> i32 {
    if db.is_null() || blob.is_null() {
        return err_to_c(FdbErr::WriteErr);
    }
    let blob_ref = unsafe { &*blob };
    let db_ref = unsafe { &mut *db };
    match db_ref.tsl_append_with_ts(&blob_ref.buf, timestamp) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_tsl_iter(db: FdbTsdbT, cb: Option<extern "C" fn(FdbTslT, *mut core::ffi::c_void) -> bool>, cb_arg: *mut core::ffi::c_void) {
    if db.is_null() || cb.is_none() {
        return;
    }
    let cb_fn = cb.unwrap();
    let db_ref = unsafe { &mut *db };
    db_ref.tsl_iter(|tsl| {
        let mut tsl_copy = tsl.clone();
        cb_fn(&mut tsl_copy as *mut TslInfo, cb_arg)
    });
}

#[no_mangle]
pub extern "C" fn fdb_tsl_iter_reverse(db: FdbTsdbT, cb: Option<extern "C" fn(FdbTslT, *mut core::ffi::c_void) -> bool>, cb_arg: *mut core::ffi::c_void) {
    if db.is_null() || cb.is_none() {
        return;
    }
    let cb_fn = cb.unwrap();
    let db_ref = unsafe { &mut *db };
    db_ref.tsl_iter_reverse(|tsl| {
        let mut tsl_copy = tsl.clone();
        cb_fn(&mut tsl_copy as *mut TslInfo, cb_arg)
    });
}

#[no_mangle]
pub extern "C" fn fdb_tsl_iter_by_time(db: FdbTsdbT, from: FdbTime, to: FdbTime, cb: Option<extern "C" fn(FdbTslT, *mut core::ffi::c_void) -> bool>, cb_arg: *mut core::ffi::c_void) {
    if db.is_null() || cb.is_none() {
        return;
    }
    let cb_fn = cb.unwrap();
    let db_ref = unsafe { &mut *db };
    db_ref.tsl_iter_by_time(from, to, |tsl| {
        let mut tsl_copy = tsl.clone();
        cb_fn(&mut tsl_copy as *mut TslInfo, cb_arg)
    });
}

#[no_mangle]
pub extern "C" fn fdb_tsl_query_count(db: FdbTsdbT, from: FdbTime, to: FdbTime, status: u32) -> usize {
    if db.is_null() {
        return 0;
    }
    let tsl_status = match status {
        0 => crate::TslStatus::Unused,
        1 => crate::TslStatus::PreWrite,
        2 => crate::TslStatus::Write,
        3 => crate::TslStatus::UserStatus1,
        4 => crate::TslStatus::Deleted,
        5 => crate::TslStatus::UserStatus2,
        _ => crate::TslStatus::Unused,
    };
    let db_ref = unsafe { &mut *db };
    db_ref.tsl_query_count(from, to, tsl_status)
}

#[no_mangle]
pub extern "C" fn fdb_tsl_set_status(db: FdbTsdbT, tsl: FdbTslT, status: u32) -> i32 {
    if db.is_null() || tsl.is_null() {
        return err_to_c(FdbErr::WriteErr);
    }
    let tsl_status = match status {
        0 => crate::TslStatus::Unused,
        1 => crate::TslStatus::PreWrite,
        2 => crate::TslStatus::Write,
        3 => crate::TslStatus::UserStatus1,
        4 => crate::TslStatus::Deleted,
        5 => crate::TslStatus::UserStatus2,
        _ => crate::TslStatus::Unused,
    };
    let tsl_ref = unsafe { &*tsl };
    let db_ref = unsafe { &mut *db };
    match db_ref.tsl_set_status(tsl_ref, tsl_status) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_tsl_clean(db: FdbTsdbT) {
    if db.is_null() {
        return;
    }
    let db_ref = unsafe { &mut *db };
    db_ref.tsl_clean();
}

#[no_mangle]
pub extern "C" fn fdb_tsl_max_blob_count(db: FdbTsdbT) -> usize {
    if db.is_null() {
        return 0;
    }
    let db_ref = unsafe { &*db };
    db_ref.tsl_max_blob_count()
}

#[no_mangle]
pub extern "C" fn fdb_tsl_to_blob(tsl: FdbTslT, blob: FdbBlobT) -> FdbBlobT {
    if tsl.is_null() || blob.is_null() {
        return ptr::null_mut();
    }
    let tsl_ref = unsafe { &*tsl };
    let blob_ref = unsafe { &mut *blob };
    blob_ref.saved_addr = tsl_ref.addr_log;
    blob_ref.saved_meta_addr = tsl_ref.addr_index;
    blob_ref.saved_len = tsl_ref.log_len as usize;
    blob
}

#[no_mangle]
pub extern "C" fn fdb_kv_get_obj(db: FdbKvdbT, key: *const c_char, kv: FdbKvT) -> FdbKvT {
    if db.is_null() || key.is_null() || kv.is_null() {
        return ptr::null_mut();
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let db_ref = unsafe { &mut *db };
    match db_ref.find_kv(key_str) {
        Some(found_kv) => {
            let kv_ref = unsafe { &mut *kv };
            *kv_ref = found_kv;
            kv
        }
        None => ptr::null_mut(),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_to_blob(kv: FdbKvT, blob: FdbBlobT) -> FdbBlobT {
    if kv.is_null() || blob.is_null() {
        return ptr::null_mut();
    }
    let kv_ref = unsafe { &*kv };
    let blob_ref = unsafe { &mut *blob };
    blob_ref.saved_meta_addr = kv_ref.addr_start;
    blob_ref.saved_addr = kv_ref.addr_value;
    blob_ref.saved_len = kv_ref.value_len as usize;
    blob
}

// Iterator stubs — these require more complex state management
// For now, provide basic functionality that the C tests need

#[repr(C)]
pub struct FdbKvIterator {
    _private: [u8; 0],
}

#[no_mangle]
pub extern "C" fn fdb_kv_iterator_init(db: FdbKvdbT, itr: *mut FdbKvIterator) -> *mut FdbKvIterator {
    // Stub
    itr
}

#[no_mangle]
pub extern "C" fn fdb_kv_iterate(db: FdbKvdbT, itr: *mut FdbKvIterator) -> bool {
    // Stub
    false
}

