display.text:
//! KVDB — Key-Value Database implementation.
//! Faithful translation of fdb_kvdb.c.

use std::cell::RefCell;

use crate::{
    StorageBackend, FdbErr, FdbTime, FDB_BYTE_ERASED, FDB_DATA_UNUSED, FDB_FAILED_ADDR,
    FDB_KV_NAME_MAX, FDB_GC_EMPTY_SEC_THRESHOLD, FDB_STR_KV_VALUE_MAX_SIZE,
    KVDB_SECTOR_MAGIC_WORD, KV_MAGIC_WORD, SECTOR_NOT_COMBINED, SECTOR_COMBINED,
    KvStatus, SectorStoreStatus, SectorDirtyStatus, DefaultKv, DefaultKvNode,
    Blob, KvInfo, KvdbSecInfo,
    calc_crc32, status, wg_align, wg_align_down, fdb_align_down, status_table_size,
    FDB_STORE_STATUS_TABLE_SIZE, FDB_DIRTY_STATUS_TABLE_SIZE, FDB_KV_STATUS_NUM,
    KV_STATUS_TABLE_SIZE, FDB_SECTOR_STORE_STATUS_NUM, FDB_SECTOR_DIRTY_STATUS_NUM,
    DbType, FDB_SEC_REMAIN_THRESHOLD,
};

/// Compute sector header data size at runtime.
fn sector_hdr_data_size(sec_size: u32) -> usize {
    // sector_hdr_data: store_status + dirty_status + magic + combined + reserved
    // For FDB_WRITE_GRAN=1:
    //   store: FDB_STORE_STATUS_TABLE_SIZE bytes
    //   dirty: FDB_DIRTY_STATUS_TABLE_SIZE bytes
    //   magic: 4 bytes
    //   combined: 4 bytes
    //   reserved: 4 bytes
    let raw = FDB_STORE_STATUS_TABLE_SIZE + FDB_DIRTY_STATUS_TABLE_SIZE + 4 + 4 + 4;
    wg_align(raw)
}

/// Compute KV header data size at runtime.
fn kv_hdr_data_size() -> usize {
    // kv_hdr_data: status_table + magic + len + crc32 + name_len + value_len
    let raw = KV_STATUS_TABLE_SIZE + 4 + 4 + 4 + 1 + 4;
    wg_align(raw)
}

/// Compute FDB_SEC_REMAIN_THRESHOLD = KV_HDR_DATA_SIZE + FDB_KV_NAME_MAX
fn sec_remain_threshold() -> usize {
    kv_hdr_data_size() + FDB_KV_NAME_MAX
}

// Offsets into sector header
fn sector_store_offset() -> usize { 0 }
fn sector_dirty_offset() -> usize { FDB_STORE_STATUS_TABLE_SIZE }
fn sector_magic_offset() -> usize { FDB_STORE_STATUS_TABLE_SIZE + FDB_DIRTY_STATUS_TABLE_SIZE }
fn kv_magic_offset() -> usize { KV_STATUS_TABLE_SIZE }
fn kv_len_offset() -> usize { KV_STATUS_TABLE_SIZE + 4 }
fn kv_name_len_offset() -> usize { KV_STATUS_TABLE_SIZE + 4 + 4 + 4 }

fn sector_num(max_size: u32, sec_size: u32) -> u32 {
    max_size / sec_size
}

pub struct Kvdb {
    pub name: String,
    pub sec_size: u32,
    pub max_size: u32,
    pub oldest_addr: u32,
    pub init_ok: bool,
    pub file_mode: bool,
    pub not_formatable: bool,
    pub dir: String,
    pub gc_request: bool,
    pub in_recovery_check: bool,
    pub cur_kv: KvInfo,
    pub cur_sector: KvdbSecInfo,
    pub last_is_complete_del: bool,
    pub default_kvs: DefaultKv,
    pub lock_fn: Option<fn(*mut core::ffi::c_void)>,
    pub unlock_fn: Option<fn(*mut core::ffi::c_void)>,
    pub user_data: *mut core::ffi::c_void,
    pub backend: Option<Box<dyn StorageBackend>>,
    // Cache tables
    kv_cache: Vec<KvCacheNode>,
    sector_cache: Vec<KvdbSecInfo>,
}

#[derive(Clone)]
struct KvCacheNode {
    name_crc: u16,
    active: u16,
    addr: u32,
}

impl Default for KvCacheNode {
    fn default() -> Self {
        KvCacheNode {
            name_crc: 0,
            active: 0,
            addr: FDB_DATA_UNUSED,
        }
    }
}

impl Kvdb {
    pub fn new() -> Self {
        let kv_cache = vec![KvCacheNode::default(); crate::FDB_KV_CACHE_TABLE_SIZE];
        let mut sector_cache = Vec::with_capacity(crate::FDB_SECTOR_CACHE_TABLE_SIZE);
        for _ in 0..crate::FDB_SECTOR_CACHE_TABLE_SIZE {
            sector_cache.push(KvdbSecInfo::default());
        }
        Kvdb {
            name: String::new(),
            sec_size: 0,
            max_size: 0,
            oldest_addr: 0,
            init_ok: false,
            file_mode: true,
            not_formatable: false,
            dir: String::new(),
            gc_request: false,
            in_recovery_check: false,
            cur_kv: KvInfo::default(),
            cur_sector: KvdbSecInfo::default(),
            last_is_complete_del: false,
            default_kvs: DefaultKv::default(),
            lock_fn: None,
            unlock_fn: None,
            user_data: std::ptr::null_mut(),
            backend: None,
            kv_cache,
            sector_cache,
        }
    }

    fn be(&mut self) -> &mut dyn StorageBackend {
        self.backend.as_deref_mut().unwrap()
    }

    fn db_lock(&self) {
        if let Some(lock) = self.lock_fn {
            lock(self.user_data);
        }
    }

    fn db_unlock(&self) {
        if let Some(unlock) = self.unlock_fn {
            unlock(self.user_data);
        }
    }

    fn update_sector_cache(&mut self, sector: &KvdbSecInfo) {
        for i in 0..self.sector_cache.len() {
            if self.sector_cache[i].addr == sector.addr {
                if sector.check_ok {
                    self.sector_cache[i] = sector.clone();
                } else {
                    self.sector_cache[i].addr = FDB_DATA_UNUSED;
                }
                return;
            } else if self.sector_cache[i].addr == FDB_DATA_UNUSED {
                // empty slot found
            }
        }
        if sector.check_ok {
            for i in 0..self.sector_cache.len() {
                if self.sector_cache[i].addr == FDB_DATA_UNUSED {
                    self.sector_cache[i] = sector.clone();
                    return;
                }
            }
        }
    }

    fn get_sector_from_cache(&self, sec_addr: u32) -> Option<usize> {
        for i in 0..self.sector_cache.len() {
            if self.sector_cache[i].addr == sec_addr {
                return Some(i);
            }
        }
        None
    }

    fn update_sector_empty_addr_cache(&mut self, sec_addr: u32, empty_addr: u32) {
        if let Some(idx) = self.get_sector_from_cache(sec_addr) {
            self.sector_cache[idx].empty_kv = empty_addr;
            self.sector_cache[idx].remain = self.sec_size as usize - (empty_addr - sec_addr) as usize;
        }
    }

    fn update_sector_status_store_cache(&mut self, sec_addr: u32, st: SectorStoreStatus) {
        if let Some(idx) = self.get_sector_from_cache(sec_addr) {
            self.sector_cache[idx].store_status = st;
        }
    }

    fn update_kv_cache(&mut self, name: &str, addr: u32) {
        let name_crc = (calc_crc32(0, name.as_bytes()) >> 16) as u16;
        let name_len = name.len();

        if addr != FDB_DATA_UNUSED {
            // Update existing
            for i in 0..self.kv_cache.len() {
                if self.kv_cache[i].name_crc == name_crc {
                    self.kv_cache[i].addr = addr;
                    return;
                }
            }
            // Find empty slot
            let mut empty_index = self.kv_cache.len();
            let mut min_activity_index = self.kv_cache.len();
            let mut min_activity: u16 = 0xFFFF;

            for i in 0..self.kv_cache.len() {
                if self.kv_cache[i].addr == FDB_DATA_UNUSED && empty_index == self.kv_cache.len() {
                    empty_index = i;
                } else if self.kv_cache[i].addr != FDB_DATA_UNUSED {
                    if self.kv_cache[i].active > 0 {
                        self.kv_cache[i].active -= 1;
                    }
                    if self.kv_cache[i].active < min_activity {
                        min_activity_index = i;
                        min_activity = self.kv_cache[i].active;
                    }
                }
            }

            if empty_index < self.kv_cache.len() {
                self.kv_cache[empty_index].addr = addr;
                self.kv_cache[empty_index].name_crc = name_crc;
                self.kv_cache[empty_index].active = self.kv_cache.len() as u16;
            } else if min_activity_index < self.kv_cache.len() {
                self.kv_cache[min_activity_index].addr = addr;
                self.kv_cache[min_activity_index].name_crc = name_crc;
                self.kv_cache[min_activity_index].active = self.kv_cache.len() as u16;
            }
        } else {
            // Delete
            for i in 0..self.kv_cache.len() {
                if self.kv_cache[i].name_crc == name_crc {
                    self.kv_cache[i].addr = FDB_DATA_UNUSED;
                    self.kv_cache[i].active = 0;
                    return;
                }
            }
        }
    }

    fn get_kv_from_cache(&mut self, name: &str) -> Option<u32> {
        let name_crc = (calc_crc32(0, name.as_bytes()) >> 16) as u16;
        let name_len = name.len();

        for i in 0..self.kv_cache.len() {
            if self.kv_cache[i].addr != FDB_DATA_UNUSED && self.kv_cache[i].name_crc == name_crc {
                // Read the KV name from flash to verify
                let mut saved_name = vec![0u8; FDB_KV_NAME_MAX];
                let kv_hdr_sz = kv_hdr_data_size();
                if self.be().read(self.kv_cache[i].addr + kv_hdr_sz as u32, &mut saved_name).is_ok() {
                    if name.as_bytes() == &saved_name[..name_len] {
                        let addr = self.kv_cache[i].addr;
                        let active = self.kv_cache[i].active;
                        self.kv_cache[i].active = if active >= 0xFFFF - self.kv_cache.len() as u16 {
                            0xFFFF
                        } else {
                            active + self.kv_cache.len() as u16
                        };
                        return Some(addr);
                    }
                }
            }
        }
        None
    }

    /// Find the next KV address by magic word.
    fn find_next_kv_addr(&self, start: u32, end: u32) -> u32 {
        // Check cache first
        let sec_addr = fdb_align_down(start as usize, self.sec_size as usize) as u32;
        if let Some(idx) = self.get_sector_from_cache(sec_addr) {
            if start == self.sector_cache[idx].empty_kv {
                return FDB_FAILED_ADDR;
            }
        }

        let mut buf = [0u8; 32];
        let start_bak = start;
        let mut cur = start;

        while cur < end && cur + 32 < end {
            if self.be().read(cur, &mut buf).is_err() {
                return FDB_FAILED_ADDR;
            }
            for i in 0..(32 - 4) {
                if cur + i as u32 >= end {
                    break;
                }
                // Little endian
                let magic = buf[i] as u32
                    | ((buf[i + 1] as u32) << 8)
                    | ((buf[i + 2] as u32) << 16)
                    | ((buf[i + 3] as u32) << 24);
                if magic == KV_MAGIC_WORD {
                    let addr = cur + i as u32;
                    let kv_addr = if kv_magic_offset() <= addr as usize {
                        addr - kv_magic_offset() as u32
                    } else {
                        continue;
                    };
                    if kv_addr >= start_bak {
                        return kv_addr;
                    }
                }
            }
            cur += (32 - 4) as u32;
        }

        FDB_FAILED_ADDR
    }

    /// Get next KV address in a sector.
    fn get_next_kv_addr(&self, sector: &KvdbSecInfo, pre_kv: &KvInfo) -> u32 {
        if sector.store_status == SectorStoreStatus::Empty {
            return FDB_FAILED_ADDR;
        }

        let sec_hdr_sz = sector_hdr_data_size(self.sec_size) as u32;

        let addr = if pre_kv.addr_start == FDB_FAILED_ADDR {
            sector.addr + sec_hdr_sz
        } else if pre_kv.addr_start <= sector.addr + self.sec_size {
            if pre_kv.crc_is_ok {
                pre_kv.addr_start + pre_kv.len
            } else {
                pre_kv.addr_start + wg_align(1) as u32
            }
        } else {
            return FDB_FAILED_ADDR;
        };

        if addr == FDB_FAILED_ADDR || addr > sector.addr + self.sec_size || pre_kv.len == 0 {
            return FDB_FAILED_ADDR;
        }

        self.find_next_kv_addr(addr, sector.addr + self.sec_size - sec_hdr_sz)
    }

    /// Read a KV from flash.
    fn read_kv(&mut self, kv: &mut KvInfo) -> Result<(), FdbErr> {
        let kv_hdr_sz = kv_hdr_data_size();
        let mut kv_hdr_buf = vec![0u8; kv_hdr_sz];
        self.be().read(kv.addr_start, &mut kv_hdr_buf)?;

        // Parse KV header from raw bytes
        let kv_status = status::get_status(&kv_hdr_buf[..KV_STATUS_TABLE_SIZE], FDB_KV_STATUS_NUM);
        kv.status = match kv_status {
            0 => KvStatus::Unused,
            1 => KvStatus::PreWrite,
            2 => KvStatus::Write,
            3 => KvStatus::PreDelete,
            4 => KvStatus::Deleted,
            5 => KvStatus::ErrHdr,
            _ => KvStatus::ErrHdr,
        };

        kv.len = u32::from_le_bytes(kv_hdr_buf[kv_len_offset()..kv_len_offset() + 4].try_into().unwrap());

        if kv.len == u32::MAX || kv.len > self.max_size || kv.len < kv_hdr_sz as u32 {
            kv.len = kv_hdr_sz as u32;
            if kv.status != KvStatus::ErrHdr {
                kv.status = KvStatus::ErrHdr;
                let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
                let _ = status::write_status(self.be(), kv.addr_start, &mut st, FDB_KV_STATUS_NUM, KvStatus::ErrHdr as usize, true);
            }
            kv.crc_is_ok = false;
            return Err(FdbErr::ReadErr);
        }

        let name_len = kv_hdr_buf[kv_name_len_offset()] as usize;
        let value_len = u32::from_le_bytes(
            kv_hdr_buf[kv_name_len_offset() + 1..kv_name_len_offset() + 5].try_into().unwrap()
        ) as usize;

        // Calculate CRC32
        let crc32_stored = u32::from_le_bytes(
            kv_hdr_buf[kv_name_len_offset() - 4..kv_name_len_offset()].try_into().unwrap()
        );

        let mut calc_crc: u32 = 0;
        // CRC32(name_len as uint32 + value_len as uint32 + name + value)
        let name_len_bytes = (name_len as u32).to_le_bytes();
        calc_crc = calc_crc32(calc_crc, &name_len_bytes);
        let value_len_bytes = (value_len as u32).to_le_bytes();
        calc_crc = calc_crc32(calc_crc, &value_len_bytes);

        let crc_data_len = kv.len as usize - kv_hdr_sz;
        let mut buf = [0u8; 32];
        let mut len = 0usize;
        while len < crc_data_len {
            let size = if len + 32 < crc_data_len { 32 } else { crc_data_len - len };
            let read_size = wg_align(size);
            let mut read_buf = vec![0u8; read_size];
            if self.be().read(kv.addr_start + kv_hdr_sz as u32 + len as u32, &mut read_buf).is_err() {
                kv.crc_is_ok = false;
                return Err(FdbErr::ReadErr);
            }
            calc_crc = calc_crc32(calc_crc, &read_buf[..size]);
            len += size;
        }

        if calc_crc != crc32_stored {
            kv.crc_is_ok = false;
            // Try to read name anyway
            let actual_name_len = name_len.min(FDB_KV_NAME_MAX);
            let aligned_name_len = wg_align(actual_name_len);
            let mut name_buf = vec![0u8; aligned_name_len];
            let _ = self.be().read(kv.addr_start + kv_hdr_sz as u32, &mut name_buf);
            kv.name[..actual_name_len].copy_from_slice(&name_buf[..actual_name_len]);
            kv.name_len = actual_name_len as u8;
            return Err(FdbErr::ReadErr);
        }

        kv.crc_is_ok = true;
        kv.name_len = name_len as u8;
        kv.value_len = value_len as u32;

        let actual_name_len = name_len.min(FDB_KV_NAME_MAX);
        let aligned_name_len = wg_align(actual_name_len);
        let mut name_buf = vec![0u8; aligned_name_len];
        self.be().read(kv.addr_start + kv_hdr_sz as u32, &mut name_buf)?;
        kv.name[..actual_name_len].copy_from_slice(&name_buf[..actual_name_len]);
        if actual_name_len < kv.name.len() {
            kv.name[actual_name_len] = 0;
        }

        kv.addr_value = kv.addr_start + kv_hdr_sz as u32 + wg_align(actual_name_len) as u32;

        Ok(())
    }

    /// Read sector info from flash.
    fn read_sector_info(&mut self, addr: u32, traversal: bool) -> Result<KvdbSecInfo, FdbErr> {
        assert_eq!(addr % self.sec_size, 0);

        let sec_hdr_sz = sector_hdr_data_size(self.sec_size);

        // Check cache
        if let Some(idx) = self.get_sector_from_cache(addr) {
            if !traversal || (traversal && self.sector_cache[idx].empty_kv != FDB_FAILED_ADDR) {
                return Ok(self.sector_cache[idx].clone());
            }
        }

        let mut sec_hdr_buf = vec![0u8; sec_hdr_sz];
        self.be().read(addr, &mut sec_hdr_buf)?;

        let mut sector = KvdbSecInfo::default();
        sector.addr = addr;

        // Parse sector header
        let store_status = status::get_status(
            &sec_hdr_buf[sector_store_offset()..sector_store_offset() + FDB_STORE_STATUS_TABLE_SIZE],
            FDB_SECTOR_STORE_STATUS_NUM,
        );
        sector.store_status = match store_status {
            0 => SectorStoreStatus::Unused,
            1 => SectorStoreStatus::Empty,
            2 => SectorStoreStatus::Using,
            3 => SectorStoreStatus::Full,
            _ => SectorStoreStatus::Unused,
        };

        let dirty_status = status::get_status(
            &sec_hdr_buf[sector_dirty_offset()..sector_dirty_offset() + FDB_DIRTY_STATUS_TABLE_SIZE],
            FDB_SECTOR_DIRTY_STATUS_NUM,
        );
        sector.dirty_status = match dirty_status {
            0 => SectorDirtyStatus::Unused,
            1 => SectorDirtyStatus::False,
            2 => SectorDirtyStatus::True,
            3 => SectorDirtyStatus::Gc,
            _ => SectorDirtyStatus::Unused,
        };

        let magic_off = sector_magic_offset();
        sector.magic = u32::from_le_bytes(sec_hdr_buf[magic_off..magic_off + 4].try_into().unwrap());

        if sector.magic != KVDB_SECTOR_MAGIC_WORD {
            sector.check_ok = false;
            sector.combined = SECTOR_NOT_COMBINED;
            return Err(FdbErr::InitFailed);
        }

        sector.check_ok = true;
        let combined_off = magic_off + 4;
        sector.combined = u32::from_le_bytes(sec_hdr_buf[combined_off..combined_off + 4].try_into().unwrap());

        if sector.combined != SECTOR_NOT_COMBINED && sector.combined != SECTOR_COMBINED {
            sector.check_ok = false;
            return Err(FdbErr::InitFailed);
        }

        if traversal {
            sector.remain = 0;
            sector.empty_kv = sector.addr + sec_hdr_sz as u32;

            if sector.store_status == SectorStoreStatus::Empty {
                sector.remain = self.sec_size as usize - sec_hdr_sz;
            } else if sector.store_status == SectorStoreStatus::Using {
                sector.remain = self.sec_size as usize - sec_hdr_sz;
                let mut kv_obj = KvInfo::default();
                kv_obj.addr_start = sector.addr + sec_hdr_sz as u32;
                loop {
                    let _ = self.read_kv(&mut kv_obj);
                    if !kv_obj.crc_is_ok {
                        if kv_obj.status != KvStatus::PreWrite && kv_obj.status != KvStatus::ErrHdr {
                            sector.remain = 0;
                            break;
                        }
                    }
                    sector.empty_kv += kv_obj.len;
                    if sector.remain >= kv_obj.len as usize {
                        sector.remain -= kv_obj.len as usize;
                    } else {
                        sector.remain = 0;
                    }

                    let next_addr = self.get_next_kv_addr(&sector, &kv_obj);
                    if next_addr == FDB_FAILED_ADDR {
                        break;
                    }
                    kv_obj.addr_start = next_addr;
                }

                // Check continue FF
                let ff_addr = status::continue_ff_addr(
                    self.be(),
                    sector.empty_kv,
                    sector.addr + self.sec_size,
                    self.sec_size,
                );
                if sector.empty_kv != ff_addr {
                    sector.empty_kv = ff_addr;
                    sector.remain = self.sec_size as usize - (ff_addr - sector.addr) as usize;
                }
            }

            self.update_sector_cache(&sector);
        } else {
            if self.get_sector_from_cache(sector.addr).is_none() {
                sector.empty_kv = FDB_FAILED_ADDR;
                sector.remain = 0;
                self.update_sector_cache(&sector);
            }
        }

        Ok(sector)
    }

    /// Get next sector address.
    fn get_next_sector_addr(&self, pre_sec: &KvdbSecInfo, traversed_len: u32) -> u32 {
        let cur_block_size = if pre_sec.combined == SECTOR_NOT_COMBINED {
            self.sec_size
        } else {
            pre_sec.combined * self.sec_size
        };

        if traversed_len + cur_block_size <= self.max_size {
            if pre_sec.addr + cur_block_size < self.max_size {
                pre_sec.addr + cur_block_size
            } else {
                0
            }
        } else {
            FDB_FAILED_ADDR
        }
    }

    /// Format a sector.
    fn format_sector(&mut self, addr: u32, combined_value: u32) -> Result<(), FdbErr> {
        assert_eq!(addr % self.sec_size, 0);

        self.be().erase(addr, self.sec_size as usize)?;

        let sec_hdr_sz = sector_hdr_data_size(self.sec_size);
        let mut sec_hdr_buf = vec![FDB_BYTE_ERASED; sec_hdr_sz];

        // For FDB_WRITE_GRAN=1, build the header in memory then write it all at once
        status::set_status(
            &mut sec_hdr_buf[sector_store_offset()..sector_store_offset() + FDB_STORE_STATUS_TABLE_SIZE],
            FDB_SECTOR_STORE_STATUS_NUM,
            SectorStoreStatus::Empty as usize,
        );
        status::set_status(
            &mut sec_hdr_buf[sector_dirty_offset()..sector_dirty_offset() + FDB_DIRTY_STATUS_TABLE_SIZE],
            FDB_SECTOR_DIRTY_STATUS_NUM,
            SectorDirtyStatus::False as usize,
        );

        let magic_off = sector_magic_offset();
        sec_hdr_buf[magic_off..magic_off + 4].copy_from_slice(&KVDB_SECTOR_MAGIC_WORD.to_le_bytes());
        sec_hdr_buf[magic_off + 4..magic_off + 8].copy_from_slice(&combined_value.to_le_bytes());
        sec_hdr_buf[magic_off + 8..magic_off + 12].copy_from_slice(&FDB_DATA_UNUSED.to_le_bytes());

        self.be().write(addr, &sec_hdr_buf, true)?;

        // Invalidate cache
        let mut sector = KvdbSecInfo::default();
        sector.addr = addr;
        sector.check_ok = false;
        sector.empty_kv = FDB_FAILED_ADDR;
        self.update_sector_cache(&sector);

        Ok(())
    }

    /// Update sector status.
    fn update_sec_status(&mut self, sector: &mut KvdbSecInfo, new_kv_len: usize) -> Result<bool, FdbErr> {
        let mut is_full = false;
        let threshold = sec_remain_threshold();

        if sector.store_status == SectorStoreStatus::Empty {
            let mut st = vec![0u8; FDB_STORE_STATUS_TABLE_SIZE];
            status::write_status(self.be(), sector.addr, &mut st, FDB_SECTOR_STORE_STATUS_NUM, SectorStoreStatus::Using as usize, true)?;
            self.update_sector_status_store_cache(sector.addr, SectorStoreStatus::Using);
            sector.store_status = SectorStoreStatus::Using;
        } else if sector.store_status == SectorStoreStatus::Using {
            if sector.remain < threshold || sector.remain - new_kv_len < threshold {
                let mut st = vec![0u8; FDB_STORE_STATUS_TABLE_SIZE];
                status::write_status(self.be(), sector.addr, &mut st, FDB_SECTOR_STORE_STATUS_NUM, SectorStoreStatus::Full as usize, true)?;
                self.update_sector_status_store_cache(sector.addr, SectorStoreStatus::Full);
                sector.store_status = SectorStoreStatus::Full;
                is_full = true;
            }
        }

        Ok(is_full)
    }

    /// Find a KV by key.
    fn find_kv(&mut self, key: &str) -> Option<KvInfo> {
        // Try cache first
        if let Some(addr) = self.get_kv_from_cache(key) {
            let mut kv = KvInfo::default();
            kv.addr_start = addr;
            if self.read_kv(&mut kv).is_ok() && kv.crc_is_ok {
                return Some(kv);
            }
        }

        // Linear scan
        let result = self.find_kv_no_cache(key);
        if let Some(ref kv) = result {
            self.update_kv_cache(key, kv.addr_start);
        }
        result
    }

    fn find_kv_no_cache(&mut self, key: &str) -> Option<KvInfo> {
        let mut kv = KvInfo::default();
        let mut found = false;
        self.kv_iterator(&mut kv, key, &mut found, Self::find_kv_cb);
        if found { Some(kv) } else { None }
    }

    fn find_kv_cb(kv: &KvInfo, key: &str, found: &mut bool) -> bool {
        let key_len = key.len();
        if kv.name_len as usize != key_len {
            return false;
        }
        if kv.crc_is_ok && kv.status == KvStatus::Write && &kv.name[..key_len] == key.as_bytes() {
            *found = true;
            return true;
        }
        false
    }

    /// Iterate over all KVs.
    fn kv_iterator<F>(&mut self, kv: &mut KvInfo, arg1: &str, arg2: &mut bool, callback: F)
    where
        F: Fn(&KvInfo, &str, &mut bool) -> bool,
    {
        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;
        let sec_hdr_sz = sector_hdr_data_size(self.sec_size) as u32;

        loop {
            traversed_len += self.sec_size;
            let sector = match self.read_sector_info(sec_addr, false) {
                Ok(s) => s,
                Err(_) => {
                    let next = self.get_next_sector_addr(&{
                        let mut s = KvdbSecInfo::default();
                        s.addr = sec_addr;
                        s.combined = SECTOR_NOT_COMBINED;
                        s
                    }, traversed_len);
                    if next == FDB_FAILED_ADDR { break; }
                    sec_addr = next;
                    continue;
                }
            };

            if sector.store_status == SectorStoreStatus::Using || sector.store_status == SectorStoreStatus::Full {
                kv.addr_start = sector.addr + sec_hdr_sz;
                loop {
                    if self.read_kv(kv).is_err() && !kv.crc_is_ok {
                        // Continue scanning
                    }
                    if callback(kv, arg1, arg2) {
                        return;
                    }
                    let next = self.get_next_kv_addr(&sector, kv);
                    if next == FDB_FAILED_ADDR { break; }
                    kv.addr_start = next;
                }
            }

            let next = self.get_next_sector_addr(&sector, traversed_len);
            if next == FDB_FAILED_ADDR { break; }
            sec_addr = next;
        }
    }

    /// Sector iterator.
    fn sector_iterator<F>(&mut self, status_filter: SectorStoreStatus, traversal: bool, mut callback: F)
    where
        F: FnMut(&mut Kvdb, &KvdbSecInfo) -> bool,
    {
        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;

        loop {
            traversed_len += self.sec_size;
            let sector = match self.read_sector_info(sec_addr, false) {
                Ok(s) => s,
                Err(_) => {
                    let next = self.get_next_sector_addr(&{
                        let mut s = KvdbSecInfo::default();
                        s.addr = sec_addr;
                        s.combined = SECTOR_NOT_COMBINED;
                        s
                    }, traversed_len);
                    if next == FDB_FAILED_ADDR { break; }
                    sec_addr = next;
                    continue;
                }
            };

            if status_filter == SectorStoreStatus::Unused || sector.store_status == status_filter {
                let sector = if traversal {
                    match self.read_sector_info(sec_addr, true) {
                        Ok(s) => s,
                        Err(_) => sector,
                    }
                } else {
                    sector
                };

                if callback(self, &sector) {
                    return;
                }
            }

            let next = self.get_next_sector_addr(&sector, traversed_len);
            if next == FDB_FAILED_ADDR { break; }
            sec_addr = next;
        }
    }

    /// Allocate a KV in a sector.
    fn alloc_kv(&mut self, kv_size: usize) -> (u32, KvdbSecInfo) {
        let mut empty_kv = FDB_FAILED_ADDR;
        let mut empty_sector = 0usize;
        let mut using_sector = 0usize;
        let threshold = sec_remain_threshold();

        // Statistics
        let mut temp_sector = KvdbSecInfo::default();
        let sec_addr_bak = self.oldest_addr;
        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;

        loop {
            traversed_len += self.sec_size;
            match self.read_sector_info(sec_addr, false) {
                Ok(sector) => {
                    if sector.check_ok && sector.store_status == SectorStoreStatus::Empty {
                        empty_sector += 1;
                    } else if sector.check_ok && sector.store_status == SectorStoreStatus::Using {
                        using_sector += 1;
                    }
                }
                Err(_) => {}
            }

            let next = self.get_next_sector_addr(&{
                let mut s = KvdbSecInfo::default();
                s.addr = sec_addr;
                s.combined = SECTOR_NOT_COMBINED;
                s
            }, traversed_len);
            if next == FDB_FAILED_ADDR { break; }
            sec_addr = next;
        }

        // Try using sectors first
        if using_sector > 0 {
            sec_addr = self.oldest_addr;
            traversed_len = 0;
            loop {
                traversed_len += self.sec_size;
                let sector = match self.read_sector_info(sec_addr, true) {
                    Ok(s) => s,
                    Err(_) => {
                        let next = self.get_next_sector_addr(&{
                            let mut s = KvdbSecInfo::default();
                            s.addr = sec_addr;
                            s.combined = SECTOR_NOT_COMBINED;
                            s
                        }, traversed_len);
                        if next == FDB_FAILED_ADDR { break; }
                        sec_addr = next;
                        continue;
                    }
                };

                if sector.check_ok && sector.remain > kv_size + threshold
                    && (sector.dirty_status == SectorDirtyStatus::False
                        || (sector.dirty_status == SectorDirtyStatus::True && !self.gc_request))
                    && sector.store_status == SectorStoreStatus::Using
                {
                    empty_kv = sector.empty_kv;
                    return (empty_kv, sector);
                }

                let next = self.get_next_sector_addr(&sector, traversed_len);
                if next == FDB_FAILED_ADDR { break; }
                sec_addr = next;
            }
        }

        // Try empty sectors
        if empty_sector > 0 && empty_kv == FDB_FAILED_ADDR {
            if empty_sector > FDB_GC_EMPTY_SEC_THRESHOLD || self.gc_request {
                sec_addr = self.oldest_addr;
                traversed_len = 0;
                loop {
                    traversed_len += self.sec_size;
                    let sector = match self.read_sector_info(sec_addr, true) {
                        Ok(s) => s,
                        Err(_) => {
                            let next = self.get_next_sector_addr(&{
                                let mut s = KvdbSecInfo::default();
                                s.addr = sec_addr;
                                s.combined = SECTOR_NOT_COMBINED;
                                s
                            }, traversed_len);
                            if next == FDB_FAILED_ADDR { break; }
                            sec_addr = next;
                            continue;
                        }
                    };

                    if sector.check_ok && sector.remain > kv_size + threshold
                        && (sector.dirty_status == SectorDirtyStatus::False
                            || (sector.dirty_status == SectorDirtyStatus::True && !self.gc_request))
                        && sector.store_status == SectorStoreStatus::Empty
                    {
                        empty_kv = sector.empty_kv;
                        return (empty_kv, sector);
                    }

                    let next = self.get_next_sector_addr(&sector, traversed_len);
                    if next == FDB_FAILED_ADDR { break; }
                    sec_addr = next;
                }
            } else {
                self.gc_request = true;
            }
        }

        (empty_kv, KvdbSecInfo::default())
    }

    /// Delete a KV.
    fn del_kv(&mut self, key: Option<&str>, old_kv: &KvInfo, complete_del: bool) -> Result<(), FdbErr> {
        let mut result = FdbErr::NoErr;

        if !complete_del {
            let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
            result = status::write_status(self.be(), old_kv.addr_start, &mut st, FDB_KV_STATUS_NUM, KvStatus::PreDelete as usize, false);
            self.last_is_complete_del = true;
        } else {
            let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
            result = status::write_status(self.be(), old_kv.addr_start, &mut st, FDB_KV_STATUS_NUM, KvStatus::Deleted as usize, true);

            if !self.last_is_complete_del && result == FdbErr::NoErr {
                if let Some(k) = key {
                    self.update_kv_cache(k, FDB_DATA_UNUSED);
                } else {
                    let name = std::str::from_utf8(&old_kv.name[..old_kv.name_len as usize]).unwrap_or("");
                    self.update_kv_cache(name, FDB_DATA_UNUSED);
                }
            }
            self.last_is_complete_del = false;
        }

        // Update dirty status
        if result == FdbErr::NoErr {
            let dirty_status_addr = fdb_align_down(old_kv.addr_start as usize, self.sec_size as usize) as u32
                + sector_dirty_offset() as u32;
            let mut dirty_st = vec![0u8; FDB_DIRTY_STATUS_TABLE_SIZE];
            let current_dirty = status::read_status(self.be(), dirty_status_addr, &mut dirty_st, FDB_SECTOR_DIRTY_STATUS_NUM);
            if current_dirty == SectorDirtyStatus::False as usize {
                let mut st = vec![0u8; FDB_DIRTY_STATUS_TABLE_SIZE];
                result = status::write_status(self.be(), dirty_status_addr, &mut st, FDB_SECTOR_DIRTY_STATUS_NUM, SectorDirtyStatus::True as usize, true);

                let sec_addr = fdb_align_down(old_kv.addr_start as usize, self.sec_size as usize) as u32;
                if let Some(idx) = self.get_sector_from_cache(sec_addr) {
                    self.sector_cache[idx].dirty_status = SectorDirtyStatus::True;
                }
            }
        }

        Ok(result)
    }

    /// Move a KV to new space.
    fn move_kv(&mut self, kv: &KvInfo) -> Result<(), FdbErr> {
        if kv.status == KvStatus::Write {
            self.del_kv(None, kv, false)?;
        }

        let (kv_addr, mut sector) = self.alloc_kv(kv.len as usize);
        if kv_addr == FDB_FAILED_ADDR {
            return Err(FdbErr::SavedFull);
        }

        // Update sector status
        self.update_sec_status(&mut sector, kv.len as usize)?;

        // Write KV header (pre-write status)
        let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
        status::write_status(self.be(), kv_addr, &mut st, FDB_KV_STATUS_NUM, KvStatus::PreWrite as usize, false)?;

        // Copy data
        let kv_hdr_sz = kv_hdr_data_size() as u32;
        let magic_off = kv_magic_offset() as u32;
        let kv_len = kv.len - magic_off;
        let mut buf = [0u8; 32];
        let mut len = 0u32;
        while len < kv_len {
            let size = if len + 32 < kv_len { 32 } else { kv_len - len };
            let read_size = wg_align(size as usize);
            let mut read_buf = vec![0u8; read_size];
            self.be().read(kv.addr_start + magic_off + len, &mut read_buf)?;
            self.be().write(kv_addr + magic_off + len, &read_buf[..size as usize], true)?;
            len += size as u32;
        }

        // Write status to WRITE
        let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
        status::write_status(self.be(), kv_addr, &mut st, FDB_KV_STATUS_NUM, KvStatus::Write as usize, true)?;

        // Update caches
        self.update_sector_empty_addr_cache(
            fdb_align_down(kv_addr as usize, self.sec_size as usize) as u32,
            kv_addr + kv_hdr_sz + wg_align(kv.name_len as usize) as u32 + wg_align(kv.value_len as usize) as u32,
        );
        let name = std::str::from_utf8(&kv.name[..kv.name_len as usize]).unwrap_or("");
        self.update_kv_cache(name, kv_addr);

        // Delete old KV
        self.del_kv(None, kv, true)?;

        Ok(())
    }

    /// GC collect by free size.
    fn gc_collect_by_free_size(&mut self, free_size: usize) {
        let mut empty_sec_num = 0usize;
        let mut empty_sec_addr = 0u32;

        // Check empty sector count
        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;
        loop {
            traversed_len += self.sec_size;
            match self.read_sector_info(sec_addr, false) {
                Ok(sector) => {
                    if sector.check_ok && sector.store_status == SectorStoreStatus::Empty {
                        empty_sec_num += 1;
                        empty_sec_addr = sector.addr;
                    }
                }
                Err(_) => {}
            }
            let next = self.get_next_sector_addr(&{
                let mut s = KvdbSecInfo::default();
                s.addr = sec_addr;
                s.combined = SECTOR_NOT_COMBINED;
                s
            }, traversed_len);
            if next == FDB_FAILED_ADDR { break; }
            sec_addr = next;
        }

        if empty_sec_num <= FDB_GC_EMPTY_SEC_THRESHOLD {
            // Do GC
            sec_addr = self.oldest_addr;
            traversed_len = 0;
            let mut last_gc_sec_addr = empty_sec_addr;
            loop {
                traversed_len += self.sec_size;
                let sector = match self.read_sector_info(sec_addr, false) {
                    Ok(s) => s,
                    Err(_) => {
                        let next = self.get_next_sector_addr(&{
                            let mut s = KvdbSecInfo::default();
                            s.addr = sec_addr;
                            s.combined = SECTOR_NOT_COMBINED;
                            s
                        }, traversed_len);
                        if next == FDB_FAILED_ADDR { break; }
                        sec_addr = next;
                        continue;
                    }
                };

                if sector.check_ok && (sector.dirty_status == SectorDirtyStatus::True || sector.dirty_status == SectorDirtyStatus::Gc) {
                    // Mark as GC
                    let dirty_addr = sector.addr + sector_dirty_offset() as u32;
                    let mut dirty_st = vec![0u8; FDB_DIRTY_STATUS_TABLE_SIZE];
                    let _ = status::write_status(self.be(), dirty_addr, &mut dirty_st, FDB_SECTOR_DIRTY_STATUS_NUM, SectorDirtyStatus::Gc as usize, true);

                    // Move all valid KVs
                    let sec_hdr_sz = sector_hdr_data_size(self.sec_size) as u32;
                    let mut kv_obj = KvInfo::default();
                    kv_obj.addr_start = sector.addr + sec_hdr_sz;
                    loop {
                        let _ = self.read_kv(&mut kv_obj);
                        if kv_obj.crc_is_ok && (kv_obj.status == KvStatus::Write || kv_obj.status == KvStatus::PreDelete) {
                            if self.move_kv(&kv_obj).is_err() {
                                break;
                            }
                        }
                        let next = self.get_next_kv_addr(&sector, &kv_obj);
                        if next == FDB_FAILED_ADDR { break; }
                        kv_obj.addr_start = next;
                    }

                    self.format_sector(sector.addr, SECTOR_NOT_COMBINED)?;
                    let old_last = last_gc_sec_addr;
                    last_gc_sec_addr = sector.addr;

                    // Update oldest_addr
                    let next_sec = self.get_next_sector_addr(&sector, 0);
                    self.oldest_addr = next_sec;

                    // Check if we have enough space
                    if let Ok(last_gc_sector) = self.read_sector_info(old_last, true) {
                        if last_gc_sector.remain > free_size {
                            break;
                        }
                    }
                }

                let next = self.get_next_sector_addr(&sector, traversed_len);
                if next == FDB_FAILED_ADDR { break; }
                sec_addr = next;
            }
        }

        self.gc_request = false;
    }

    /// Create a KV blob.
    fn create_kv_blob(&mut self, sector: &mut KvdbSecInfo, key: &str, value: &[u8]) -> Result<(), FdbErr> {
        let kv_hdr_sz = kv_hdr_data_size();
        let key_len = key.len();
        let value_len = value.len();

        if key_len > FDB_KV_NAME_MAX {
            return Err(FdbErr::KvNameErr);
        }

        let total_len = kv_hdr_sz + wg_align(key_len) + wg_align(value_len);
        if total_len > self.sec_size as usize - sector_hdr_data_size(self.sec_size) {
            return Err(FdbErr::SavedFull);
        }

        let kv_addr = if sector.empty_kv != FDB_FAILED_ADDR {
            sector.empty_kv
        } else {
            let (addr, _) = self.alloc_kv(total_len);
            if addr == FDB_FAILED_ADDR {
                // Try GC
                if self.gc_request {
                    self.gc_collect_by_free_size(total_len);
                    let (addr2, _) = self.alloc_kv(total_len);
                    if addr2 == FDB_FAILED_ADDR {
                        return Err(FdbErr::SavedFull);
                    }
                    addr2
                } else {
                    return Err(FdbErr::SavedFull);
                }
            } else {
                addr
            }
        };

        let is_full = self.update_sec_status(sector, total_len)?;

        // Build KV header
        let mut kv_hdr_buf = vec![FDB_BYTE_ERASED; kv_hdr_sz];
        // Status table: pre-write
        status::set_status(
            &mut kv_hdr_buf[..KV_STATUS_TABLE_SIZE],
            FDB_KV_STATUS_NUM,
            KvStatus::PreWrite as usize,
        );
        // Magic
        kv_hdr_buf[kv_magic_offset()..kv_magic_offset() + 4].copy_from_slice(&KV_MAGIC_WORD.to_le_bytes());
        // Len
        kv_hdr_buf[kv_len_offset()..kv_len_offset() + 4].copy_from_slice(&(total_len as u32).to_le_bytes());
        // Name_len
        kv_hdr_buf[kv_name_len_offset()] = key_len as u8;
        // Value_len
        kv_hdr_buf[kv_name_len_offset() + 1..kv_name_len_offset() + 5].copy_from_slice(&(value_len as u32).to_le_bytes());

        // Calculate CRC32
        let mut crc: u32 = 0;
        let name_len_bytes = (key_len as u32).to_le_bytes();
        crc = calc_crc32(crc, &name_len_bytes);
        let value_len_bytes = (value_len as u32).to_le_bytes();
        crc = calc_crc32(crc, &value_len_bytes);
        crc = calc_crc32(crc, key.as_bytes());
        // Pad name alignment
        let name_pad = wg_align(key_len) - key_len;
        for _ in 0..name_pad {
            crc = calc_crc32(crc, &[FDB_BYTE_ERASED]);
        }
        crc = calc_crc32(crc, value);
        let value_pad = wg_align(value_len) - value_len;
        for _ in 0..value_pad {
            crc = calc_crc32(crc, &[FDB_BYTE_ERASED]);
        }

        // CRC32 stored at offset kv_name_len_offset - 4
        let crc_off = kv_name_len_offset() - 4;
        kv_hdr_buf[crc_off..crc_off + 4].copy_from_slice(&crc.to_le_bytes());

        // Write header (first status, then rest)
        status::write_status(self.be(), kv_addr, &mut kv_hdr_buf[..KV_STATUS_TABLE_SIZE].to_vec(), FDB_KV_STATUS_NUM, KvStatus::PreWrite as usize, false)?;
        self.be().write(kv_addr + kv_magic_offset() as u32, &kv_hdr_buf[kv_magic_offset()..], false)?;

        // Write key name
        status::write_align(self.be(), kv_addr + kv_hdr_sz as u32, key.as_bytes())?;

        // Update cache
        if !is_full {
            self.update_sector_empty_addr_cache(
                sector.addr,
                kv_addr + kv_hdr_sz as u32 + wg_align(key_len) as u32 + wg_align(value_len) as u32,
            );
        }
        self.update_kv_cache(key, kv_addr);

        // Write value
        status::write_align(self.be(), kv_addr + kv_hdr_sz as u32 + wg_align(key_len) as u32, value)?;

        // Set status to WRITE
        let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
        status::write_status(self.be(), kv_addr, &mut st, FDB_KV_STATUS_NUM, KvStatus::Write as usize, true)?;

        if is_full {
            self.gc_request = true;
        }

        Ok(())
    }

    /// Set a KV value.
    fn set_kv(&mut self, key: &str, value: &[u8]) -> Result<(), FdbErr> {
        if value.is_empty() {
            // Delete
            return self.del_kv(Some(key), &KvInfo::default(), true);
        }

        let kv_len = kv_hdr_data_size() + wg_align(key.len()) + wg_align(value.len());
        let (empty_addr, _) = self.alloc_kv(kv_len);
        if empty_addr == FDB_FAILED_ADDR {
            if self.gc_request {
                self.gc_collect_by_free_size(kv_len);
                let (empty_addr2, _) = self.alloc_kv(kv_len);
                if empty_addr2 == FDB_FAILED_ADDR {
                    return Err(FdbErr::SavedFull);
                }
            } else {
                return Err(FdbErr::SavedFull);
            }
        }

        let kv_is_found = self.find_kv(key);
        if let Some(ref old_kv) = kv_is_found {
            self.del_kv(Some(key), old_kv, false)?;
        }

        let mut sector = KvdbSecInfo::default();
        sector.empty_kv = FDB_FAILED_ADDR;
        let result = self.create_kv_blob(&mut sector, key, value);

        if let Some(ref old_kv) = kv_is_found {
            if result.is_ok() {
                let _ = self.del_kv(Some(key), old_kv, true);
            }
        }

        if self.gc_request {
            self.gc_collect_by_free_size(kv_hdr_data_size() + wg_align(key.len()) + wg_align(value.len()));
        }

        result
    }

    /// Get a KV value.
    fn get_kv(&mut self, key: &str, value_buf: &mut [u8]) -> (usize, usize) {
        if let Some(kv) = self.find_kv(key) {
            let value_len = kv.value_len as usize;
            let read_len = value_buf.len().min(value_len);
