//! FFI — C-compatible exports for the flashdb_rust static library.
//! Minimal stubs to satisfy the build; will be filled in as needed.

use std::ffi::{CStr, CString};
use std::os::raw::c_char;
use std::ptr;

use crate::{Kvdb, Tsdb, FdbErr, FdbTime, Blob, KvInfo, TslInfo, TslStatus};

pub type FdbKvdbT = *mut Kvdb;
pub type FdbTsdbT = *mut Tsdb;
pub type FdbKvT = *mut KvInfo;
pub type FdbTslT = *mut TslInfo;

fn err_to_c(e: FdbErr) -> i32 {
    e as i32
}

// ---- KVDB API ----

#[no_mangle]
pub extern "C" fn fdb_kvdb_init(
    db: FdbKvdbT,
    name: *const c_char,
    path: *const c_char,
    _default_kv: *const u8,
    user_data: *mut core::ffi::c_void,
) -> i32 {
    if db.is_null() || name.is_null() || path.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let name_str = unsafe { CStr::from_ptr(name) }.to_str().unwrap_or("");
    let path_str = unsafe { CStr::from_ptr(path) }.to_str().unwrap_or("");
    let db_ref = unsafe { &mut *db };
    match db_ref.init(name_str, path_str, None, user_data) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kvdb_deinit(db: FdbKvdbT) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let db_ref = unsafe { &mut *db };
    match db_ref.deinit() {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kvdb_control(db: FdbKvdbT, cmd: i32, arg: *mut core::ffi::c_void) {
    if db.is_null() {
        return;
    }
    let db_ref = unsafe { &mut *db };
    db_ref.control(cmd, arg);
}

#[no_mangle]
pub extern "C" fn fdb_kv_set(db: FdbKvdbT, key: *const c_char, value: *const c_char) -> i32 {
    if db.is_null() || key.is_null() {
        return err_to_c(FdbErr::KvNameErr);
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let db_ref = unsafe { &mut *db };
    if value.is_null() {
        match db_ref.kv_del(key_str) {
            Ok(()) => err_to_c(FdbErr::NoErr),
            Err(e) => err_to_c(e),
        }
    } else {
        let val_str = unsafe { CStr::from_ptr(value) }.to_str().unwrap_or("");
        match db_ref.kv_set(key_str, val_str) {
            Ok(()) => err_to_c(FdbErr::NoErr),
            Err(e) => err_to_c(e),
        }
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_get(db: FdbKvdbT, key: *const c_char) -> *mut c_char {
    if db.is_null() || key.is_null() {
        return ptr::null_mut();
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let db_ref = unsafe { &mut *db };
    match db_ref.kv_get(key_str) {
        Some(val) => {
            let c_str = CString::new(val).unwrap_or_default();
            c_str.into_raw()
        }
        None => ptr::null_mut(),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_del(db: FdbKvdbT, key: *const c_char) -> i32 {
    if db.is_null() || key.is_null() {
        return err_to_c(FdbErr::KvNameErr);
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let db_ref = unsafe { &mut *db };
    match db_ref.kv_del(key_str) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_set_blob(db: FdbKvdbT, key: *const c_char, value_buf: *const core::ffi::c_void, buf_len: usize) -> i32 {
    if db.is_null() || key.is_null() {
        return err_to_c(FdbErr::KvNameErr);
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let data = if value_buf.is_null() || buf_len == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(value_buf as *const u8, buf_len) }
    };
    let db_ref = unsafe { &mut *db };
    match db_ref.kv_set_blob(key_str, data) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_get_blob(db: FdbKvdbT, key: *const c_char, value_buf: *mut core::ffi::c_void, buf_len: usize) -> usize {
    if db.is_null() || key.is_null() || value_buf.is_null() || buf_len == 0 {
        return 0;
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let buf = unsafe { std::slice::from_raw_parts_mut(value_buf as *mut u8, buf_len) };
    let db_ref = unsafe { &mut *db };
    db_ref.kv_get_blob(key_str, buf)
}

#[no_mangle]
pub extern "C" fn fdb_kv_set_default(db: FdbKvdbT) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let db_ref = unsafe { &mut *db };
    match db_ref.set_default() {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kvdb_check(db: FdbKvdbT) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let db_ref = unsafe { &mut *db };
    match db_ref.check() {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_kv_print(_db: FdbKvdbT) {}

// ---- TSDB API ----

#[no_mangle]
pub extern "C" fn fdb_tsdb_init(
    db: FdbTsdbT,
    name: *const c_char,
    path: *const c_char,
    get_time: Option<extern "C" fn() -> FdbTime>,
    max_len: usize,
    user_data: *mut core::ffi::c_void,
) -> i32 {
    if db.is_null() || name.is_null() || path.is_null() || get_time.is_none() {
        return err_to_c(FdbErr::InitFailed);
    }
    let name_str = unsafe { CStr::from_ptr(name) }.to_str().unwrap_or("");
    let path_str = unsafe { CStr::from_ptr(path) }.to_str().unwrap_or("");
    let get_time_fn = get_time.unwrap();
    let db_ref = unsafe { &mut *db };
    match db_ref.init(name_str, path_str, get_time_fn, max_len, user_data) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_tsdb_deinit(db: FdbTsdbT) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let db_ref = unsafe { &mut *db };
    match db_ref.deinit() {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_tsdb_control(db: FdbTsdbT, cmd: i32, arg: *mut core::ffi::c_void) {
    if db.is_null() {
        return;
    }
    let db_ref = unsafe { &mut *db };
    db_ref.control(cmd, arg);
}

#[no_mangle]
pub extern "C" fn fdb_tsl_append(db: FdbTsdbT, value_buf: *const core::ffi::c_void, buf_len: usize) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::WriteErr);
    }
    let data = if value_buf.is_null() || buf_len == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(value_buf as *const u8, buf_len) }
    };
    let db_ref = unsafe { &mut *db };
    match db_ref.tsl_append(data) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_tsl_append_with_ts(db: FdbTsdbT, value_buf: *const core::ffi::c_void, buf_len: usize, timestamp: FdbTime) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::WriteErr);
    }
    let data = if value_buf.is_null() || buf_len == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(value_buf as *const u8, buf_len) }
    };
    let db_ref = unsafe { &mut *db };
    match db_ref.tsl_append_with_ts(data, timestamp) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_tsl_query_count(db: FdbTsdbT, from: FdbTime, to: FdbTime, status: u32) -> usize {
    if db.is_null() {
        return 0;
    }
    let tsl_status = match status {
        0 => TslStatus::Unused,
        1 => TslStatus::PreWrite,
        2 => TslStatus::Write,
        3 => TslStatus::UserStatus1,
        4 => TslStatus::Deleted,
        5 => TslStatus::UserStatus2,
        _ => TslStatus::Unused,
    };
    let db_ref = unsafe { &mut *db };
    db_ref.tsl_query_count(from, to, tsl_status)
}

#[no_mangle]
pub extern "C" fn fdb_tsl_clean(db: FdbTsdbT) {
    if db.is_null() {
        return;
    }
    let db_ref = unsafe { &mut *db };
    db_ref.tsl_clean();
}

#[no_mangle]
pub extern "C" fn fdb_calc_crc32(crc: u32, buf: *const core::ffi::c_void, size: usize) -> u32 {
    if buf.is_null() || size == 0 {
        return crc;
    }
    let data = unsafe { std::slice::from_raw_parts(buf as *const u8, size) };
    crate::calc_crc32(crc, data)
}

