    let db_ref = unsafe { &mut *db };
    db_ref.control(cmd, arg);
}

#[no_mangle]
pub extern "C" fn fdb_tsl_append(db: FdbTsdbT, value_buf: *const core::ffi::c_void, buf_len: usize) -> i32 {
