    };
    let db_ref = unsafe { &mut *db };
    match db_ref.tsl_append(data) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_tsl_append_with_ts(db: FdbTsdbT, value_buf: *const core::ffi::c_void, buf_len: usize, timestamp: FdbTime) -> i32 {
    if db.is_null() { return err_to_c(FdbErr::WriteErr); }
    let data = if value_buf.is_null() || buf_len == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(value_buf as *const u8, buf_len) }
    };
    let db_ref = unsafe { &mut *db };
    match db_ref.tsl_append_with_ts(data, timestamp) {
        Ok(()) => err_to_c(FdbErr::NoErr),
        Err(e) => err_to_c(e),
    }
}

#[no_mangle]
pub extern "C" fn fdb_tsl_query_count(db: FdbTsdbT, from: FdbTime, to: FdbTime, status: u32) -> usize {
    if db.is_null() { return 0; }
    let tsl_status = match status {
        0 => TslStatus::Unused,
        1 => TslStatus::PreWrite,
        2 => TslStatus::Write,
        3 => TslStatus::UserStatus1,
        4 => TslStatus::Deleted,
        5 => TslStatus::UserStatus2,
        _ => TslStatus::Unused,
    };
    let db_ref = unsafe { &mut *db };
    db_ref.tsl_query_count(from, to, tsl_status)
}

#[no_mangle]
pub extern "C" fn fdb_tsl_clean(db: FdbTsdbT) {
    if db.is_null() { return; }
    let db_ref = unsafe { &mut *db };
    db_ref.tsl_clean();
}

#[no_mangle]
pub extern "C" fn fdb_calc_crc32(crc: u32, buf: *const core::ffi::c_void, size: usize) -> u32 {
    if buf.is_null() || size == 0 { return crc; }
    let data = unsafe { std::slice::from_raw_parts(buf as *const u8, size) };
    crate::calc_crc32(crc, data)
}

