display.text:
//! POSIX file mode storage backend for FlashDB.
//! Faithful translation of fdb_file.c (POSIX mode).

use std::fs;
use std::io::{Read, Seek, SeekFrom, Write};
use std::path::PathBuf;

use crate::{StorageBackend, FdbErr, FDB_BYTE_ERASED, fdb_align_down};

const DB_PATH_MAX: usize = 256;
const DB_NAME_MAX: usize = 8;
const BUF_SIZE: usize = 32;
const FILE_CACHE_TABLE_SIZE: usize = crate::FDB_FILE_CACHE_TABLE_SIZE;

struct FileCacheEntry {
    sec_addr: u32,
    fd: Option<fs::File>,
}

impl Default for FileCacheEntry {
    fn default() -> Self {
        FileCacheEntry {
            sec_addr: crate::FDB_FAILED_ADDR,
            fd: None,
        }
    }
}

pub struct FileBackend {
    db_name: String,
    dir: PathBuf,
    sec_size: u32,
    max_size: u32,
    cache: Vec<FileCacheEntry>,
}

impl FileBackend {
    pub fn new(db_name: &str, dir: &str, sec_size: u32, max_size: u32) -> Self {
        let mut cache = Vec::with_capacity(FILE_CACHE_TABLE_SIZE);
        for _ in 0..FILE_CACHE_TABLE_SIZE {
            cache.push(FileCacheEntry::default());
        }
        FileBackend {
            db_name: db_name.to_string(),
            dir: PathBuf::from(dir),
            sec_size,
            max_size,
            cache,
        }
    }

    fn get_db_file_path(&self, addr: u32) -> PathBuf {
        let sec_addr = fdb_align_down(addr as usize, self.sec_size as usize) as u32;
        let index = sec_addr / self.sec_size;
        let file_name = format!("{:.*}.fdb.{}", DB_NAME_MAX, self.db_name, index);
        self.dir.join(&file_name)
    }

    fn get_file_from_cache(&self, sec_addr: u32) -> Option<&fs::File> {
        for entry in &self.cache {
            if entry.sec_addr == sec_addr {
                return entry.fd.as_ref();
            }
        }
        None
    }

    fn update_file_cache(&mut self, sec_addr: u32, fd: Option<fs::File>) {
        // Check if already in cache
        for entry in &mut self.cache {
            if entry.sec_addr == sec_addr {
                entry.fd = fd;
                return;
            }
        }

        // Find free slot
        if fd.is_some() {
            for i in 0..self.cache.len() {
                if self.cache[i].fd.is_none() && self.cache[i].sec_addr == crate::FDB_FAILED_ADDR {
                    self.cache[i].sec_addr = sec_addr;
                    self.cache[i].fd = fd;
                    return;
                }
            }
            // Cache full — close the last entry and shift
            if let Some(ref mut f) = self.cache.last_mut().unwrap().fd {
                let _ = f.sync_all();
            }
            for i in (1..self.cache.len()).rev() {
                self.cache[i] = std::mem::take(&mut self.cache[i - 1]);
            }
            self.cache[0].sec_addr = sec_addr;
            self.cache[0].fd = fd;
        }
    }

    fn open_db_file(&mut self, addr: u32, clean: bool) -> Option<fs::File> {
        let sec_addr = fdb_align_down(addr as usize, self.sec_size as usize) as u32;

        // Try cache first
        let cached_fd = self.get_file_from_cache(sec_addr).and_then(|f| f.try_clone().ok());

        if cached_fd.is_some() && !clean {
            return cached_fd;
        }

        let path = self.get_db_file_path(addr);

        // Close cached fd if we're cleaning
        if clean {
            self.update_file_cache(sec_addr, None);
        }

        if clean {
            // Clean the old file
            if let Ok(mut f) = fs::OpenOptions::new()
                .read(true)
                .write(true)
                .create(true)
                .truncate(true)
                .open(&path)
            {
                let _ = f.sync_all();
            }
        }

        // Open the file
        if self.get_file_from_cache(sec_addr).is_none() {
            if let Ok(f) = fs::OpenOptions::new()
                .read(true)
                .write(true)
                .open(&path)
            {
                self.update_file_cache(sec_addr, Some(f));
            } else {
                // File doesn't exist yet; create it
                // Ensure directory exists
                if let Some(parent) = path.parent() {
                    let _ = fs::create_dir_all(parent);
                }
                if let Ok(f) = fs::OpenOptions::new()
                    .read(true)
                    .write(true)
                    .create(true)
                    .open(&path)
                {
                    self.update_file_cache(sec_addr, Some(f));
                }
            }
        }

        self.get_file_from_cache(sec_addr).and_then(|f| f.try_clone().ok())
    }
}

impl StorageBackend for FileBackend {
    fn read(&mut self, addr: u32, buf: &mut [u8]) -> Result<(), FdbErr> {
        let fd = self.open_db_file(addr, false);
        match fd {
            Some(mut f) => {
                let offset = addr % self.sec_size;
                if f.seek(SeekFrom::Start(offset as u64)).is_err() {
                    return Err(FdbErr::ReadErr);
                }
                match f.read_exact(buf) {
                    Ok(()) => Ok(()),
                    Err(_) => Err(FdbErr::ReadErr),
                }
            }
            None => Err(FdbErr::ReadErr),
        }
    }

    fn write(&mut self, addr: u32, data: &[u8], sync: bool) -> Result<(), FdbErr> {
        let fd = self.open_db_file(addr, false);
        match fd {
            Some(mut f) => {
                let offset = addr % self.sec_size;
                if f.seek(SeekFrom::Start(offset as u64)).is_err() {
                    return Err(FdbErr::WriteErr);
                }
                match f.write_all(data) {
                    Ok(()) => {
                        if sync {
                            let _ = f.sync_all();
                        }
                        Ok(())
                    }
                    Err(_) => Err(FdbErr::WriteErr),
                }
            }
            None => Err(FdbErr::WriteErr),
        }
    }

    fn erase(&mut self, addr: u32, size: usize) -> Result<(), FdbErr> {
        let fd = self.open_db_file(addr, true);
        match fd {
            Some(mut f) => {
                let erase_buf = [FDB_BYTE_ERASED; BUF_SIZE];
                f.seek(SeekFrom::Start(0)).map_err(|_| FdbErr::EraseErr)?;
                let full_chunks = size / BUF_SIZE;
                for _ in 0..full_chunks {
                    f.write_all(&erase_buf).map_err(|_| FdbErr::EraseErr)?;
                }
                let remainder = size - full_chunks * BUF_SIZE;
                if remainder > 0 {
                    f.write_all(&erase_buf[..remainder]).map_err(|_| FdbErr::EraseErr)?;
                }
                let _ = f.sync_all();
                Ok(())
            }
            None => Err(FdbErr::EraseErr),
        }
    }
}

