use std::cell::RefCell;
use std::fs;
use std::io::{Read, Seek, SeekFrom, Write};
use std::path::PathBuf;

use crate::{StorageBackend, FdbErr, FDB_BYTE_ERASED, fdb_align_down};

const DB_PATH_MAX: usize = 256;
