    KV_STATUS_TABLE_SIZE, FDB_SECTOR_STORE_STATUS_NUM, FDB_SECTOR_DIRTY_STATUS_NUM,
};

/// Compute sector header data size at runtime.
fn sector_hdr_data_size(sec_size: u32) -> usize {
    // sector_hdr_data: store_status + dirty_status + magic + combined + reserved
    // For FDB_WRITE_GRAN=1:
    //   store: FDB_STORE_STATUS_TABLE_SIZE bytes
    //   dirty: FDB_DIRTY_STATUS_TABLE_SIZE bytes
    //   magic: 4 bytes
    //   combined: 4 bytes
    //   reserved: 4 bytes
    let raw = FDB_STORE_STATUS_TABLE_SIZE + FDB_DIRTY_STATUS_TABLE_SIZE + 4 + 4 + 4;
    wg_align(raw)
}

/// Compute KV header data size at runtime.
fn kv_hdr_data_size() -> usize {
    // kv_hdr_data: status_table + magic + len + crc32 + name_len + value_len
    let raw = KV_STATUS_TABLE_SIZE + 4 + 4 + 4 + 1 + 4;
    wg_align(raw)
}

/// Compute FDB_SEC_REMAIN_THRESHOLD = KV_HDR_DATA_SIZE + FDB_KV_NAME_MAX
fn sec_remain_threshold() -> usize {
    kv_hdr_data_size() + FDB_KV_NAME_MAX
}

// Offsets into sector header
fn sector_store_offset() -> usize { 0 }
fn sector_dirty_offset() -> usize { FDB_STORE_STATUS_TABLE_SIZE }
fn sector_magic_offset() -> usize { FDB_STORE_STATUS_TABLE_SIZE + FDB_DIRTY_STATUS_TABLE_SIZE }
fn kv_magic_offset() -> usize { KV_STATUS_TABLE_SIZE }
fn kv_len_offset() -> usize { KV_STATUS_TABLE_SIZE + 4 }
fn kv_name_len_offset() -> usize { KV_STATUS_TABLE_SIZE + 4 + 4 + 4 }

fn sector_num(max_size: u32, sec_size: u32) -> u32 {
    max_size / sec_size
}

