    /// Deinitialize.
    pub fn deinit(&mut self) -> Result<(), FdbErr> {
        self.init_ok = false;
        self.backend = None;
        Ok(())
    }

    /// Check database integrity.
    pub fn check(&mut self) -> Result<(), FdbErr> {
        if !self.init_ok {
            return Err(FdbErr::InitFailed);
        }
        self.db_lock();

        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;
        let sec_hdr_sz = sector_hdr_data_size(self.sec_size) as u32;
        let mut result = FdbErr::NoErr;

        loop {
            traversed_len += self.sec_size;
            match self.read_sector_info(sec_addr, false) {
                Ok(sector) => {
                    if sector.store_status == SectorStoreStatus::Using || sector.store_status == SectorStoreStatus::Full {
                        let mut kv = KvInfo::default();
                        kv.addr_start = sector.addr + sec_hdr_sz;
                        loop {
                            result = self.read_kv(&mut kv).err().unwrap_or(FdbErr::NoErr);
                            let next = self.get_next_kv_addr(&sector, &kv);
                            if next == FDB_FAILED_ADDR || result != FdbErr::NoErr { break; }
                            kv.addr_start = next;
                        }
                    }
                }
                Err(e) => { result = e; }
            }

            let next = {
                let mut s = KvdbSecInfo::default();
                s.addr = sec_addr;
                s.combined = SECTOR_NOT_COMBINED;
                s
            };
            let n = self.get_next_sector_addr(&next, traversed_len);
            if n == FDB_FAILED_ADDR || result != FdbErr::NoErr { break; }
            sec_addr = n;
        }

        self.db_unlock();
        if result == FdbErr::NoErr { Ok(()) } else { Err(result) }
    }

    /// Control interface.
    pub fn control(&mut self, cmd: i32, arg: *mut core::ffi::c_void) {
        match cmd {
            crate::FDB_KVDB_CTRL_SET_SEC_SIZE => {
                assert!(!self.init_ok);
                unsafe { self.sec_size = *(arg as *const u32); }
            }
            crate::FDB_KVDB_CTRL_GET_SEC_SIZE => {
                unsafe { *(arg as *mut u32) = self.sec_size; }
            }
            crate::FDB_KVDB_CTRL_SET_LOCK => {
                unsafe { self.lock_fn = Some(std::mem::transmute(arg)); }
            }
            crate::FDB_KVDB_CTRL_SET_UNLOCK => {
                unsafe { self.unlock_fn = Some(std::mem::transmute(arg)); }
            }
            crate::FDB_KVDB_CTRL_SET_FILE_MODE => {
                assert!(!self.init_ok);
                unsafe { self.file_mode = *(arg as *const bool); }
            }
            crate::FDB_KVDB_CTRL_SET_MAX_SIZE => {
                assert!(!self.init_ok);
                unsafe { self.max_size = *(arg as *const u32); }
            }
            crate::FDB_KVDB_CTRL_SET_NOT_FORMAT => {
                assert!(!self.init_ok);
                unsafe { self.not_formatable = *(arg as *const bool); }
            }
            _ => {}
        }
    }
}

