static int dir_delete(const char* path)
{
    DIR* dir = NULL;
    struct dirent* dirent = NULL;
    char* full_path;
    int res = 0;

    if (path == NULL || path[0] == '\0')
        return -ENOENT;

    full_path = (char*)malloc(PATH_MAX);
    if (full_path == NULL)
        return -ENOMEM;

    dir = opendir(path);
    if (dir == NULL)
    {
        free(full_path);
        return -ENOENT;
    }

    while (1)
    {
        dirent = readdir(dir);
        if (dirent == NULL)
            break;
        if (strcmp(".", dirent->d_name) != 0 &&
            strcmp("..", dirent->d_name) != 0)
        {
            snprintf(full_path, PATH_MAX, "%s/%s", path, dirent->d_name);
            if (dirent->d_type == DT_REG)
            {
                if (unlink(full_path) != 0)
                {
                    LOG_W("cannot remove '%s'", full_path);
                    res = -1;
                }
            }
            else if (dirent->d_type == DT_DIR)
            {
                if (dir_delete(full_path) != 0)
                {
                    res = -1;
                }
            }
        }
    }
    closedir(dir);
    free(full_path);

    if (path[strlen(path) - 1] != '/')
    {
        if (unlink(path) != 0)
        {
            LOG_W("cannot remove '%s'", path);
            res = -1;
        }
    }

    return res;
}

