}

fn update_sector_empty_addr_cache(&mut self, sec_addr: u32, empty_addr: u32) {
    if let Some(idx) = self.get_sector_from_cache(sec_addr) {
        self.sector_cache[idx].empty_kv = empty_addr;
        self.sector_cache[idx].remain = self.sec_size as usize - (empty_addr - sec_addr) as usize;
    }
}

fn update_sector_status_store_cache(&mut self, sec_addr: u32, st: SectorStoreStatus) {
    if let Some(idx) = self.get_sector_from_cache(sec_addr) {
        self.sector_cache[idx].store_status = st;
    }
}

fn update_kv_cache(&mut self, name: &str, addr: u32) {
    let name_crc = (calc_crc32(0, name.as_bytes()) >> 16) as u16;
    let name_len = name.len();

    if addr != FDB_DATA_UNUSED {
        // Update existing
        for i in 0..self.kv_cache.len() {
            if self.kv_cache[i].name_crc == name_crc {
                self.kv_cache[i].addr = addr;
                return;
            }
        }
        // Find empty slot
        let mut empty_index = self.kv_cache.len();
        let mut min_activity_index = self.kv_cache.len();
        let mut min_activity: u16 = 0xFFFF;

        for i in 0..self.kv_cache.len() {
            if self.kv_cache[i].addr == FDB_DATA_UNUSED && empty_index == self.kv_cache.len() {
                empty_index = i;
            } else if self.kv_cache[i].addr != FDB_DATA_UNUSED {
                if self.kv_cache[i].active > 0 {
                    self.kv_cache[i].active -= 1;
                }
                if self.kv_cache[i].active < min_activity {
                    min_activity_index = i;
                    min_activity = self.kv_cache[i].active;
                }
            }
        }

        if empty_index < self.kv_cache.len() {
            self.kv_cache[empty_index].addr = addr;
            self.kv_cache[empty_index].name_crc = name_crc;
            self.kv_cache[empty_index].active = self.kv_cache.len() as u16;
        } else if min_activity_index < self.kv_cache.len() {
            self.kv_cache[min_activity_index].addr = addr;
            self.kv_cache[min_activity_index].name_crc = name_crc;
            self.kv_cache[min_activity_index].active = self.kv_cache.len() as u16;
        }
    } else {
        // Delete
        for i in 0..self.kv_cache.len() {
            if self.kv_cache[i].name_crc == name_crc {
                self.kv_cache[i].addr = FDB_DATA_UNUSED;
                self.kv_cache[i].active = 0;
                return;
            }
        }
    }
}

fn get_kv_from_cache(&mut self, name: &str) -> Option<u32> {
    let name_crc = (calc_crc32(0, name.as_bytes()) >> 16) as u16;
    let name_len = name.len();

    for i in 0..self.kv_cache.len() {
        if self.kv_cache[i].addr != FDB_DATA_UNUSED && self.kv_cache[i].name_crc == name_crc {
            // Read the KV name from flash to verify
            let mut saved_name = vec![0u8; FDB_KV_NAME_MAX];
            let kv_hdr_sz = kv_hdr_data_size();
            if self.be().read(self.kv_cache[i].addr + kv_hdr_sz as u32, &mut saved_name).is_ok() {
                if name.as_bytes() == &saved_name[..name_len] {
                    let addr = self.kv_cache[i].addr;
                    let active = self.kv_cache[i].active;
                    self.kv_cache[i].active = if active >= 0xFFFF - self.kv_cache.len() as u16 {
                        0xFFFF
                    } else {
                        active + self.kv_cache.len() as u16
                    };
                    return Some(addr);
                }
            }
        }
    }
    None
}

