    self.be().read(addr, &mut sec_hdr_buf)?;

    let mut sector = KvdbSecInfo::default();
    sector.addr = addr;

    // Parse sector header
    let store_status = status::get_status(
        &sec_hdr_buf[sector_store_offset()..sector_store_offset() + FDB_STORE_STATUS_TABLE_SIZE],
        FDB_SECTOR_STORE_STATUS_NUM,
    );
    sector.store_status = match store_status {
        0 => SectorStoreStatus::Unused,
        1 => SectorStoreStatus::Empty,
        2 => SectorStoreStatus::Using,
        3 => SectorStoreStatus::Full,
        _ => SectorStoreStatus::Unused,
    };

    let dirty_status = status::get_status(
        &sec_hdr_buf[sector_dirty_offset()..sector_dirty_offset() + FDB_DIRTY_STATUS_TABLE_SIZE],
        FDB_SECTOR_DIRTY_STATUS_NUM,
    );
    sector.dirty_status = match dirty_status {
        0 => SectorDirtyStatus::Unused,
        1 => SectorDirtyStatus::False,
        2 => SectorDirtyStatus::True,
        3 => SectorDirtyStatus::Gc,
        _ => SectorDirtyStatus::Unused,
    };

    let magic_off = sector_magic_offset();
    sector.magic = u32::from_le_bytes(sec_hdr_buf[magic_off..magic_off + 4].try_into().unwrap());

    if sector.magic != KVDB_SECTOR_MAGIC_WORD {
        sector.check_ok = false;
        sector.combined = SECTOR_NOT_COMBINED;
        return Err(FdbErr::InitFailed);
    }

    sector.check_ok = true;
    let combined_off = magic_off + 4;
    sector.combined = u32::from_le_bytes(sec_hdr_buf[combined_off..combined_off + 4].try_into().unwrap());

    if sector.combined != SECTOR_NOT_COMBINED && sector.combined != SECTOR_COMBINED {
