/// Get next sector address.
fn get_next_sector_addr(&self, pre_sec: &KvdbSecInfo, traversed_len: u32) -> u32 {
    let cur_block_size = if pre_sec.combined == SECTOR_NOT_COMBINED {
        self.sec_size
    } else {
        pre_sec.combined * self.sec_size
    };

    if traversed_len + cur_block_size <= self.max_size {
        if pre_sec.addr + cur_block_size < self.max_size {
            pre_sec.addr + cur_block_size
        } else {
            0
        }
    } else {
        FDB_FAILED_ADDR
    }
}

/// Format a sector.
fn format_sector(&mut self, addr: u32, combined_value: u32) -> Result<(), FdbErr> {
    assert_eq!(addr % self.sec_size, 0);

    self.be().erase(addr, self.sec_size as usize)?;

    let sec_hdr_sz = sector_hdr_data_size(self.sec_size);
    let mut sec_hdr_buf = vec![FDB_BYTE_ERASED; sec_hdr_sz];

    // For FDB_WRITE_GRAN=1, build the header in memory then write it all at once
    status::set_status(
        &mut sec_hdr_buf[sector_store_offset()..sector_store_offset() + FDB_STORE_STATUS_TABLE_SIZE],
        FDB_SECTOR_STORE_STATUS_NUM,
        SectorStoreStatus::Empty as usize,
    );
    status::set_status(
        &mut sec_hdr_buf[sector_dirty_offset()..sector_dirty_offset() + FDB_DIRTY_STATUS_TABLE_SIZE],
        FDB_SECTOR_DIRTY_STATUS_NUM,
        SectorDirtyStatus::False as usize,
    );

    let magic_off = sector_magic_offset();
    sec_hdr_buf[magic_off..magic_off + 4].copy_from_slice(&KVDB_SECTOR_MAGIC_WORD.to_le_bytes());
    sec_hdr_buf[magic_off + 4..magic_off + 8].copy_from_slice(&combined_value.to_le_bytes());
    sec_hdr_buf[magic_off + 8..magic_off + 12].copy_from_slice(&FDB_DATA_UNUSED.to_le_bytes());

    self.be().write(addr, &sec_hdr_buf, true)?;

    // Invalidate cache
    let mut sector = KvdbSecInfo::default();
    sector.addr = addr;
    sector.check_ok = false;
    sector.empty_kv = FDB_FAILED_ADDR;
    self.update_sector_cache(&sector);

    Ok(())
}

/// Update sector status.
fn update_sec_status(&mut self, sector: &mut KvdbSecInfo, new_kv_len: usize) -> Result<bool, FdbErr> {
    let mut is_full = false;
    let threshold = sec_remain_threshold();

    if sector.store_status == SectorStoreStatus::Empty {
        let mut st = vec![0u8; FDB_STORE_STATUS_TABLE_SIZE];
        status::write_status(self.be(), sector.addr, &mut st, FDB_SECTOR_STORE_STATUS_NUM, SectorStoreStatus::Using as usize, true)?;
        self.update_sector_status_store_cache(sector.addr, SectorStoreStatus::Using);
        sector.store_status = SectorStoreStatus::Using;
    } else if sector.store_status == SectorStoreStatus::Using {
        if sector.remain < threshold || sector.remain - new_kv_len < threshold {
            let mut st = vec![0u8; FDB_STORE_STATUS_TABLE_SIZE];
            status::write_status(self.be(), sector.addr, &mut st, FDB_SECTOR_STORE_STATUS_NUM, SectorStoreStatus::Full as usize, true)?;
            self.update_sector_status_store_cache(sector.addr, SectorStoreStatus::Full);
            sector.store_status = SectorStoreStatus::Full;
            is_full = true;
        }
    }

    Ok(is_full)
}

/// Find a KV by key.
fn find_kv(&mut self, key: &str) -> Option<KvInfo> {
    // Try cache first
    if let Some(addr) = self.get_kv_from_cache(key) {
        let mut kv = KvInfo::default();
        kv.addr_start = addr;
        if self.read_kv(&mut kv).is_ok() && kv.crc_is_ok {
            return Some(kv);
        }
    }

    // Linear scan
    let result = self.find_kv_no_cache(key);
    if let Some(ref kv) = result {
        self.update_kv_cache(key, kv.addr_start);
    }
    result
}

fn find_kv_no_cache(&mut self, key: &str) -> Option<KvInfo> {
    let mut kv = KvInfo::default();
    let mut found = false;
    self.kv_iterator(&mut kv, key, &mut found, Self::find_kv_cb);
    if found { Some(kv) } else { None }
}

fn find_kv_cb(kv: &KvInfo, key: &str, found: &mut bool) -> bool {
    let key_len = key.len();
    if kv.name_len as usize != key_len {
        return false;
    }
    if kv.crc_is_ok && kv.status == KvStatus::Write && &kv.name[..key_len] == key.as_bytes() {
        *found = true;
        return true;
    }
    false
}

