/// Create a KV blob.
fn create_kv_blob(&mut self, sector: &mut KvdbSecInfo, key: &str, value: &[u8]) -> Result<(), FdbErr> {
    let kv_hdr_sz = kv_hdr_data_size();
    let key_len = key.len();
    let value_len = value.len();

    if key_len > FDB_KV_NAME_MAX {
        return Err(FdbErr::KvNameErr);
    }

    let total_len = kv_hdr_sz + wg_align(key_len) + wg_align(value_len);
    if total_len > self.sec_size as usize - sector_hdr_data_size(self.sec_size) {
        return Err(FdbErr::SavedFull);
    }

    let kv_addr = if sector.empty_kv != FDB_FAILED_ADDR {
        sector.empty_kv
    } else {
        let (addr, _) = self.alloc_kv(total_len);
        if addr == FDB_FAILED_ADDR {
            // Try GC
            if self.gc_request {
                self.gc_collect_by_free_size(total_len);
                let (addr2, _) = self.alloc_kv(total_len);
                if addr2 == FDB_FAILED_ADDR {
                    return Err(FdbErr::SavedFull);
                }
                addr2
            } else {
                return Err(FdbErr::SavedFull);
            }
        } else {
            addr
        }
    };

    let is_full = self.update_sec_status(sector, total_len)?;

    // Build KV header
    let mut kv_hdr_buf = vec![FDB_BYTE_ERASED; kv_hdr_sz];
    // Status table: pre-write
    status::set_status(
        &mut kv_hdr_buf[..KV_STATUS_TABLE_SIZE],
        FDB_KV_STATUS_NUM,
        KvStatus::PreWrite as usize,
    );
    // Magic
    kv_hdr_buf[kv_magic_offset()..kv_magic_offset() + 4].copy_from_slice(&KV_MAGIC_WORD.to_le_bytes());
    // Len
    kv_hdr_buf[kv_len_offset()..kv_len_offset() + 4].copy_from_slice(&(total_len as u32).to_le_bytes());
    // Name_len
    kv_hdr_buf[kv_name_len_offset()] = key_len as u8;
    // Value_len
    kv_hdr_buf[kv_name_len_offset() + 1..kv_name_len_offset() + 5].copy_from_slice(&(value_len as u32).to_le_bytes());

    // Calculate CRC32
    let mut crc: u32 = 0;
    let name_len_bytes = (key_len as u32).to_le_bytes();
    crc = calc_crc32(crc, &name_len_bytes);
    let value_len_bytes = (value_len as u32).to_le_bytes();
    crc = calc_crc32(crc, &value_len_bytes);
    crc = calc_crc32(crc, key.as_bytes());
    // Pad name alignment
    let name_pad = wg_align(key_len) - key_len;
    for _ in 0..name_pad {
        crc = calc_crc32(crc, &[FDB_BYTE_ERASED]);
    }
    crc = calc_crc32(crc, value);
    let value_pad = wg_align(value_len) - value_len;
    for _ in 0..value_pad {
        crc = calc_crc32(crc, &[FDB_BYTE_ERASED]);
    }

    // CRC32 stored at offset kv_name_len_offset - 4
    let crc_off = kv_name_len_offset() - 4;
    kv_hdr_buf[crc_off..crc_off + 4].copy_from_slice(&crc.to_le_bytes());

    // Write header (first status, then rest)
    status::write_status(self.be(), kv_addr, &mut kv_hdr_buf[..KV_STATUS_TABLE_SIZE].to_vec(), FDB_KV_STATUS_NUM, KvStatus::PreWrite as usize, false)?;
    self.be().write(kv_addr + kv_magic_offset() as u32, &kv_hdr_buf[kv_magic_offset()..], false)?;

    // Write key name
    status::write_align(self.be(), kv_addr + kv_hdr_sz as u32, key.as_bytes())?;

    // Update cache
    if !is_full {
        self.update_sector_empty_addr_cache(
            sector.addr,
            kv_addr + kv_hdr_sz as u32 + wg_align(key_len) as u32 + wg_align(value_len) as u32,
        );
    }
    self.update_kv_cache(key, kv_addr);

    // Write value
    status::write_align(self.be(), kv_addr + kv_hdr_sz as u32 + wg_align(key_len) as u32, value)?;

    // Set status to WRITE
    let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
    status::write_status(self.be(), kv_addr, &mut st, FDB_KV_STATUS_NUM, KvStatus::Write as usize, true)?;

    if is_full {
        self.gc_request = true;
    }

    Ok(())
}

/// Set a KV value.
fn set_kv(&mut self, key: &str, value: &[u8]) -> Result<(), FdbErr> {
    if value.is_empty() {
        // Delete
        return self.del_kv(Some(key), &KvInfo::default(), true);
    }

    let kv_len = kv_hdr_data_size() + wg_align(key.len()) + wg_align(value.len());
    let (empty_addr, _) = self.alloc_kv(kv_len);
    if empty_addr == FDB_FAILED_ADDR {
        if self.gc_request {
            self.gc_collect_by_free_size(kv_len);
            let (empty_addr2, _) = self.alloc_kv(kv_len);
            if empty_addr2 == FDB_FAILED_ADDR {
                return Err(FdbErr::SavedFull);
            }
        } else {
            return Err(FdbErr::SavedFull);
        }
    }

    let kv_is_found = self.find_kv(key);
    if let Some(ref old_kv) = kv_is_found {
        self.del_kv(Some(key), old_kv, false)?;
    }

    let mut sector = KvdbSecInfo::default();
    sector.empty_kv = FDB_FAILED_ADDR;
    let result = self.create_kv_blob(&mut sector, key, value);

    if let Some(ref old_kv) = kv_is_found {
        if result.is_ok() {
            let _ = self.del_kv(Some(key), old_kv, true);
        }
    }

    if self.gc_request {
        self.gc_collect_by_free_size(kv_hdr_data_size() + wg_align(key.len()) + wg_align(value.len()));
    }

    result
}

/// Get a KV value.
fn get_kv(&mut self, key: &str, value_buf: &mut [u8]) -> (usize, usize) {
    if let Some(kv) = self.find_kv(key) {
        let value_len = kv.value_len as usize;
        let read_len = value_buf.len().min(value_len);
        if self.be().read(kv.addr_value, &mut value_buf[..read_len]).is_err() {
            return (0, value_len);
        }
        (read_len, value_len)
    } else {
        (0, 0)
    }
}

