fn kv_load(&mut self) -> Result<(), FdbErr> {
    self.in_recovery_check = true;

    // Check all sector headers
    let mut check_failed_count = 0usize;
    let sec_num = self.max_size / self.sec_size;

    let mut sec_addr = 0u32;
    let mut traversed_len = 0u32;
    loop {
        traversed_len += self.sec_size;
        match self.read_sector_info(sec_addr, false) {
            Ok(sector) => {
                if !sector.check_ok {
                    check_failed_count += 1;
                    if !self.not_formatable {
                        self.format_sector(sector.addr, SECTOR_NOT_COMBINED)?;
                    }
                }
            }
            Err(_) => {
                check_failed_count += 1;
                if !self.not_formatable {
                    self.format_sector(sec_addr, SECTOR_NOT_COMBINED)?;
                }
            }
        }
        let next = {
            let mut s = KvdbSecInfo::default();
            s.addr = sec_addr;
            s.combined = SECTOR_NOT_COMBINED;
            s
        };
        let n = self.get_next_sector_addr(&next, traversed_len);
        if n == FDB_FAILED_ADDR { break; }
        sec_addr = n;
    }

    if self.not_formatable && check_failed_count > 0 {
        return Err(FdbErr::ReadErr);
    }

    if check_failed_count == sec_num as usize {
        self.set_default()?;
    }

    // Recovery GC
    sec_addr = 0;
    traversed_len = 0;
    loop {
        traversed_len += self.sec_size;
        if let Ok(sector) = self.read_sector_info(sec_addr, false) {
            if sector.check_ok && sector.dirty_status == SectorDirtyStatus::Gc {
                self.gc_request = true;
                self.gc_collect();
            }
        }
        let next = {
            let mut s = KvdbSecInfo::default();
            s.addr = sec_addr;
            s.combined = SECTOR_NOT_COMBINED;
            s
        };
        let n = self.get_next_sector_addr(&next, traversed_len);
        if n == FDB_FAILED_ADDR { break; }
        sec_addr = n;
    }

    // Recovery KVs
    loop {
        let mut kv = KvInfo::default();
        let mut need_gc = false;
        let mut sec_addr = self.oldest_addr;
        let mut traversed_len = 0u32;
        let sec_hdr_sz = sector_hdr_data_size(self.sec_size) as u32;

        loop {
            traversed_len += self.sec_size;
            let sector = match self.read_sector_info(sec_addr, false) {
                Ok(s) => s,
                Err(_) => {
                    let next = {
                        let mut s = KvdbSecInfo::default();
                        s.addr = sec_addr;
                        s.combined = SECTOR_NOT_COMBINED;
                        s
                    };
                    let n = self.get_next_sector_addr(&next, traversed_len);
                    if n == FDB_FAILED_ADDR { break; }
                    sec_addr = n;
                    continue;
                }
            };

            if sector.store_status == SectorStoreStatus::Using || sector.store_status == SectorStoreStatus::Full {
                kv.addr_start = sector.addr + sec_hdr_sz;
                loop {
                    let _ = self.read_kv(&mut kv);
                    if kv.crc_is_ok && kv.status == KvStatus::PreDelete {
                        if self.move_kv(&kv).is_err() {
                            need_gc = true;
                            break;
                        }
                    } else if kv.status == KvStatus::PreWrite {
                        let mut st = vec![0u8; KV_STATUS_TABLE_SIZE];
                        let _ = status::write_status(self.be(), kv.addr_start, &mut st, FDB_KV_STATUS_NUM, KvStatus::ErrHdr as usize, true);
                        break;
                    } else if kv.crc_is_ok && kv.status == KvStatus::Write {
                        let name = std::str::from_utf8(&kv.name[..kv.name_len as usize]).unwrap_or("");
                        self.update_kv_cache(name, kv.addr_start);
                    }
                    let next = self.get_next_kv_addr(&sector, &kv);
                    if next == FDB_FAILED_ADDR { break; }
                    kv.addr_start = next;
                }
            }

            let next = {
                let mut s = KvdbSecInfo::default();
                s.addr = sec_addr;
                s.combined = sector.combined;
                s
            };
            let n = self.get_next_sector_addr(&next, traversed_len);
            if n == FDB_FAILED_ADDR { break; }
            sec_addr = n;
        }

        if self.gc_request {
            self.gc_collect();
        } else {
            break;
        }
    }

    self.in_recovery_check = false;
    Ok(())
}

fn gc_collect(&mut self) {
    self.gc_collect_by_free_size(self.max_size as usize);
}

/// Set a string KV.
pub fn kv_set(&mut self, key: &str, value: &str) -> Result<(), FdbErr> {
    if !self.init_ok {
        return Err(FdbErr::InitFailed);
    }
    self.db_lock();
    let result = self.set_kv(key, value.as_bytes());
    self.db_unlock();
    result
}

/// Get a string KV.
