#![allow(warnings)]

mod crc;
mod status;
mod file_backend;
mod kvdb;
mod tsdb;
mod ffi;

// Re-export public types for tests
pub use crc::calc_crc32;
pub use kvdb::Kvdb;
pub use tsdb::Tsdb;
pub use file_backend::FileBackend;

/// Software version, must match C.
pub const FDB_SW_VERSION: &str = "2.2.99";
pub const FDB_SW_VERSION_NUM: u32 = 0x20299;

/// Write granularity in bits — fixed at 1 for this profile.
pub const FDB_WRITE_GRAN: usize = 1;

/// KV max name length.
pub const FDB_KV_NAME_MAX: usize = 64;

/// KV cache table size.
pub const FDB_KV_CACHE_TABLE_SIZE: usize = 64;

/// Sector cache table size.
pub const FDB_SECTOR_CACHE_TABLE_SIZE: usize = 8;

/// File cache table size.
pub const FDB_FILE_CACHE_TABLE_SIZE: usize = 2;

/// Erased byte value.
pub const FDB_BYTE_ERASED: u8 = 0xFF;

/// Written byte value.
pub const FDB_BYTE_WRITTEN: u8 = 0x00;

/// Data unused marker (when FDB_BYTE_ERASED == 0xFF).
pub const FDB_DATA_UNUSED: u32 = 0xFFFFFFFF;

/// Failed / invalid address.
pub const FDB_FAILED_ADDR: u32 = 0xFFFFFFFF;

/// String KV value max size for the legacy `fdb_kv_get` function.
pub const FDB_STR_KV_VALUE_MAX_SIZE: usize = 128;

/// GC minimum number of empty sectors.
pub const GC_MIN_EMPTY_SEC_NUM: usize = 1;

/// Sector remain threshold before full status.
pub const FDB_SEC_REMAIN_THRESHOLD_FACTOR: usize = 0; // computed at runtime

/// GC empty sector threshold.
pub const FDB_GC_EMPTY_SEC_THRESHOLD: usize = 1;

/// Sector magic word (`F`, `D`, `B`, `1`) = 0x30424446
pub const KVDB_SECTOR_MAGIC_WORD: u32 = 0x30424446;

/// KV magic word (`K`, `V`, `0`, `0`) = 0x3030564B
pub const KV_MAGIC_WORD: u32 = 0x3030564B;

/// TSDB sector magic word (`T`, `S`, `L`, `0`) = 0x304C5354
pub const TSDB_SECTOR_MAGIC_WORD: u32 = 0x304C5354;

/// Sector not combined value (when FDB_BYTE_ERASED == 0xFF).
pub const SECTOR_NOT_COMBINED: u32 = 0xFFFFFFFF;
pub const SECTOR_COMBINED: u32 = 0x00000000;

/// Align `size` up to `align` (align must be a power of 2).
#[inline]
pub const fn fdb_align(size: usize, align: usize) -> usize {
    ((size + align - 1) / align) * align
}

