display.text:
//! Status table read/write utilities.
//! Faithful translation of _fdb_set_status, _fdb_get_status, etc.

use crate::{
    FDB_WRITE_GRAN, FDB_BYTE_ERASED, FDB_BYTE_WRITTEN, status_table_size,
    StorageBackend, FdbErr, wg_align,
};

/// Set the status in a status table buffer.
/// Returns the byte index that was modified (or usize::MAX if no write needed).
/// Identical semantics to C `_fdb_set_status`.
pub fn set_status(status_table: &mut [u8], status_num: usize, status_index: usize) -> usize {
    // Fill the table with erased value
    let table_size = status_table_size(status_num);
    for b in status_table.iter_mut().take(table_size) {
        *b = FDB_BYTE_ERASED;
    }

    if status_index == 0 {
        return usize::MAX;
    }

    if FDB_WRITE_GRAN == 1 {
        let byte_index = (status_index - 1) / 8;
        if FDB_BYTE_ERASED == 0xFF {
            status_table[byte_index] &= (0x00ff_u32 >> (status_index % 8)) as u8;
        } else {
            status_table[byte_index] |= (0x00ff_u32 >> (status_index % 8)) as u8;
        }
        byte_index
    } else {
        let byte_index = (status_index - 1) * (FDB_WRITE_GRAN / 8);
        status_table[byte_index] = FDB_BYTE_WRITTEN;
        byte_index
    }
}

/// Get the current status index from a status table buffer.
/// Identical semantics to C `_fdb_get_status`.
pub fn get_status(status_table: &[u8], status_num: usize) -> usize {
    let mut i = 0usize;
    let mut status_num_bak = status_num;
    let sn = status_num - 1;
    status_num_bak = sn + 1;

    let mut count = sn;
    loop {
        if count == 0 {
            break;
        }
        if FDB_WRITE_GRAN == 1 {
            if (status_table[count / 8] & (0x80 >> (count % 8)) as u8) == 0x00 {
                break;
            }
        } else {
            if status_table[count * FDB_WRITE_GRAN / 8] == FDB_BYTE_WRITTEN {
                break;
            }
        }
        i += 1;
        if count == 0 { break; }
        count -= 1;
    }

    status_num_bak - i
}

/// Write a status to flash via the backend.
/// Identical semantics to C `_fdb_write_status`.
pub fn write_status(
    backend: &dyn StorageBackend,
    addr: u32,
    status_table: &mut [u8],
    status_num: usize,
    status_index: usize,
    sync: bool,
) -> Result<(), FdbErr> {
    assert!(status_index < status_num);

    let byte_index = set_status(status_table, status_num, status_index);

    if byte_index == usize::MAX {
        return Ok(());
    }

    if FDB_WRITE_GRAN == 1 {
        backend.write(addr + byte_index as u32, &status_table[byte_index..byte_index + 1], sync)
    } else {
        let gran_bytes = FDB_WRITE_GRAN / 8;
        backend.write(addr + byte_index as u32, &status_table[byte_index..byte_index + gran_bytes], sync)
    }
}

/// Read a status from flash via the backend.
/// Returns the status index.
/// Identical semantics to C `_fdb_read_status`.
pub fn read_status(
    backend: &dyn StorageBackend,
    addr: u32,
    status_table: &mut [u8],
    total_num: usize,
) -> usize {
    let table_size = status_table_size(total_num);
    if backend.read(addr, &mut status_table[..table_size]).is_err() {
        // If read fails, treat as all-erased
        for b in status_table.iter_mut().take(table_size) {
            *b = FDB_BYTE_ERASED;
        }
    }
    get_status(status_table, total_num)
}

/// Find the continue 0xFF flash address.
/// Identical semantics to C `_fdb_continue_ff_addr`.
pub fn continue_ff_addr(
    backend: &dyn StorageBackend,
    start: u32,
    end: u32,
    sec_size: u32,
) -> u32 {
    let mut buf = [0u8; 32];
    let mut last_data = FDB_BYTE_WRITTEN;
    let mut addr = start;
    let mut cur = start;

    while cur < end {
        let read_size = if cur + 32 < end { 32 } else { (end - cur) as usize };
        if backend.read(cur, &mut buf[..read_size]).is_err() {
            break;
        }
        for i in 0..read_size {
            if last_data != FDB_BYTE_ERASED && buf[i] == FDB_BYTE_ERASED {
                addr = cur + i as u32;
            }
            last_data = buf[i];
        }
        cur += 32;
    }

    if last_data == FDB_BYTE_ERASED {
        wg_align(addr as usize) as u32
    } else {
        end
    }
}

/// Write data aligned to write granularity.
/// Identical semantics to C `_fdb_flash_write_align`.
pub fn write_align(
    backend: &dyn StorageBackend,
    addr: u32,
    data: &[u8],
) -> Result<(), FdbErr> {
    let aligned_down = crate::wg_align_down(data.len());
    if aligned_down > 0 {
        backend.write(addr, &data[..aligned_down], false)?;
    }

    let remain = data.len() - aligned_down;
    if remain > 0 {
        let unit = crate::wg_unit();
        let mut align_data = vec![FDB_BYTE_ERASED; unit];
        align_data[..remain].copy_from_slice(&data[aligned_down..aligned_down + remain]);
        backend.write(addr + aligned_down as u32, &align_data, false)?;
    }

    Ok(())
}

