            let _ = f.sync_all();
        }
        let len = cache.len();
        for i in (1..len).rev() {
            cache[i] = std::mem::take(&mut cache[i - 1]);
        }
        cache[0].sec_addr = sec_addr;
        cache[0].fd = fd;
    }
}
