    }
}

#[no_mangle]
pub extern "C" fn fdb_tsl_query_count(
    db: FdbTsdbT,
    from: FdbTime,
    to: FdbTime,
    status: u32,
) -> usize {
    if db.is_null() {
        return 0;
    }
    let tsl_status = match status {
        0 => TslStatus::Unused,
        1 => TslStatus::PreWrite,
        2 => TslStatus::Write,
        3 => TslStatus::UserStatus1,
        4 => TslStatus::Deleted,
        5 => TslStatus::UserStatus2,
        _ => TslStatus::Unused,
    };
    let db_ref = unsafe { &mut *db };
    db_ref.tsl_query_count(from, to, tsl_status)
}

#[no_mangle]
pub extern "C" fn fdb_tsl_clean(db: FdbTsdbT) {
    if db.is_null() {
        return;
    }
