#[inline]
pub const fn fdb_align_down(size: usize, align: usize) -> usize {
    (size / align) * align
}

/// Write-granularity alignment unit in bytes.
#[inline]
pub const fn wg_unit() -> usize {
    (FDB_WRITE_GRAN + 7) / 8
}

/// Align by write granularity.
#[inline]
pub const fn wg_align(size: usize) -> usize {
    fdb_align(size, wg_unit())
}

