/// Status table size in bytes.
/// For FDB_WRITE_GRAN == 1: (status_number * 1 + 7) / 8
/// For other: ((status_number - 1) * gran + 7) / 8
#[inline]
pub const fn status_table_size(status_number: usize) -> usize {
    if FDB_WRITE_GRAN == 1 {
        (status_number * FDB_WRITE_GRAN + 7) / 8
    } else {
        ((status_number - 1) * FDB_WRITE_GRAN + 7) / 8
    }
}

