static int dir_delete_simple(const char *path) {
    DIR *dir = opendir(path);
    if (!dir) return -1;
    struct dirent *d;
    char full[1024];
    while ((d = readdir(dir))) {
        if (strcmp(d->d_name, ".") == 0 || strcmp(d->d_name, "..") == 0)
            continue;
        snprintf(full, sizeof(full), "%s/%s", path, d->d_name);
        if (d->d_type == DT_DIR) {
            dir_delete_simple(full);
        } else {
            unlink(full);
        }
    }
    closedir(dir);
    rmdir(path);
    return 0;
}

