pub struct Blob {
    pub buf: Vec<u8>,
    pub size: usize,
    pub saved_meta_addr: u32,
    pub saved_addr: u32,
    pub saved_len: usize,
}

impl Blob {
    pub fn new(value_buf: &[u8]) -> Self {
        Blob {
            buf: value_buf.to_vec(),
            size: value_buf.len(),
            saved_meta_addr: 0,
            saved_addr: 0,
            saved_len: 0,
        }
    }

    pub fn make(&mut self, value_buf: &[u8], buf_len: usize) -> &mut Self {
        self.buf = value_buf.to_vec();
        self.size = buf_len;
        self
    }

    pub fn read_from_storage(
        &mut self,
        backend: &mut dyn StorageBackend,
        addr: u32,
        len: usize,
    ) -> usize {
        let read_len = self.size.min(len);
        if read_len == 0 {
            return 0;
        }
        let mut tmp = vec![0u8; read_len];
        match backend.read(addr, &mut tmp) {
            Ok(()) => {
                let copy_len = read_len.min(self.buf.len());
                self.buf[..copy_len].copy_from_slice(&tmp[..copy_len]);
                read_len
            }
            Err(_) => 0,
        }
    }
}

// ---- KV Info (in-memory) ----

