//! FFI — C-compatible exports for the flashdb_rust static library.
//!
//! Provides C ABI functions matching the FlashDB public API in flashdb.h.
//! Uses opaque pointer pattern: C allocates the struct on stack, we store
//! the Rust Box in a global registry keyed by the struct's address.

use std::collections::HashMap;
use std::ffi::{CStr, CString};
use std::os::raw::c_char;
use std::ptr;
use std::sync::Mutex;

use crate::{FdbErr, FdbTime, KvInfo, Kvdb, Tsdb, TslInfo, TslStatus};

// ---- C-compatible repr(C) structs ----

/// C `struct fdb_blob` — matches fdb_def.h layout exactly.
#[repr(C)]
#[derive(Debug, Clone)]
pub struct CFlashdbBlob {
    pub buf: *mut core::ffi::c_void,
    pub size: usize,
    pub saved_meta_addr: u32,
    pub saved_addr: u32,
    pub saved_len: usize,
}

/// C `fdb_kv_status_t` enum — matches fdb_def.h.
pub const FDB_KV_UNUSED: u32 = 0;
pub const FDB_KV_PRE_WRITE: u32 = 1;
pub const FDB_KV_WRITE: u32 = 2;
pub const FDB_KV_PRE_DELETE: u32 = 3;
pub const FDB_KV_DELETED: u32 = 4;
pub const FDB_KV_ERR_HDR: u32 = 5;

/// C `fdb_tsl_status_t` enum values.
pub const FDB_TSL_UNUSED: u32 = 0;
pub const FDB_TSL_PRE_WRITE: u32 = 1;
pub const FDB_TSL_WRITE: u32 = 2;
pub const FDB_TSL_USER_STATUS1: u32 = 3;
pub const FDB_TSL_DELETED: u32 = 4;
pub const FDB_TSL_USER_STATUS2: u32 = 5;

/// C `struct fdb_kv` — matches fdb_def.h layout exactly.
#[repr(C)]
#[derive(Debug, Clone)]
pub struct CFlashdbKv {
    pub status: u32,
    pub crc_is_ok: bool,
    pub name_len: u8,
    pub _pad: [u8; 3],
    pub magic: u32,
    pub len: u32,
    pub value_len: u32,
    pub name: [u8; crate::FDB_KV_NAME_MAX],
    pub addr_start: u32,
    pub addr_value: u32,
}

impl Default for CFlashdbKv {
    fn default() -> Self {
        CFlashdbKv {
            status: FDB_KV_UNUSED,
            crc_is_ok: false,
            name_len: 0,
            _pad: [0; 3],
            magic: 0,
            len: 0,
            value_len: 0,
            name: [0u8; crate::FDB_KV_NAME_MAX],
            addr_start: crate::FDB_FAILED_ADDR,
            addr_value: 0,
        }
    }
}

impl From<&KvInfo> for CFlashdbKv {
    fn from(kv: &KvInfo) -> Self {
        let mut name = [0u8; crate::FDB_KV_NAME_MAX];
        let copy_len = kv.name_len as usize;
        if copy_len > 0 && copy_len <= name.len() {
            name[..copy_len].copy_from_slice(&kv.name[..copy_len]);
        }
        CFlashdbKv {
            status: kv.status as u32,
            crc_is_ok: kv.crc_is_ok,
            name_len: kv.name_len,
            _pad: [0; 3],
            magic: kv.magic,
            len: kv.len,
            value_len: kv.value_len,
            name,
            addr_start: kv.addr_start,
            addr_value: kv.addr_value,
        }
    }
}

/// C `struct fdb_kv_iterator` — matches fdb_def.h layout.
#[repr(C)]
#[derive(Debug)]
pub struct CFlashdbKvIterator {
    pub curr_kv: CFlashdbKv,
    pub iterated_cnt: u32,
    pub iterated_obj_bytes: usize,
    pub iterated_value_bytes: usize,
    pub sector_addr: u32,
    pub traversed_len: u32,
}

impl Default for CFlashdbKvIterator {
    fn default() -> Self {
        CFlashdbKvIterator {
            curr_kv: CFlashdbKv::default(),
            iterated_cnt: 0,
            iterated_obj_bytes: 0,
            iterated_value_bytes: 0,
            sector_addr: 0,
            traversed_len: 0,
        }
    }
}

/// C `struct fdb_tsl` — matches fdb_def.h layout.
#[repr(C)]
#[derive(Debug, Clone)]
pub struct CFlashdbTsl {
    pub status: u32,
    pub time: FdbTime,
    pub log_len: u32,
    pub addr_index: u32,
    pub addr_log: u32,
}

impl Default for CFlashdbTsl {
    fn default() -> Self {
        CFlashdbTsl {
            status: FDB_TSL_UNUSED,
            time: 0,
            log_len: 0,
            addr_index: crate::FDB_FAILED_ADDR,
            addr_log: 0,
        }
    }
}

impl From<&TslInfo> for CFlashdbTsl {
    fn from(tsl: &TslInfo) -> Self {
        CFlashdbTsl {
            status: tsl.status as u32,
            time: tsl.time,
            log_len: tsl.log_len,
            addr_index: tsl.addr_index,
            addr_log: tsl.addr_log,
        }
    }
}

// ---- Global registries for Rust objects ----

struct KvdbEntry {
    db: Box<Kvdb>,
    sec_size: u32,
    max_size: u32,
    file_mode: bool,
    not_formatable: bool,
}

struct TsdbEntry {
    db: Box<Tsdb>,
    sec_size: u32,
    max_size: u32,
    file_mode: bool,
    not_formatable: bool,
}

lazy_static::lazy_static! {
    static ref KVDB_REGISTRY: Mutex<HashMap<usize, KvdbEntry>> = Mutex::new(HashMap::new());
    static ref TSDB_REGISTRY: Mutex<HashMap<usize, TsdbEntry>> = Mutex::new(HashMap::new());
}

fn err_to_c(e: FdbErr) -> i32 {
    e as i32
}

// ---- Blob API ----

/// C `fdb_blob_make` — initializes a blob struct.
#[no_mangle]
pub extern "C" fn fdb_blob_make(
    blob: *mut CFlashdbBlob,
    value_buf: *const core::ffi::c_void,
    buf_len: usize,
) -> *mut CFlashdbBlob {
    if blob.is_null() {
        return ptr::null_mut();
    }
    unsafe {
        (*blob).buf = value_buf as *mut core::ffi::c_void;
        (*blob).size = buf_len;
        (*blob).saved_meta_addr = 0;
        (*blob).saved_addr = 0;
        (*blob).saved_len = 0;
    }
    blob
}

/// C `fdb_blob_read` — reads blob data from storage.
#[no_mangle]
pub extern "C" fn fdb_blob_read(
    db_ptr: *mut core::ffi::c_void,
    blob: *mut CFlashdbBlob,
) -> usize {
    if blob.is_null() {
        return 0;
    }
    let saved_addr = unsafe { (*blob).saved_addr };
    let saved_len = unsafe { (*blob).saved_len };
    let buf = unsafe { (*blob).buf };
    let size = unsafe { (*blob).size };

    if saved_len == 0 || buf.is_null() || size == 0 {
        return 0;
    }

    let read_len = size.min(saved_len);
    let dst = unsafe { std::slice::from_raw_parts_mut(buf as *mut u8, read_len) };

    // Determine if this is a KVDB or TSDB by checking both registries
    let db_addr = db_ptr as usize;
    {
        let reg = KVDB_REGISTRY.lock().unwrap();
        if let Some(entry) = reg.get(&db_addr) {
            if entry.db.backend.is_some() {
                let be = entry.db.backend.as_deref().unwrap();
                if be.read(saved_addr, dst).is_ok() {
                    return read_len;
                }
            }
        }
    }
    {
        let reg = TSDB_REGISTRY.lock().unwrap();
        if let Some(entry) = reg.get(&db_addr) {
            if entry.db.backend.is_some() {
                let be = entry.db.backend.as_deref().unwrap();
                if be.read(saved_addr, dst).is_ok() {
                    return read_len;
                }
            }
        }
    }

    0
}

// ---- KVDB API ----

/// C `fdb_kvdb_init` — initializes a KVDB.
#[no_mangle]
pub extern "C" fn fdb_kvdb_init(
    db: *mut core::ffi::c_void,
    name: *const c_char,
    path: *const c_char,
    _default_kv: *const u8,
    user_data: *mut core::ffi::c_void,
) -> i32 {
    if db.is_null() || name.is_null() || path.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let name_str = unsafe { CStr::from_ptr(name) }.to_str().unwrap_or("");
    let path_str = unsafe { CStr::from_ptr(path) }.to_str().unwrap_or("");

    let db_addr = db as usize;
    let (sec_size, max_size, file_mode, not_formatable) = {
        let reg = KVDB_REGISTRY.lock().unwrap();
        if let Some(entry) = reg.get(&db_addr) {
            (entry.sec_size, entry.max_size, entry.file_mode, entry.not_formatable)
        } else {
            (0u32, 0u32, true, false)
        }
    };

    let mut kvdb = Box::new(Kvdb::new());
    if sec_size != 0 {
        kvdb.control(
            crate::FDB_KVDB_CTRL_SET_SEC_SIZE,
            &sec_size as *const u32 as *mut core::ffi::c_void,
        );
    }
    kvdb.control(
        crate::FDB_KVDB_CTRL_SET_FILE_MODE,
        &file_mode as *const bool as *mut core::ffi::c_void,
    );
    if max_size != 0 {
        kvdb.control(
            crate::FDB_KVDB_CTRL_SET_MAX_SIZE,
            &max_size as *const u32 as *mut core::ffi::c_void,
        );
    }
    kvdb.control(
        crate::FDB_KVDB_CTRL_SET_NOT_FORMAT,
        &not_formatable as *const bool as *mut core::ffi::c_void,
    );

    match kvdb.init(name_str, path_str, None, user_data) {
        Ok(()) => {
            let mut reg = KVDB_REGISTRY.lock().unwrap();
            reg.insert(
                db_addr,
                KvdbEntry {
                    db: kvdb,
                    sec_size,
                    max_size,
                    file_mode,
                    not_formatable,
                },
            );
            err_to_c(FdbErr::NoErr)
        }
        Err(e) => err_to_c(e),
    }
}

/// C `fdb_kvdb_deinit` — deinitializes a KVDB.
#[no_mangle]
pub extern "C" fn fdb_kvdb_deinit(db: *mut core::ffi::c_void) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let db_addr = db as usize;
    let mut reg = KVDB_REGISTRY.lock().unwrap();
    if let Some(mut entry) = reg.remove(&db_addr) {
        match entry.db.deinit() {
            Ok(()) => err_to_c(FdbErr::NoErr),
            Err(e) => err_to_c(e),
        }
    } else {
        err_to_c(FdbErr::InitFailed)
    }
}

/// C `fdb_kvdb_control` — controls a KVDB.
#[no_mangle]
pub extern "C" fn fdb_kvdb_control(db: *mut core::ffi::c_void, cmd: i32, arg: *mut core::ffi::c_void) {
    if db.is_null() {
        return;
    }
    let db_addr = db as usize;
    let mut reg = KVDB_REGISTRY.lock().unwrap();
    if let Some(entry) = reg.get_mut(&db_addr) {
        if entry.db.init_ok {
            entry.db.control(cmd, arg);
        } else {
            // Pre-init: store config params in the entry
            match cmd {
                crate::FDB_KVDB_CTRL_SET_SEC_SIZE => {
                    if !arg.is_null() {
                        entry.sec_size = unsafe { *(arg as *const u32) };
                    }
                }
                crate::FDB_KVDB_CTRL_SET_FILE_MODE => {
                    if !arg.is_null() {
                        entry.file_mode = unsafe { *(arg as *const bool) };
                    }
                }
                crate::FDB_KVDB_CTRL_SET_MAX_SIZE => {
                    if !arg.is_null() {
                        entry.max_size = unsafe { *(arg as *const u32) };
                    }
                }
                crate::FDB_KVDB_CTRL_SET_NOT_FORMAT => {
                    if !arg.is_null() {
                        entry.not_formatable = unsafe { *(arg as *const bool) };
                    }
                }
                crate::FDB_KVDB_CTRL_GET_SEC_SIZE => {
                    if !arg.is_null() {
                        unsafe { *(arg as *mut u32) = entry.sec_size };
                    }
                }
                crate::FDB_KVDB_CTRL_SET_LOCK | crate::FDB_KVDB_CTRL_SET_UNLOCK => {}
                _ => {}
            }
        }
    } else {
        // Not yet in registry — create a placeholder entry
        let mut entry = KvdbEntry {
            db: Box::new(Kvdb::new()),
            sec_size: 0,
            max_size: 0,
            file_mode: true,
            not_formatable: false,
        };
        match cmd {
            crate::FDB_KVDB_CTRL_SET_SEC_SIZE => {
                if !arg.is_null() {
                    entry.sec_size = unsafe { *(arg as *const u32) };
                }
            }
            crate::FDB_KVDB_CTRL_SET_FILE_MODE => {
                if !arg.is_null() {
                    entry.file_mode = unsafe { *(arg as *const bool) };
                }
            }
            crate::FDB_KVDB_CTRL_SET_MAX_SIZE => {
                if !arg.is_null() {
                    entry.max_size = unsafe { *(arg as *const u32) };
                }
            }
            crate::FDB_KVDB_CTRL_SET_NOT_FORMAT => {
                if !arg.is_null() {
                    entry.not_formatable = unsafe { *(arg as *const bool) };
                }
            }
            crate::FDB_KVDB_CTRL_GET_SEC_SIZE => {
                if !arg.is_null() {
                    unsafe { *(arg as *mut u32) = 0 };
                }
            }
            _ => {}
        }
        reg.insert(db_addr, entry);
    }
}

/// C `fdb_kvdb_check` — checks KVDB integrity.
#[no_mangle]
pub extern "C" fn fdb_kvdb_check(db: *mut core::ffi::c_void) -> i32 {
    if db.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let db_addr = db as usize;
    let mut reg = KVDB_REGISTRY.lock().unwrap();
    if let Some(entry) = reg.get_mut(&db_addr) {
        match entry.db.check() {
            Ok(()) => err_to_c(FdbErr::NoErr),
            Err(e) => err_to_c(e),
        }
    } else {
        err_to_c(FdbErr::InitFailed)
    }
}

/// C `fdb_kv_set` — sets a string KV.
#[no_mangle]
pub extern "C" fn fdb_kv_set(
    db: *mut core::ffi::c_void,
    key: *const c_char,
    value: *const c_char,
) -> i32 {
    if db.is_null() || key.is_null() {
        return err_to_c(FdbErr::KvNameErr);
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let db_addr = db as usize;
    let mut reg = KVDB_REGISTRY.lock().unwrap();
    if let Some(entry) = reg.get_mut(&db_addr) {
        if value.is_null() {
            match entry.db.kv_del(key_str) {
                Ok(()) => err_to_c(FdbErr::NoErr),
                Err(e) => err_to_c(e),
            }
        } else {
            let val_str = unsafe { CStr::from_ptr(value) }.to_str().unwrap_or("");
            match entry.db.kv_set(key_str, val_str) {
                Ok(()) => err_to_c(FdbErr::NoErr),
                Err(e) => err_to_c(e),
            }
        }
    } else {
        err_to_c(FdbErr::InitFailed)
    }
}

/// C `fdb_kv_get` — gets a string KV value.
#[no_mangle]
pub extern "C" fn fdb_kv_get(db: *mut core::ffi::c_void, key: *const c_char) -> *mut c_char {
    if db.is_null() || key.is_null() {
        return ptr::null_mut();
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let db_addr = db as usize;
    let mut reg = KVDB_REGISTRY.lock().unwrap();
    if let Some(entry) = reg.get_mut(&db_addr) {
        match entry.db.kv_get(key_str) {
            Some(val) => {
                let c_str = CString::new(val).unwrap_or_default();
                c_str.into_raw()
            }
            None => ptr::null_mut(),
        }
    } else {
        ptr::null_mut()
    }
}

/// C `fdb_kv_set_blob` — sets a blob KV (takes fdb_blob_t).
#[no_mangle]
pub extern "C" fn fdb_kv_set_blob(
