    blob: *mut CFlashdbBlob,
) -> *mut CFlashdbBlob {
    if kv.is_null() || blob.is_null() {
        return ptr::null_mut();
    }
    unsafe {
        (*blob).saved_meta_addr = (*kv).addr_start;
        (*blob).saved_addr = (*kv).addr_value;
        (*blob).saved_len = (*kv).value_len as usize;
    }
    blob
