/// C `fdb_kv_iterate` — iterates to the next KV.
#[no_mangle]
pub extern "C" fn fdb_kv_iterate(
    db: *mut core::ffi::c_void,
    itr: *mut CFlashdbKvIterator,
) -> bool {
    if db.is_null() || itr.is_null() {
        return false;
    }
    let db_addr = db as usize;
    let mut reg = KVDB_REGISTRY.lock().unwrap();
    if let Some(entry) = reg.get_mut(&db_addr) {
        let itr_ref = unsafe { &mut *itr };

        // Simple iteration: scan all KVs and return the one at index iterated_cnt
        let mut kv_list: Vec<KvInfo> = Vec::new();
        let mut kv = KvInfo::default();
        let mut found = false;
        entry.db.kv_iterator(&mut kv, "", &mut found, |_kv, _arg, _found| true);

        // Re-scan and collect all valid KVs
        kv_list.clear();
        let sec_hdr_sz = crate::kvdb::sector_hdr_data_size(entry.db.sec_size) as u32;
        let mut sec_addr = entry.db.oldest_addr;
        let mut traversed_len = 0u32;
        loop {
            traversed_len += entry.db.sec_size;
            let sector = match entry.db.read_sector_info(sec_addr, false) {
                Ok(s) => s,
                Err(_) => {
                    let next = entry.db.get_next_sector_addr(
                        &{
                            let mut s = crate::KvdbSecInfo::default();
                            s.addr = sec_addr;
                            s.combined = crate::SECTOR_NOT_COMBINED;
                            s
                        },
                        traversed_len,
                    );
                    if next == crate::FDB_FAILED_ADDR {
                        break;
                    }
                    sec_addr = next;
                    continue;
                }
            };

            if sector.store_status == crate::SectorStoreStatus::Using
                || sector.store_status == crate::SectorStoreStatus::Full
            {
                let mut kv_obj = KvInfo::default();
                kv_obj.addr_start = sector.addr + sec_hdr_sz;
                loop {
                    let _ = entry.db.read_kv(&mut kv_obj);
                    if kv_obj.crc_is_ok && kv_obj.status == crate::KvStatus::Write {
                        kv_list.push(kv_obj.clone());
                    }
                    let next = entry.db.get_next_kv_addr(&sector, &kv_obj);
                    if next == crate::FDB_FAILED_ADDR {
                        break;
                    }
                    kv_obj.addr_start = next;
                }
            }

            let next = entry.db.get_next_sector_addr(
                &{
                    let mut s = crate::KvdbSecInfo::default();
                    s.addr = sec_addr;
                    s.combined = sector.combined;
                    s
                },
                traversed_len,
            );
            if next == crate::FDB_FAILED_ADDR {
                break;
            }
            sec_addr = next;
        }

        let idx = itr_ref.iterated_cnt as usize;
        if idx < kv_list.len() {
            let c_kv = CFlashdbKv::from(&kv_list[idx]);
            itr_ref.curr_kv = c_kv;
            itr_ref.iterated_cnt += 1;
            itr_ref.iterated_obj_bytes += kv_list[idx].len as usize;
            itr_ref.iterated_value_bytes += kv_list[idx].value_len as usize;
            true
        } else {
            false
        }
    } else {
        false
    }
}

