/// C `fdb_tsdb_init` — initializes a TSDB.
#[no_mangle]
pub extern "C" fn fdb_tsdb_init(
    db: *mut core::ffi::c_void,
    name: *const c_char,
    path: *const c_char,
    get_time: Option<extern "C" fn() -> FdbTime>,
    max_len: usize,
    user_data: *mut core::ffi::c_void,
) -> i32 {
    if db.is_null() || name.is_null() || path.is_null() || get_time.is_none() {
        return err_to_c(FdbErr::InitFailed);
    }
    let name_str = unsafe { CStr::from_ptr(name) }.to_str().unwrap_or("");
    let path_str = unsafe { CStr::from_ptr(path) }.to_str().unwrap_or("");
    let get_time_fn = get_time.unwrap();

    let db_addr = db as usize;
    let (sec_size, max_size, file_mode, not_formatable) = {
        let reg = TSDB_REGISTRY.lock().unwrap();
        if let Some(entry) = reg.get(&db_addr) {
            (entry.sec_size, entry.max_size, entry.file_mode, entry.not_formatable)
        } else {
            (0u32, 0u32, true, false)
        }
    };

    let mut tsdb = Box::new(Tsdb::new());
    if sec_size != 0 {
        tsdb.control(
            crate::FDB_TSDB_CTRL_SET_SEC_SIZE,
            &sec_size as *const u32 as *mut core::ffi::c_void,
        );
    }
    tsdb.control(
        crate::FDB_TSDB_CTRL_SET_FILE_MODE,
        &file_mode as *const bool as *mut core::ffi::c_void,
    );
    if max_size != 0 {
        tsdb.control(
            crate::FDB_TSDB_CTRL_SET_MAX_SIZE,
            &max_size as *const u32 as *mut core::ffi::c_void,
        );
    }
    tsdb.control(
        crate::FDB_TSDB_CTRL_SET_NOT_FORMAT,
        &not_formatable as *const bool as *mut core::ffi::c_void,
    );

    match tsdb.init(name_str, path_str, get_time_fn, max_len, user_data) {
        Ok(()) => {
            let mut reg = TSDB_REGISTRY.lock().unwrap();
            reg.insert(
                db_addr,
                TsdbEntry {
                    db: tsdb,
                    sec_size,
                    max_size,
                    file_mode,
                    not_formatable,
                },
            );
            err_to_c(FdbErr::NoErr)
        }
        Err(e) => err_to_c(e),
    }
}

