/// C `fdb_tsdb_control` — controls a TSDB.
#[no_mangle]
pub extern "C" fn fdb_tsdb_control(db: *mut core::ffi::c_void, cmd: i32, arg: *mut core::ffi::c_void) {
    if db.is_null() {
        return;
    }
    let db_addr = db as usize;
    let mut reg = TSDB_REGISTRY.lock().unwrap();
    if let Some(entry) = reg.get_mut(&db_addr) {
        if entry.db.init_ok {
            entry.db.control(cmd, arg);
        } else {
            match cmd {
                crate::FDB_TSDB_CTRL_SET_SEC_SIZE => {
                    if !arg.is_null() {
                        entry.sec_size = unsafe { *(arg as *const u32) };
                    }
                }
                crate::FDB_TSDB_CTRL_SET_FILE_MODE => {
                    if !arg.is_null() {
                        entry.file_mode = unsafe { *(arg as *const bool) };
                    }
                }
                crate::FDB_TSDB_CTRL_SET_MAX_SIZE => {
                    if !arg.is_null() {
                        entry.max_size = unsafe { *(arg as *const u32) };
                    }
                }
                crate::FDB_TSDB_CTRL_SET_NOT_FORMAT => {
                    if !arg.is_null() {
                        entry.not_formatable = unsafe { *(arg as *const bool) };
                    }
                }
                crate::FDB_TSDB_CTRL_GET_SEC_SIZE => {
                    if !arg.is_null() {
                        unsafe { *(arg as *mut u32) = entry.sec_size };
                    }
                }
                crate::FDB_TSDB_CTRL_GET_ROLLOVER => {
                    if !arg.is_null() {
                        unsafe { *(arg as *mut bool) = entry.db.rollover };
                    }
                }
                crate::FDB_TSDB_CTRL_GET_LAST_TIME => {
                    if !arg.is_null() {
                        unsafe { *(arg as *mut FdbTime) = entry.db.last_time };
                    }
                }
                _ => {}
            }
        }
    } else {
        let mut entry = TsdbEntry {
            db: Box::new(Tsdb::new()),
            sec_size: 0,
            max_size: 0,
            file_mode: true,
            not_formatable: false,
        };
        match cmd {
            crate::FDB_TSDB_CTRL_SET_SEC_SIZE => {
                if !arg.is_null() {
                    entry.sec_size = unsafe { *(arg as *const u32) };
                }
            }
            crate::FDB_TSDB_CTRL_SET_FILE_MODE => {
                if !arg.is_null() {
                    entry.file_mode = unsafe { *(arg as *const bool) };
                }
            }
            crate::FDB_TSDB_CTRL_SET_MAX_SIZE => {
                if !arg.is_null() {
                    entry.max_size = unsafe { *(arg as *const u32) };
                }
            }
            crate::FDB_TSDB_CTRL_SET_NOT_FORMAT => {
                if !arg.is_null() {
                    entry.not_formatable = unsafe { *(arg as *const bool) };
                }
            }
            crate::FDB_TSDB_CTRL_GET_SEC_SIZE => {
                if !arg.is_null() {
                    unsafe { *(arg as *mut u32) = 0 };
                }
            }
            _ => {}
        }
        reg.insert(db_addr, entry);
    }
}

