/// C `fdb_tsl_set_status` — sets TSL status.
#[no_mangle]
pub extern "C" fn fdb_tsl_set_status(
    db: *mut core::ffi::c_void,
    tsl: *mut CFlashdbTsl,
    status: u32,
) -> i32 {
    if db.is_null() || tsl.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let tsl_status = match status {
        0 => TslStatus::Unused,
        1 => TslStatus::PreWrite,
        2 => TslStatus::Write,
        3 => TslStatus::UserStatus1,
        4 => TslStatus::Deleted,
        5 => TslStatus::UserStatus2,
        _ => TslStatus::Unused,
    };
    let tsl_ref = unsafe { &*tsl };
    let mut tsl_info = TslInfo {
        status: match tsl_ref.status {
            0 => TslStatus::Unused,
            1 => TslStatus::PreWrite,
            2 => TslStatus::Write,
            3 => TslStatus::UserStatus1,
            4 => TslStatus::Deleted,
            5 => TslStatus::UserStatus2,
            _ => TslStatus::Unused,
        },
        time: tsl_ref.time,
        log_len: tsl_ref.log_len,
        addr_index: tsl_ref.addr_index,
        addr_log: tsl_ref.addr_log,
    };
    let db_addr = db as usize;
    let mut reg = TSDB_REGISTRY.lock().unwrap();
    if let Some(entry) = reg.get_mut(&db_addr) {
        match entry.db.tsl_set_status(&tsl_info, tsl_status) {
            Ok(()) => err_to_c(FdbErr::NoErr),
            Err(e) => err_to_c(e),
        }
    } else {
        err_to_c(FdbErr::InitFailed)
    }
}

