/// C `fdb_tsl_to_blob` — converts a TSL to a blob.
#[no_mangle]
pub extern "C" fn fdb_tsl_to_blob(
    tsl: *mut CFlashdbTsl,
    blob: *mut CFlashdbBlob,
) -> *mut CFlashdbBlob {
    if tsl.is_null() || blob.is_null() {
        return ptr::null_mut();
    }
    unsafe {
        (*blob).saved_meta_addr = (*tsl).addr_index;
        (*blob).saved_addr = (*tsl).addr_log;
        (*blob).saved_len = (*tsl).log_len as usize;
    }
    blob
}

/// C `fdb_calc_crc32` — calculates CRC32.
#[no_mangle]
pub extern "C" fn fdb_calc_crc32(crc: u32, buf: *const core::ffi::c_void, size: usize) -> u32 {
    if buf.is_null() || size == 0 {
        return crc;
    }
    let data = unsafe { std::slice::from_raw_parts(buf as *const u8, size) };
    crate::calc_crc32(crc, data)
}

