    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let blob_ref = unsafe { &mut *blob };
    let buf_ptr = blob_ref.buf;
    let buf_size = blob_ref.size;

    if buf_ptr.is_null() || buf_size == 0 {
        return 0;
    }
    let buf = unsafe { std::slice::from_raw_parts_mut(buf_ptr as *mut u8, buf_size) };

    let db_addr = db as usize;
    let mut reg = KVDB_REGISTRY.lock().unwrap();
    if let Some(entry) = reg.get_mut(&db_addr) {
        let (read_len, value_len) = entry.db.get_kv(key_str, buf);
        if read_len > 0 {
            if let Some(kv_info) = entry.db.find_kv(key_str) {
                blob_ref.saved_meta_addr = kv_info.addr_start;
                blob_ref.saved_addr = kv_info.addr_value;
                blob_ref.saved_len = kv_info.value_len as usize;
            }
        }
        read_len
    } else {
        0
    }
}

