display.text:
//! FlashDB Rust — a faithful C-to-Rust translation of the FlashDB embedded database.
//!
//! Supported profile: POSIX file mode, KVDB + TSDB, FDB_WRITE_GRAN=1, signed 32-bit timestamp.

#![allow(warnings)]

mod crc;
mod ffi;
mod file_backend;
mod kvdb;
mod status;
mod tsdb;

// Re-export public types for tests
pub use crc::calc_crc32;
pub use file_backend::FileBackend;
pub use kvdb::Kvdb;
pub use tsdb::Tsdb;

/// Software version, must match C.
pub const FDB_SW_VERSION: &str = "2.2.99";
pub const FDB_SW_VERSION_NUM: u32 = 0x20299;

/// Write granularity in bits — fixed at 1 for this profile.
pub const FDB_WRITE_GRAN: usize = 1;

/// KV max name length.
pub const FDB_KV_NAME_MAX: usize = 64;

/// KV cache table size.
pub const FDB_KV_CACHE_TABLE_SIZE: usize = 64;

/// Sector cache table size.
pub const FDB_SECTOR_CACHE_TABLE_SIZE: usize = 8;

/// File cache table size.
pub const FDB_FILE_CACHE_TABLE_SIZE: usize = 2;

/// Erased byte value.
pub const FDB_BYTE_ERASED: u8 = 0xFF;

/// Written byte value.
pub const FDB_BYTE_WRITTEN: u8 = 0x00;

/// Data unused marker (when FDB_BYTE_ERASED == 0xFF).
pub const FDB_DATA_UNUSED: u32 = 0xFFFFFFFF;

/// Failed / invalid address.
pub const FDB_FAILED_ADDR: u32 = 0xFFFFFFFF;

/// String KV value max size for the legacy `fdb_kv_get` function.
pub const FDB_STR_KV_VALUE_MAX_SIZE: usize = 128;

/// GC minimum number of empty sectors.
pub const GC_MIN_EMPTY_SEC_NUM: usize = 1;

/// Sector remain threshold before full status.
pub const FDB_SEC_REMAIN_THRESHOLD_FACTOR: usize = 0; // computed at runtime

/// GC empty sector threshold.
pub const FDB_GC_EMPTY_SEC_THRESHOLD: usize = 1;

/// Sector magic word (`F`, `D`, `B`, `1`) = 0x30424446
pub const KVDB_SECTOR_MAGIC_WORD: u32 = 0x30424446;

/// KV magic word (`K`, `V`, `0`, `0`) = 0x3030564B
pub const KV_MAGIC_WORD: u32 = 0x3030564B;

/// TSDB sector magic word (`T`, `S`, `L`, `0`) = 0x304C5354
pub const TSDB_SECTOR_MAGIC_WORD: u32 = 0x304C5354;

/// Sector not combined value (when FDB_BYTE_ERASED == 0xFF).
pub const SECTOR_NOT_COMBINED: u32 = 0xFFFFFFFF;
pub const SECTOR_COMBINED: u32 = 0x00000000;

/// Align `size` up to `align` (align must be a power of 2).
#[inline]
pub const fn fdb_align(size: usize, align: usize) -> usize {
    ((size + align - 1) / align) * align
}

/// Align down.
#[inline]
pub const fn fdb_align_down(size: usize, align: usize) -> usize {
    (size / align) * align
}

/// Write-granularity alignment unit in bytes.
#[inline]
pub const fn wg_unit() -> usize {
    (FDB_WRITE_GRAN + 7) / 8
}

/// Align by write granularity.
#[inline]
pub const fn wg_align(size: usize) -> usize {
    fdb_align(size, wg_unit())
}

/// Align down by write granularity.
#[inline]
pub const fn wg_align_down(size: usize) -> usize {
    fdb_align_down(size, wg_unit())
}

/// Status table size in bytes.
/// For FDB_WRITE_GRAN == 1: (status_number * 1 + 7) / 8
/// For other: ((status_number - 1) * gran + 7) / 8
#[inline]
pub const fn status_table_size(status_number: usize) -> usize {
    if FDB_WRITE_GRAN == 1 {
        (status_number * FDB_WRITE_GRAN + 7) / 8
    } else {
        ((status_number - 1) * FDB_WRITE_GRAN + 7) / 8
    }
}

pub const FDB_STORE_STATUS_TABLE_SIZE: usize = status_table_size(FDB_SECTOR_STORE_STATUS_NUM);
pub const FDB_DIRTY_STATUS_TABLE_SIZE: usize = status_table_size(FDB_SECTOR_DIRTY_STATUS_NUM);
pub const KV_STATUS_TABLE_SIZE: usize = status_table_size(FDB_KV_STATUS_NUM);
pub const TSL_STATUS_TABLE_SIZE: usize = status_table_size(FDB_TSL_STATUS_NUM);

/// Number of sector store statuses.
pub const FDB_SECTOR_STORE_STATUS_NUM: usize = 4;
/// Number of sector dirty statuses.
pub const FDB_SECTOR_DIRTY_STATUS_NUM: usize = 4;
/// Number of KV statuses.
pub const FDB_KV_STATUS_NUM: usize = 6;
/// Number of TSL statuses.
pub const FDB_TSL_STATUS_NUM: usize = 6;

// ---- Error codes ----

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum FdbErr {
    NoErr = 0,
    EraseErr = 1,
    ReadErr = 2,
    WriteErr = 3,
    KvNameErr = 4,
    KvNameExist = 5,
    SavedFull = 6,
    InitFailed = 7,
}

impl FdbErr {
    pub fn from_c(val: u32) -> Option<Self> {
        match val {
            0 => Some(FdbErr::NoErr),
            1 => Some(FdbErr::EraseErr),
            2 => Some(FdbErr::ReadErr),
            3 => Some(FdbErr::WriteErr),
            4 => Some(FdbErr::KvNameErr),
            5 => Some(FdbErr::KvNameExist),
            6 => Some(FdbErr::SavedFull),
            7 => Some(FdbErr::InitFailed),
            _ => None,
        }
    }
}

// ---- Status enums ----

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum KvStatus {
    Unused = 0,
    PreWrite = 1,
    Write = 2,
    PreDelete = 3,
    Deleted = 4,
    ErrHdr = 5,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum TslStatus {
    Unused = 0,
    PreWrite = 1,
    Write = 2,
    UserStatus1 = 3,
    Deleted = 4,
    UserStatus2 = 5,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum SectorStoreStatus {
    Unused = 0,
    Empty = 1,
    Using = 2,
    Full = 3,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum SectorDirtyStatus {
    Unused = 0,
    False = 1,
    True = 2,
    Gc = 3,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(C)]
pub enum DbType {
    Kv = 0,
    Ts = 1,
}

/// Timestamp type — 32-bit signed for this profile.
pub type FdbTime = i32;

/// Callback type for getting current time.
pub type GetTimeFn = fn() -> FdbTime;

/// Lock callback.
pub type LockFn = fn(*mut core::ffi::c_void);

/// Unlock callback.
pub type UnlockFn = fn(*mut core::ffi::c_void);

/// TSL iteration callback. Returns `true` to stop iteration.
pub type TslCb = fn(&TslInfo, *mut core::ffi::c_void) -> bool;

// ---- Blob ----

#[derive(Debug, Clone)]
pub struct Blob {
    pub buf: Vec<u8>,
    pub size: usize,
    pub saved_meta_addr: u32,
    pub saved_addr: u32,
    pub saved_len: usize,
}

impl Blob {
    pub fn new(value_buf: &[u8]) -> Self {
        Blob {
            buf: value_buf.to_vec(),
            size: value_buf.len(),
            saved_meta_addr: 0,
            saved_addr: 0,
            saved_len: 0,
        }
    }

    pub fn make(&mut self, value_buf: &[u8], buf_len: usize) -> &mut Self {
        self.buf = value_buf.to_vec();
        self.size = buf_len;
        self
    }

    pub fn read_from_storage(
        &mut self,
        backend: &mut dyn StorageBackend,
        addr: u32,
        len: usize,
    ) -> usize {
        let read_len = self.size.min(len);
        if read_len == 0 {
            return 0;
        }
        let mut tmp = vec![0u8; read_len];
        match backend.read(addr, &mut tmp) {
            Ok(()) => {
                let copy_len = read_len.min(self.buf.len());
                self.buf[..copy_len].copy_from_slice(&tmp[..copy_len]);
                read_len
            }
            Err(_) => 0,
        }
    }
}

// ---- KV Info (in-memory) ----

#[derive(Debug, Clone)]
pub struct KvInfo {
    pub status: KvStatus,
    pub crc_is_ok: bool,
    pub name_len: u8,
    pub magic: u32,
    pub len: u32,
    pub value_len: u32,
    pub name: [u8; FDB_KV_NAME_MAX],
    pub addr_start: u32,
    pub addr_value: u32,
}

impl Default for KvInfo {
    fn default() -> Self {
        KvInfo {
            status: KvStatus::Unused,
            crc_is_ok: false,
            name_len: 0,
            magic: 0,
            len: 0,
            value_len: 0,
            name: [0u8; FDB_KV_NAME_MAX],
            addr_start: FDB_FAILED_ADDR,
            addr_value: 0,
        }
    }
}

// ---- TSL Info (in-memory) ----

#[derive(Debug, Clone)]
pub struct TslInfo {
    pub status: TslStatus,
    pub time: FdbTime,
    pub log_len: u32,
    pub addr_index: u32,
    pub addr_log: u32,
}

impl Default for TslInfo {
    fn default() -> Self {
        TslInfo {
            status: TslStatus::Unused,
            time: 0,
            log_len: 0,
            addr_index: FDB_FAILED_ADDR,
            addr_log: FDB_DATA_UNUSED,
        }
    }
}

// ---- KVDB Sector Info (in-memory) ----

#[derive(Debug, Clone)]
pub struct KvdbSecInfo {
    pub check_ok: bool,
    pub store_status: SectorStoreStatus,
    pub dirty_status: SectorDirtyStatus,
    pub addr: u32,
    pub magic: u32,
    pub combined: u32,
    pub remain: usize,
    pub empty_kv: u32,
}

impl Default for KvdbSecInfo {
    fn default() -> Self {
        KvdbSecInfo {
            check_ok: false,
            store_status: SectorStoreStatus::Unused,
            dirty_status: SectorDirtyStatus::Unused,
            addr: 0,
            magic: 0,
            combined: SECTOR_NOT_COMBINED,
            remain: 0,
            empty_kv: FDB_FAILED_ADDR,
        }
    }
}

// ---- TSDB Sector Info (in-memory) ----

#[derive(Debug, Clone)]
pub struct TsdbSecInfo {
    pub check_ok: bool,
    pub status: SectorStoreStatus,
    pub addr: u32,
    pub magic: u32,
    pub start_time: FdbTime,
    pub end_time: FdbTime,
    pub end_idx: u32,
    pub end_info_stat: [TslStatus; 2],
    pub remain: usize,
    pub empty_idx: u32,
    pub empty_data: u32,
}

impl Default for TsdbSecInfo {
    fn default() -> Self {
        TsdbSecInfo {
            check_ok: false,
            status: SectorStoreStatus::Unused,
            addr: 0,
            magic: 0,
            start_time: 0x7FFFFFFF,
            end_time: 0,
            end_idx: 0,
            end_info_stat: [TslStatus::Unused, TslStatus::Unused],
            remain: 0,
            empty_idx: 0,
            empty_data: 0,
        }
    }
}

// ---- Default KV ----

#[derive(Debug, Clone)]
pub struct DefaultKvNode {
    pub key: String,
    pub value: Vec<u8>,
    pub value_len: usize,
}

#[derive(Debug, Clone, Default)]
pub struct DefaultKv {
    pub kvs: Vec<DefaultKvNode>,
}

// ---- Storage Backend Trait ----

pub trait StorageBackend {
    fn read(&self, addr: u32, buf: &mut [u8]) -> Result<(), FdbErr>;
    fn write(&self, addr: u32, data: &[u8], sync: bool) -> Result<(), FdbErr>;
    fn erase(&self, addr: u32, size: usize) -> Result<(), FdbErr>;
}

// ---- KVDB Control Commands ----

pub const FDB_KVDB_CTRL_SET_SEC_SIZE: i32 = 0x00;
pub const FDB_KVDB_CTRL_GET_SEC_SIZE: i32 = 0x01;
pub const FDB_KVDB_CTRL_SET_LOCK: i32 = 0x02;
pub const FDB_KVDB_CTRL_SET_UNLOCK: i32 = 0x03;
pub const FDB_KVDB_CTRL_SET_FILE_MODE: i32 = 0x09;
pub const FDB_KVDB_CTRL_SET_MAX_SIZE: i32 = 0x0A;
pub const FDB_KVDB_CTRL_SET_NOT_FORMAT: i32 = 0x0B;

// ---- TSDB Control Commands ----

pub const FDB_TSDB_CTRL_SET_SEC_SIZE: i32 = 0x00;
pub const FDB_TSDB_CTRL_GET_SEC_SIZE: i32 = 0x01;
pub const FDB_TSDB_CTRL_SET_LOCK: i32 = 0x02;
pub const FDB_TSDB_CTRL_SET_UNLOCK: i32 = 0x03;
pub const FDB_TSDB_CTRL_SET_ROLLOVER: i32 = 0x04;
pub const FDB_TSDB_CTRL_GET_ROLLOVER: i32 = 0x05;
pub const FDB_TSDB_CTRL_GET_LAST_TIME: i32 = 0x06;
pub const FDB_TSDB_CTRL_SET_FILE_MODE: i32 = 0x09;
pub const FDB_TSDB_CTRL_SET_MAX_SIZE: i32 = 0x0A;
pub const FDB_TSDB_CTRL_SET_NOT_FORMAT: i32 = 0x0B;

