/// C `fdb_kvdb_init` — initializes a KVDB.
#[no_mangle]
pub extern "C" fn fdb_kvdb_init(
    db: *mut core::ffi::c_void,
    name: *const c_char,
    path: *const c_char,
    _default_kv: *const u8,
    user_data: *mut core::ffi::c_void,
) -> i32 {
    if db.is_null() || name.is_null() || path.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let name_str = unsafe { CStr::from_ptr(name) }.to_str().unwrap_or("");
    let path_str = unsafe { CStr::from_ptr(path) }.to_str().unwrap_or("");

    let db_addr = db as usize;
    let (sec_size, max_size, file_mode, not_formatable) = {
        let reg = KVDB_REGISTRY.lock().unwrap();
        if let Some(entry) = reg.get(&db_addr) {
            (
                entry.sec_size,
                entry.max_size,
                entry.file_mode,
                entry.not_formatable,
            )
        } else {
            (0u32, 0u32, true, false)
        }
    };

    let mut kvdb = Box::new(Kvdb::new());
    if sec_size != 0 {
        kvdb.control(
            crate::FDB_KVDB_CTRL_SET_SEC_SIZE,
            &sec_size as *const u32 as *mut core::ffi::c_void,
        );
    }
    kvdb.control(
        crate::FDB_KVDB_CTRL_SET_FILE_MODE,
        &file_mode as *const bool as *mut core::ffi::c_void,
    );
    if max_size != 0 {
        kvdb.control(
            crate::FDB_KVDB_CTRL_SET_MAX_SIZE,
            &max_size as *const u32 as *mut core::ffi::c_void,
        );
    }
    kvdb.control(
        crate::FDB_KVDB_CTRL_SET_NOT_FORMAT,
        &not_formatable as *const bool as *mut core::ffi::c_void,
    );

    match kvdb.init(name_str, path_str, None, user_data) {
        Ok(()) => {
            let mut reg = KVDB_REGISTRY.lock().unwrap();
            reg.insert(
                db_addr,
                KvdbEntry {
                    db: kvdb,
                    sec_size,
                    max_size,
                    file_mode,
                    not_formatable,
                },
            );
            err_to_c(FdbErr::NoErr)
        }
        Err(e) => err_to_c(e),
    }
}

