/// C `fdb_kvdb_control` — controls a KVDB.
#[no_mangle]
pub extern "C" fn fdb_kvdb_control(
    db: *mut core::ffi::c_void,
    cmd: i32,
    arg: *mut core::ffi::c_void,
) {
    if db.is_null() {
        return;
    }
    let db_addr = db as usize;
    let mut reg = KVDB_REGISTRY.lock().unwrap();
    if let Some(entry) = reg.get_mut(&db_addr) {
        if entry.db.init_ok {
            entry.db.control(cmd, arg);
        } else {
            // Pre-init: store config params in the entry
            match cmd {
                crate::FDB_KVDB_CTRL_SET_SEC_SIZE => {
                    if !arg.is_null() {
                        entry.sec_size = unsafe { *(arg as *const u32) };
                    }
                }
                crate::FDB_KVDB_CTRL_SET_FILE_MODE => {
                    if !arg.is_null() {
                        entry.file_mode = unsafe { *(arg as *const bool) };
                    }
                }
                crate::FDB_KVDB_CTRL_SET_MAX_SIZE => {
                    if !arg.is_null() {
                        entry.max_size = unsafe { *(arg as *const u32) };
                    }
                }
                crate::FDB_KVDB_CTRL_SET_NOT_FORMAT => {
                    if !arg.is_null() {
                        entry.not_formatable = unsafe { *(arg as *const bool) };
                    }
                }
                crate::FDB_KVDB_CTRL_GET_SEC_SIZE => {
                    if !arg.is_null() {
                        unsafe { *(arg as *mut u32) = entry.sec_size };
                    }
                }
                crate::FDB_KVDB_CTRL_SET_LOCK | crate::FDB_KVDB_CTRL_SET_UNLOCK => {}
                _ => {}
            }
        }
    } else {
        // Not yet in registry — create a placeholder entry
        let mut entry = KvdbEntry {
            db: Box::new(Kvdb::new()),
            sec_size: 0,
            max_size: 0,
            file_mode: true,
            not_formatable: false,
        };
        match cmd {
            crate::FDB_KVDB_CTRL_SET_SEC_SIZE => {
                if !arg.is_null() {
                    entry.sec_size = unsafe { *(arg as *const u32) };
                }
            }
            crate::FDB_KVDB_CTRL_SET_FILE_MODE => {
                if !arg.is_null() {
                    entry.file_mode = unsafe { *(arg as *const bool) };
                }
            }
            crate::FDB_KVDB_CTRL_SET_MAX_SIZE => {
                if !arg.is_null() {
                    entry.max_size = unsafe { *(arg as *const u32) };
                }
            }
            crate::FDB_KVDB_CTRL_SET_NOT_FORMAT => {
                if !arg.is_null() {
                    entry.not_formatable = unsafe { *(arg as *const bool) };
                }
            }
            crate::FDB_KVDB_CTRL_GET_SEC_SIZE => {
                if !arg.is_null() {
                    unsafe { *(arg as *mut u32) = 0 };
                }
            }
            _ => {}
        }
        reg.insert(db_addr, entry);
    }
}

