pub extern "C" fn fdb_kv_get_obj(
    db: *mut core::ffi::c_void,
    key: *const c_char,
    kv: *mut CFlashdbKv,
) -> *mut CFlashdbKv {
    if db.is_null() || key.is_null() || kv.is_null() {
        return ptr::null_mut();
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let db_addr = db as usize;
    let mut reg = KVDB_REGISTRY.lock().unwrap();
    if let Some(entry) = reg.get_mut(&db_addr) {
        match entry.db.find_kv(key_str) {
            Some(kv_info) => {
                let c_kv = CFlashdbKv::from(&kv_info);
                unsafe {
                    *kv = c_kv;
                }
                kv
            }
            None => ptr::null_mut(),
        }
    } else {
        ptr::null_mut()
    }
}

