pub extern "C" fn fdb_kv_set_blob(
    db: *mut core::ffi::c_void,
    key: *const c_char,
    blob: *mut CFlashdbBlob,
) -> i32 {
    ensure_panic_hook();
    eprintln!("[FFI] fdb_kv_set_blob called");
    if db.is_null() || key.is_null() || blob.is_null() {
        return err_to_c(FdbErr::KvNameErr);
    }
    let key_str = unsafe { CStr::from_ptr(key) }.to_str().unwrap_or("");
    let blob_ref = unsafe { &*blob };
    let data = if blob_ref.buf.is_null() || blob_ref.size == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(blob_ref.buf as *const u8, blob_ref.size) }
    };
    let db_addr = db as usize;
    let mut reg = KVDB_REGISTRY.lock().unwrap();
    if let Some(entry) = reg.get_mut(&db_addr) {
        match entry.db.kv_set_blob(key_str, data) {
            Ok(()) => err_to_c(FdbErr::NoErr),
            Err(e) => err_to_c(e),
        }
    } else {
        err_to_c(FdbErr::InitFailed)
    }
}

