#include <stdio.h>
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

#define FDB_KV_NAME_MAX 64
#define FDB_KV_CACHE_TABLE_SIZE 64
#define FDB_SECTOR_CACHE_TABLE_SIZE 8

typedef enum {
    FDB_KV_UNUSED = 0, FDB_KV_PRE_WRITE = 1, FDB_KV_WRITE = 2,
    FDB_KV_PRE_DELETE = 3, FDB_KV_DELETED = 4, FDB_KV_ERR_HDR = 5,
} fdb_kv_status_t;

typedef enum {
    FDB_SECTOR_STORE_UNUSED = 0, FDB_SECTOR_STORE_EMPTY = 1,
    FDB_SECTOR_STORE_USING = 2, FDB_SECTOR_STORE_FULL = 3,
} fdb_sector_store_status_t;

typedef enum {
    FDB_SECTOR_DIRTY_UNUSED = 0, FDB_SECTOR_DIRTY_FALSE = 1,
    FDB_SECTOR_DIRTY_TRUE = 2, FDB_SECTOR_DIRTY_GC = 3,
} fdb_sector_dirty_status_t;

typedef int32_t fdb_time_t;
typedef void (*fdb_lock_t)(void *);
typedef void (*fdb_unlock_t)(void *);
typedef fdb_time_t (*fdb_get_time_t)(void);

struct fdb_kv {
    fdb_kv_status_t status;
    bool crc_is_ok;
    uint8_t name_len;
    uint32_t magic;
    uint32_t len;
    uint32_t value_len;
    char name[FDB_KV_NAME_MAX];
    struct { uint32_t start; uint32_t value; } addr;
};

struct kvdb_sec_info {
    bool check_ok;
    fdb_sector_store_status_t store_status;
    fdb_sector_dirty_status_t dirty_status;
    uint32_t addr;
    uint32_t magic;
    uint32_t combined;
    size_t remain;
    uint32_t empty_kv;
};

struct fdb_db {
    const char *name;
    fdb_lock_t lock;
    fdb_unlock_t unlock;
    void *user_data;
    uint32_t sec_size;
    uint32_t max_size;
    bool file_mode;
    bool not_formatable;
    bool init_ok;
    uint32_t oldest_addr;
};

struct kv_cache_node {
    uint32_t addr;
    struct kvdb_sec_info sector;
    struct fdb_kv kv;
};

struct fdb_kvdb {
    struct fdb_db parent;
    struct kvdb_sec_info cur_sector;
    struct fdb_kv cur_kv;
    bool gc_request;
    bool in_recovery_check;
    struct fdb_kv last_kv;
    bool last_is_complete_del;
    struct kv_cache_node kv_cache_table[FDB_KV_CACHE_TABLE_SIZE];
    struct kv_cache_node sector_cache_table[FDB_SECTOR_CACHE_TABLE_SIZE];
    void *user_data;
};

int main() {
    printf("=== struct fdb_db ===\n");
    printf("sizeof = %zu\n", sizeof(struct fdb_db));
    printf("offsetof(name) = %zu\n", offsetof(struct fdb_db, name));
    printf("offsetof(lock) = %zu\n", offsetof(struct fdb_db, lock));
    printf("offsetof(unlock) = %zu\n", offsetof(struct fdb_db, unlock));
    printf("offsetof(user_data) = %zu\n", offsetof(struct fdb_db, user_data));
    printf("offsetof(sec_size) = %zu\n", offsetof(struct fdb_db, sec_size));
    printf("offsetof(max_size) = %zu\n", offsetof(struct fdb_db, max_size));
    printf("offsetof(file_mode) = %zu\n", offsetof(struct fdb_db, file_mode));
    printf("offsetof(not_formatable) = %zu\n", offsetof(struct fdb_db, not_formatable));
    printf("offsetof(init_ok) = %zu\n", offsetof(struct fdb_db, init_ok));
    printf("offsetof(oldest_addr) = %zu\n", offsetof(struct fdb_db, oldest_addr));

    printf("\n=== struct fdb_kvdb ===\n");
    printf("sizeof = %zu\n", sizeof(struct fdb_kvdb));
    printf("offsetof(parent) = %zu\n", offsetof(struct fdb_kvdb, parent));
    printf("offsetof(parent.oldest_addr) = %zu\n", offsetof(struct fdb_kvdb, parent.oldest_addr));

    return 0;
}
EOF
