    ensure_panic_hook();
    eprintln!("[FFI] fdb_kvdb_deinit called: db={:?}", db);
    if db.is_null() {
        return err_to_c(FdbErr::InitFailed);
    }
    let db_addr = db as usize;
    let mut reg = KVDB_REGISTRY.lock().unwrap();
    if let Some(mut entry) = reg.remove(&db_addr) {
        match entry.db.deinit() {
            Ok(()) => err_to_c(FdbErr::NoErr),
            Err(e) => err_to_c(e),
